_LogExcInfo = (
    bool
    | BaseException
    | tuple[type[BaseException], BaseException, TracebackType | None]
    | tuple[None, None, None]
    | None
)


class _LogKwargs(TypedDict, total=False):
    exc_info: _LogExcInfo
    stack_info: bool
    stacklevel: int
    extra: Mapping[str, object] | None


def _safe_worker_log(level: int, message: str, *args: object, **kwargs: Unpack[_LogKwargs]) -> None:
    stream = getattr(sys, "stderr", None)
    if bool(getattr(stream, "closed", False)):
        return
    previous_raise_exceptions = logging.raiseExceptions
    logging.raiseExceptions = False
    try:
        LOGGER.log(level, message, *args, **kwargs)
    finally:
        logging.raiseExceptions = previous_raise_exceptions


class _AsyncioConnectionResetFilter(logging.Filter):
    """Suppress verbose ConnectionResetError tracebacks coming from asyncio proactor callbacks.

    These errors are typically raised when the remote peer forcibly closes a connection
    and surface as noisy ERROR-level callbacks in the stdlib proactor. We filter
    them here to avoid log spam while preserving other asyncio logs.
    """

    def filter(self, record: logging.LogRecord) -> bool:  # pragma: no cover - small runtime helper
        try:
            msg = record.getMessage() or ""
            if "ConnectionResetError" in msg and "_ProactorBasePipeTransport._call_connection_lost" in msg:
                return False
        except Exception:
            pass
        if record.exc_info:
            exc_type = record.exc_info[0]
            if exc_type and getattr(exc_type, "__name__", "") == "ConnectionResetError":
                return False
        return True


# Attach the filter to the asyncio logger so stdlib proactor noise is reduced.
try:
    _ASYNCIO_LOGGER.addFilter(_AsyncioConnectionResetFilter())
except Exception:
    LOGGER.debug("Failed to attach asyncio ConnectionResetError filter; continuing without it.", exc_info=True)
