def _normalize_fx_market_candidate(text: Any) -> str:
    raw = re.sub(r"[^A-Z0-9/ ]+", "", str(text or "").upper())
    raw = re.sub(r"\s+", " ", raw).strip()
    if not raw:
        return ""

    compact = raw.replace(" ", "")
    has_otc = "OTC" in compact
    # The broker's small selector glyph regularly turns the final ``C`` in
    # ``OTC`` into ``E`` (for example ``EUR/NZDOTE``).  Preserve the OTC
    # namespace only when the selector contains one valid FX pair followed by
    # exactly one three-glyph suffix that differs from OTC by at most one
    # glyph.  Keeping this pair-anchored and length-bounded avoids promoting
    # unrelated trailing toolbar text to an OTC instrument.
    pair_with_suffix = re.fullmatch(r"([A-Z]{3})/?([A-Z]{3})([A-Z0-9]{3})", compact)
    if pair_with_suffix:
        left, right, suffix = pair_with_suffix.groups()
        suffix_distance = sum(actual != expected for actual, expected in zip(suffix, "OTC", strict=True))
        if (
            left in _FX_CURRENCY_CODES
            and right in _FX_CURRENCY_CODES
            and left != right
            and suffix_distance <= 1
        ):
            has_otc = True
    compact = compact.replace("OTC", "")
    pair = ""
    slash_match = re.search(r"([A-Z]{3})/([A-Z]{3})", compact)
    if slash_match:
        left, right = slash_match.group(1), slash_match.group(2)
        if left in _FX_CURRENCY_CODES and right in _FX_CURRENCY_CODES and left != right:
            pair = f"{left}/{right}"
    if not pair:
        letters = re.sub(r"[^A-Z]", "", compact)
        for index in range(0, max(0, len(letters) - 5)):
            left = letters[index:index + 3]
            right = letters[index + 3:index + 6]
            if left in _FX_CURRENCY_CODES and right in _FX_CURRENCY_CODES and left != right:
                pair = f"{left}/{right}"
                break
    if not pair:
        return ""
    return f"{pair} OTC" if has_otc else pair


def _complete_fx_market_candidate_v3(text: Any) -> str:
    """Return only a complete FX identity, preserving an explicit OTC suffix."""

    market = _normalize_fx_market_candidate(text)
    return market if re.fullmatch(r"[A-Z]{3}/[A-Z]{3}(?: OTC)?", market) else ""


def _identity_text_fx_candidates_v3(text: Any) -> list[str]:
    """Extract boundary-delimited FX symbols from a window/chart identity string."""

    raw = re.sub(r"\s+", " ", str(text or "").upper()).strip()
    if not raw:
        return []
    codes = "|".join(sorted(_FX_CURRENCY_CODES))
    pattern = re.compile(
        rf"(?<![A-Z])({codes})\s*(?:[/._:\-]\s*)?({codes})(?:\s+(OTC)|\s*(OTC))?(?![A-Z])"
    )
    candidates: list[str] = []
    for match in pattern.finditer(raw):
        left, right = match.group(1), match.group(2)
        if left == right:
            continue
        market = f"{left}/{right}"
        if match.group(3) or match.group(4):
            market += " OTC"
        if market not in candidates:
            candidates.append(market)
    return candidates


def _identity_text_timeframe_candidates_v3(text: Any) -> list[str]:
    """Extract supported chart intervals without interpreting arbitrary numbers."""

    raw = str(text or "").upper()
    if not raw:
        return []
    aliases = {
        "1M": "M1",
        "3M": "M3",
        "5M": "M5",
        "15M": "M15",
        "30M": "M30",
        "1H": "H1",
        "4H": "H4",
        "1D": "D1",
    }
    labels: list[str] = []
    for token in re.findall(
        r"(?<![A-Z0-9])(?:M1|M3|M5|M15|M30|H1|H4|D1|1M|3M|5M|15M|30M|1H|4H|1D)(?![A-Z0-9])",
        raw,
    ):
        label = aliases.get(token, token)
        if label in _TIMEFRAME_LABELS and label not in labels:
            labels.append(label)
    return labels
