def _now_iso() -> str:
    return utc_now_iso()


def _now_epoch() -> float:
    return float(time.time())


def _epoch_to_utc_iso(epoch: float) -> str:
    return datetime.fromtimestamp(float(epoch), tz=timezone.utc).isoformat()


def _clip01(value: Any) -> float:
    try:
        number = float(value or 0.0)
    except (TypeError, ValueError):
        return 0.0
    return float(max(0.0, min(1.0, number)))


def _array_mean_float(value: Any) -> float:
    return float(np.asarray(value, dtype=np.float32).mean())


def _timeframe_seconds(timeframe: Any, default: int = 300) -> int:
    label = str(timeframe or "").strip().upper()
    seconds = {
        "S3": 3,
        "S15": 15,
        "S30": 30,
        "M1": 60,
        "M3": 180,
        "M5": 300,
        "M15": 900,
        "M30": 1800,
        "H1": 3600,
        "H4": 14400,
        "D1": 86400,
    }.get(label, int(default))
    return max(1, int(seconds))


def _normalize_high_frequency_timeframe(value: Any) -> str:
    label = str(value or "").strip().upper()
    return label if label in _HIGH_FREQUENCY_SUPPORTED_TIMEFRAMES else _HIGH_FREQUENCY_TIMEFRAME


def _high_frequency_profile_expiry_seconds(timeframe: Any) -> int:
    return _HIGH_FREQUENCY_M1_EXPIRY_SEC if _normalize_high_frequency_timeframe(timeframe) == "M1" else _HIGH_FREQUENCY_FIXED_EXPIRY_SEC


