def _compact_live_state_observability_value(value: Any, *, depth: int = 0) -> Any:
    if depth > _COMPACT_LIVE_STATE_MAX_OBSERVABILITY_DEPTH:
        return str(value)[:_COMPACT_LIVE_STATE_MAX_STRING_CHARS]
    if isinstance(value, Mapping):
        result: dict[str, Any] = {}
        mapping_value = cast(Mapping[Any, Any], value)
        role = str(mapping_value.get("role") or "").lower()
        is_forecast_mapping = bool(
            "lstm_forecast" in role
            or "forecast_path" in mapping_value
            or "forecast_candles" in mapping_value
        )
        for key, item in mapping_value.items():
            text_key = str(key)
            if text_key in _PACKET_SELF_REFERENCE_KEYS or text_key in _COMPACT_LIVE_STATE_HEAVY_DIAGNOSTIC_KEYS:
                continue
            if is_forecast_mapping and text_key in {
                "forecast_path",
                "forecast_candles",
                "forecast_band_points",
                "line_points",
                "points",
            } and isinstance(item, Sequence) and not isinstance(item, (str, bytes, bytearray)):
                items = list(cast(Sequence[Any], item))
                if text_key in {"forecast_path", "forecast_candles"}:
                    mapping_items = [
                        cast(Mapping[str, Any], row)
                        for row in items
                        if isinstance(row, Mapping)
                    ]
                    mapping_items.sort(key=lambda row: int(_float_or(row.get("step"), 0.0)))
                    items = mapping_items[:12]
                else:
                    items = items[:64]
                result[text_key] = [
                    _compact_live_state_observability_value(row, depth=depth + 1)
                    for row in items
                ]
                continue
            result[text_key] = _compact_live_state_observability_value(item, depth=depth + 1)
        return result
    if isinstance(value, Sequence) and not isinstance(value, (str, bytes, bytearray)):
        items = list(cast(Sequence[Any], value))
        if len(items) > _COMPACT_LIVE_STATE_MAX_SEQUENCE_ITEMS:
            items = items[-_COMPACT_LIVE_STATE_MAX_SEQUENCE_ITEMS:]
        return [_compact_live_state_observability_value(item, depth=depth + 1) for item in items]
    if isinstance(value, str) and len(value) > _COMPACT_LIVE_STATE_MAX_STRING_CHARS:
        return value[:_COMPACT_LIVE_STATE_MAX_STRING_CHARS]
    return value


_ORDER_POSITIONING_SOURCE_SNAPSHOT_LIMIT = 24


def _compact_order_positioning_sources_v3(value: Any) -> dict[str, Any]:
    """Keep one bounded, current-frame source snapshot without history growth."""

    if not isinstance(value, Mapping):
        return {}
    source = cast(Mapping[str, Any], value)
    frame_id = int(_float_or(source.get("frame_id"), 0.0) or 0)
    rows = _sequence_of_mappings(source.get("objects"))[
        :_ORDER_POSITIONING_SOURCE_SNAPSHOT_LIMIT
    ]
    if frame_id <= 0 or not rows:
        return {}
    return {
        "schema_version": "PG_ORDER_POSITIONING_SOURCES_V3",
        "frame_id": frame_id,
        # Compact every row independently so the general eight-item sequence
        # cap cannot silently discard valid source zones from this bounded set.
        "objects": [
            _compact_live_state_observability_value(row)
            for row in rows
        ],
    }


