def _compact_live_state_sidecar_payload(payload: Mapping[str, Any]) -> dict[str, Any]:
    compact: dict[str, Any] = {}
    for key in _COMPACT_LIVE_STATE_SIDECAR_KEYS:
        value = payload.get(key)
        if value not in (None, "", [], {}):
            compact[key] = value
    if "tracking_summary" in compact:
        compact["tracking_summary"] = _compact_live_state_market_payload(compact["tracking_summary"])
    if "latest_signal" in compact:
        compact["latest_signal"] = _compact_live_state_latest_signal_payload(compact["latest_signal"])
    if "model_council_result" in compact:
        compact["model_council_result"] = _compact_live_state_council_result(compact["model_council_result"])
    for packet_key in ("model_council_packet", "execution_packet", "latest_model_council_packet", "latest_execution_packet"):
        packet = compact.get(packet_key)
        if isinstance(packet, Mapping):
            compact[packet_key] = _compact_live_state_execution_packet(cast(Mapping[str, Any], packet))
    current_packet: dict[str, Any] | None = None
    for packet_key in ("latest_execution_packet", "execution_packet", "latest_model_council_packet", "model_council_packet"):
        packet = compact.get(packet_key)
        if isinstance(packet, Mapping):
            current_packet = dict(cast(Mapping[str, Any], packet))
            break
    for packet_key in ("model_council_packet", "execution_packet", "latest_model_council_packet"):
        compact.pop(packet_key, None)
    if current_packet:
        compact["latest_execution_packet"] = current_packet
        compact["execution_packet_present"] = True
    return cast(
        dict[str, Any],
        _strip_private_shadow_forecast_fields_v3(compact),
    )


def _first_mapping(value: Any) -> dict[str, Any]:
    items = _sequence_of_mappings(value)
    return items[0] if items else {}


def _upper_action(value: Any, fallback: str = "HOLD") -> str:
    text = str(value or fallback).strip().upper()
    return text or str(fallback or "HOLD").upper()


def _opposite_action(value: Any) -> str:
    action = _upper_action(value, fallback="HOLD")
    if action == "BUY":
        return "SELL"
    if action == "SELL":
        return "BUY"
    return "HOLD"


def _execution_trade_profile(value: Any) -> str:
    text = str(value or "").strip().upper().replace("-", "_").replace(" ", "_")
    if text in {"SWING", "SWING_ONLY", "TREND_FOLLOW"}:
        return "SWING"
    if text in {"AUTO", "HYBRID", "HIGH_FREQUENCY_WITH_SWING_FALLBACK"}:
        return _HIGH_FREQUENCY_FALLBACK_PROFILE
    if text in {"HF", "HFT", "HIGH_FREQUENCY", "HIGH_FREQUENCY_ONLY", "TWO_CANDLE"}:
        return _HIGH_FREQUENCY_TRADE_PROFILE
    return _HIGH_FREQUENCY_TRADE_PROFILE


def _forecast_direction_and_confidence(value: Any) -> tuple[str, float]:
    row = _mapping_to_dict(value)
    side = _upper_action(
        row.get("direction")
        or row.get("direction_bias")
        or row.get("side")
        or row.get("bias"),
        fallback="HOLD",
    )
    if side not in {"BUY", "SELL"}:
        side = "HOLD"
    return side, _clip01(row.get("confidence", row.get("probability", 0.0)))


def _m5_candle_boundary_clock(now_epoch: float, timeframe_seconds: int, *, grace_seconds: float) -> dict[str, Any]:
    tf_seconds = max(1, int(timeframe_seconds or 300))
    now_value = max(0.0, float(now_epoch or 0.0))
    cycle_start = int(now_value // tf_seconds) * tf_seconds
    elapsed = max(0.0, now_value - float(cycle_start))
    remaining = max(0.0, float(tf_seconds) - elapsed)
    just_closed = elapsed <= max(1.0, float(grace_seconds or 0.0))
    last_closed = float(cycle_start)
    next_close = float(cycle_start + tf_seconds)
    return {
        "timeframe_seconds": int(tf_seconds),
        "cycle_start_epoch": float(cycle_start),
        "cycle_start_at": _epoch_to_utc_iso(float(cycle_start)),
        "last_closed_epoch": last_closed,
        "last_closed_at": _epoch_to_utc_iso(last_closed),
        "next_close_epoch": next_close,
        "next_close_at": _epoch_to_utc_iso(next_close),
        "seconds_elapsed": round(float(elapsed), 3),
        "seconds_remaining": round(float(remaining), 3),
        "entry_grace_seconds": round(float(grace_seconds), 3),
        "just_closed": bool(just_closed),
    }


def _build_high_frequency_candle_cycle_context(
    *,
    signal: Mapping[str, Any],
    tracking: Mapping[str, Any],
    controls: Mapping[str, Any],
    symbol: str,
    timeframe: str,
    now_epoch: float,
) -> dict[str, Any]:
    profile = _execution_trade_profile(controls.get("trade_profile") or controls.get("execution_profile"))
    enabled = bool(controls.get("high_frequency_enabled", True)) and profile != "SWING"
    swing_fallback_enabled = bool(controls.get("swing_fallback_enabled", False))
    configured_timeframe = _normalize_high_frequency_timeframe(
        controls.get("high_frequency_timeframe", _HIGH_FREQUENCY_TIMEFRAME)
    )
    timeframe_label = str(timeframe or "").strip().upper()
    timeframe_seconds = _timeframe_seconds(timeframe_label or configured_timeframe, default=300)
    grace_seconds = max(
        0.0,
        float(controls.get("high_frequency_entry_grace_sec", _HIGH_FREQUENCY_ENTRY_GRACE_SEC) or 0.0),
    )
    clock = _m5_candle_boundary_clock(float(now_epoch), timeframe_seconds, grace_seconds=grace_seconds)
    high_frequency = _mapping_to_dict(
        signal.get("high_frequency_forecast")
        or tracking.get("high_frequency_forecast")
        or signal.get("micro_candle_forecast")
        or tracking.get("micro_candle_forecast")
    )
    two_candle_study = _mapping_to_dict(
        signal.get("two_candle_study")
        or tracking.get("two_candle_study")
        or high_frequency.get("two_candle_study")
    )
    forecast_rows = _sequence_of_mappings(high_frequency.get("candle_forecasts"))
    next_forecast = _mapping_to_dict(two_candle_study.get("next_candle_forecast"))
    second_forecast = _mapping_to_dict(two_candle_study.get("second_next_candle_forecast"))
    if not next_forecast and forecast_rows:
        next_forecast = dict(forecast_rows[0])
    if not second_forecast and len(forecast_rows) >= 2:
        second_forecast = dict(forecast_rows[1])
    next_side, next_confidence = _forecast_direction_and_confidence(next_forecast)
    second_side, second_confidence = _forecast_direction_and_confidence(second_forecast)

    def first_trade_side(*values: Any) -> str:
        for value in values:
            side_value = _upper_action(value, fallback="HOLD")
            if side_value in {"BUY", "SELL"}:
                return side_value
        return "HOLD"

    active_candidate_side = first_trade_side(
        signal.get("execution_action"),
        signal.get("candidate_action"),
        signal.get("action"),
        signal.get("side"),
        tracking.get("candidate_side"),
        tracking.get("execution_action"),
        tracking.get("action"),
    )
    pressure_side = first_trade_side(
        high_frequency.get("primary_pressure"),
        two_candle_study.get("primary_pressure"),
        signal.get("candidate_action"),
        signal.get("action"),
    )
    agreement_side = next_side if next_side in {"BUY", "SELL"} and next_side == second_side else "HOLD"
    side = (
        agreement_side
        if agreement_side in {"BUY", "SELL"}
        else active_candidate_side
        if active_candidate_side in {"BUY", "SELL"}
        else pressure_side
    )
    forecast_confidence = max(
        _clip01(high_frequency.get("confidence") or 0.0),
        _clip01(two_candle_study.get("confidence") or 0.0),
        (next_confidence + second_confidence) / 2.0 if next_confidence > 0.0 or second_confidence > 0.0 else 0.0,
    )
    min_confidence = _clip01(
        controls.get("high_frequency_min_confidence", _HIGH_FREQUENCY_MIN_CONFIDENCE)
        or _HIGH_FREQUENCY_MIN_CONFIDENCE
    )
    profile_expiry_seconds = _high_frequency_profile_expiry_seconds(configured_timeframe)
    expiry_seconds = max(
        profile_expiry_seconds,
        int(
            float(
                controls.get("high_frequency_expiry_seconds", profile_expiry_seconds)
                or profile_expiry_seconds
            )
        ),
    )
    minimum_horizon_candles = int(
        math.ceil(
            MINIMUM_ELIGIBLE_TRADE_DURATION_SECONDS
            / float(max(1, timeframe_seconds))
        )
    )
    horizon_candles = max(
        _HIGH_FREQUENCY_HORIZON_CANDLES,
        minimum_horizon_candles,
        int(
            float(
                controls.get("high_frequency_horizon_candles", _HIGH_FREQUENCY_HORIZON_CANDLES)
                or _HIGH_FREQUENCY_HORIZON_CANDLES
            )
        ),
    )
    status = str(high_frequency.get("status") or two_candle_study.get("status") or "").strip().upper()
    timeframe_ok = timeframe_label == configured_timeframe
    forecast_ready = bool(status == "READY" and agreement_side in {"BUY", "SELL"})
    confidence_ok = bool(forecast_confidence >= min_confidence)
    candle_closed = bool(clock.get("just_closed"))
    ready = bool(enabled and timeframe_ok and forecast_ready and confidence_ok and candle_closed)
    if not enabled:
        reason = "High-frequency profile is disabled."
    elif not timeframe_ok:
        reason = f"High-frequency mode is fixed to {configured_timeframe}; detected timeframe is {timeframe_label or 'missing'}."
    elif not forecast_ready:
        reason = "Waiting for next-1 and next-2 unseen candle forecasts to agree on BUY or SELL."
    elif not confidence_ok:
        reason = f"Two-candle confidence {forecast_confidence:.2f} is below {min_confidence:.2f}."
    elif not candle_closed:
        reason = f"Current {timeframe_label or configured_timeframe} candle is still open; {clock['seconds_remaining']:.1f}s until close."
    else:
        reason = (
            f"{side} short-horizon direction evidence is ready; the candidate "
            f"duration is held to {expiry_seconds}s so sub-15-minute moves are "
            "not considered."
        )
    closed_epoch = float(clock.get("last_closed_epoch", now_epoch) or now_epoch)
    return {
        "schema_version": "PG_MINIMUM_DURATION_CANDLE_CYCLE_V3",
        "enabled": bool(enabled),
        "profile": profile,
        "swing_fallback_enabled": swing_fallback_enabled,
        "ready": ready,
        "reason": reason,
        "lane": _HIGH_FREQUENCY_LANE,
        "side": side if ready and side in {"BUY", "SELL"} else "HOLD",
        "candidate_side": side if side in {"BUY", "SELL"} else "HOLD",
        "forecast_side": agreement_side,
        "pressure_side": pressure_side,
        "active_candidate_side": active_candidate_side,
        "confidence": round(float(forecast_confidence), 4),
        "min_confidence": round(float(min_confidence), 4),
        "timeframe": timeframe_label,
        "configured_timeframe": configured_timeframe,
        "timeframe_seconds": int(timeframe_seconds),
        "horizon_candles": int(horizon_candles),
        "expiry_seconds": int(expiry_seconds),
        "entry_duration_seconds": int(expiry_seconds),
        "entry_duration_candles": round(float(expiry_seconds) / float(max(1, timeframe_seconds)), 3),
        "current_candle_closed": candle_closed,
        "current_candle_state": "CLOSED_CONFIRMED" if candle_closed else "DEVELOPING",
        "closed_candle_epoch": closed_epoch,
        "closed_candle_at": _epoch_to_utc_iso(closed_epoch),
        "cycle_key": f"{symbol or 'UNKNOWN'}|{timeframe_label or configured_timeframe}|{int(closed_epoch)}|{int(expiry_seconds)}",
        "instrument_key": f"{symbol or 'UNKNOWN'}|{timeframe_label or configured_timeframe}",
        "clock": clock,
        "next_candle_forecast": next_forecast,
        "second_next_candle_forecast": second_forecast,
        "forecast_agreement": bool(agreement_side in {"BUY", "SELL"}),
        "targets_future_candle_window": True,
        "duration_policy": duration_eligibility_contract_v3(expiry_seconds),
        "minimum_eligible_duration_seconds": (
            MINIMUM_ELIGIBLE_TRADE_DURATION_SECONDS
        ),
        "under_15_minutes_excluded": True,
        "short_horizon_direction_is_not_timing_authority": True,
        "do_not_render_synthetic_candles": True,
        "uses_unseen_future_candles": False,
        "does_not_trade_seen_last_two_candles": True,
    }


def _execution_expiry_window(timeframe_seconds: int) -> tuple[int, int, int, int]:
    tf = max(1, int(timeframe_seconds or 300))
    if tf <= 30:
        fast = max(_EXECUTION_TACTICAL_MIN_SEC, tf)
        standard = max(fast, min(120, tf * 2))
        maximum = max(standard, min(_EXECUTION_MAX_LIVE_EXPIRY_SEC, tf * 12))
    elif tf <= 60:
        fast = 60
        standard = 180
        maximum = 600
    elif tf <= 180:
        fast = 180
        standard = 360
        maximum = 1200
    elif tf <= 300:
        fast = 300
        standard = 900
        maximum = _EXECUTION_MAX_LIVE_EXPIRY_SEC
    else:
        fast = max(300, int(round(tf * 0.75)))
        standard = min(_EXECUTION_MAX_LIVE_EXPIRY_SEC, max(fast, int(round(tf * 2.0))))
        maximum = _EXECUTION_MAX_LIVE_EXPIRY_SEC
    # JPCLF timing does not admit sub-15-minute contracts.  Keep the adaptive
    # shape above the floor, but never let a low timeframe collapse the OTC
    # clock back to a scalp-sized expiry.
    minimum = MINIMUM_ELIGIBLE_TRADE_DURATION_SECONDS
    fast = min(_EXECUTION_MAX_LIVE_EXPIRY_SEC, max(minimum, fast))
    standard = min(
        _EXECUTION_MAX_LIVE_EXPIRY_SEC,
        max(fast, standard),
    )
    maximum = min(
        _EXECUTION_MAX_LIVE_EXPIRY_SEC,
        max(standard, maximum),
    )
    return (
        int(max(1, minimum)),
        int(max(minimum, fast)),
        int(max(fast, standard)),
        int(max(standard, maximum)),
    )


def _jpclf_planned_contract_duration_seconds(
    timeframe: object,
    decision_kernel: Mapping[str, Any],
    execution_controls: Mapping[str, Any],
) -> int:
    """Freeze the explicit duration studied by JPCLF for this closed candle.

    This planner intentionally runs before the executable timing packet exists.
    It uses only the current closed-candle decision horizon, the visible
    timeframe, and an explicit operator timing control.  The result is a
    study candidate, never entry permission.
    """

    timeframe_seconds = _timeframe_seconds(timeframe, default=300)
    if timeframe_seconds > MAXIMUM_STUDIED_TRADE_DURATION_SECONDS:
        # A closed H4/D1 candle cannot prove a sub-candle expiry inside the
        # bounded two-hour field, so the JPCLF lane must abstain.
        return 0
    _minimum, _tactical, standard, maximum = _execution_expiry_window(
        timeframe_seconds
    )
    try:
        horizon_candles = int(decision_kernel.get("target_horizon_candles", 0) or 0)
    except (TypeError, ValueError, OverflowError):
        horizon_candles = 0
    mapped_seconds = (
        max(0, horizon_candles) * timeframe_seconds
        if horizon_candles > 0
        else 0
    )
    configured_seconds = 0
    configured_timeframe = str(
        execution_controls.get("high_frequency_timeframe") or ""
    ).strip().upper()
    if configured_timeframe == str(timeframe or "").strip().upper():
        try:
            configured_seconds = int(
                execution_controls.get("high_frequency_expiry_seconds", 0) or 0
            )
        except (TypeError, ValueError, OverflowError):
            configured_seconds = 0
    candidate = max(
        MINIMUM_ELIGIBLE_TRADE_DURATION_SECONDS,
        standard,
        mapped_seconds,
        configured_seconds,
    )
    # A closed-candle-only field may mature only on an actually observed close.
    # Align to source cadence instead of inventing an intrabar expiry boundary.
    candidate = int(
        math.ceil(candidate / float(max(1, timeframe_seconds)))
        * max(1, timeframe_seconds)
    )
    return int(
        max(
            MINIMUM_ELIGIBLE_TRADE_DURATION_SECONDS,
            min(MAXIMUM_STUDIED_TRADE_DURATION_SECONDS, maximum, candidate),
        )
    )


def _extract_price_proxy_series(tracking_summary: Mapping[str, Any]) -> list[float]:
    rows = _sequence_of_mappings(tracking_summary.get("tracked_candles", []))
    values: list[float] = []
    for row in rows:
        for key in ("price_proxy", "close_proxy", "c", "close"):
            if key in row:
                value = _float_or(row.get(key), float("nan"))
                if np.isfinite(value):
                    values.append(float(value))
                    break
    if not values:
        latest = _float_or(tracking_summary.get("latest_price_proxy"), float("nan"))
        if np.isfinite(latest):
            values.append(float(latest))
    return values


def _price_proxy_values_from_row(row: Mapping[str, Any]) -> list[float]:
    values: list[float] = []
    for key in (
        "high_proxy",
        "low_proxy",
        "open_proxy",
        "close_proxy",
        "price_proxy",
        "h",
        "l",
        "o",
        "c",
        "high",
        "low",
        "open",
        "close",
    ):
        if key not in row:
            continue
        value = _float_or(row.get(key), float("nan"))
        if np.isfinite(value):
            values.append(float(value))
    return values


def _extract_price_proxy_range_values(tracking_summary: Mapping[str, Any], *, window: int | None = None) -> list[float]:
    rows = _sequence_of_mappings(tracking_summary.get("tracked_candles", []))
    selected = rows[-window:] if window and window > 0 else rows
    values: list[float] = []
    for row in selected:
        values.extend(_price_proxy_values_from_row(row))
    if not values:
        close_values = _extract_price_proxy_series(tracking_summary)
        values.extend(close_values[-window:] if window and window > 0 else close_values)
    if not values:
        latest = _float_or(tracking_summary.get("latest_price_proxy"), float("nan"))
        if np.isfinite(latest):
            values.append(float(latest))
    return [float(value) for value in values if np.isfinite(float(value))]


def _latest_price_proxy(tracking_summary: Mapping[str, Any], latest_signal: Mapping[str, Any] | None = None) -> float | None:
    direct = _float_or(tracking_summary.get("latest_price_proxy"), float("nan"))
    if np.isfinite(direct):
        return float(direct)
    if latest_signal is not None:
        signal_price = _float_or(latest_signal.get("latest_price_proxy"), float("nan"))
        if np.isfinite(signal_price):
            return float(signal_price)
    series = _extract_price_proxy_series(tracking_summary)
    if series:
        return float(series[-1])
    return None


def _position_in_series(values: Sequence[float], *, window: int | None = None) -> float:
    selected = list(values[-window:]) if window and window > 0 else list(values)
    selected = [float(value) for value in selected if np.isfinite(float(value))]
    if not selected:
        return 0.5
    low = min(selected)
    high = max(selected)
    if high - low <= 1e-6:
        return 0.5
    return _clip01((selected[-1] - low) / (high - low))


def _position_value_in_values(value: float | None, values: Sequence[float]) -> float:
    selected = [float(item) for item in values if np.isfinite(float(item))]
    if not selected or value is None or not np.isfinite(float(value)):
        return 0.5
    low = min(selected)
    high = max(selected)
    if high - low <= 1e-6:
        return 0.5
    return _clip01((float(value) - low) / (high - low))


def _execution_price_position_payload(
    latest_signal: Mapping[str, Any],
    tracking_summary: Mapping[str, Any],
    *,
    side_override: str | None = None,
) -> dict[str, Any]:
    series = _extract_price_proxy_series(tracking_summary)
    latest_price = _latest_price_proxy(tracking_summary, latest_signal)
    range_values = _extract_price_proxy_range_values(tracking_summary)
    local_range_values = _extract_price_proxy_range_values(tracking_summary, window=12)
    tokens = _sequence_of_mappings(_mapping_to_dict(tracking_summary.get("behavior", {})).get("candle_tokens", []))
    latest_token = tokens[-1] if tokens else {}
    close_position_raw = _float_or(
        latest_signal.get("close_position", latest_token.get("close_position")),
        float("nan"),
    )
    global_position = _position_value_in_values(latest_price, range_values) if range_values else _position_in_series(series)
    local_position = (
        _position_value_in_values(latest_price, local_range_values)
        if local_range_values
        else _position_in_series(series, window=12)
    )
    close_position = _clip01(close_position_raw) if np.isfinite(close_position_raw) else local_position
    side = _upper_action(side_override, fallback="HOLD") if side_override else _upper_action(latest_signal.get("execution_action", latest_signal.get("action", "HOLD")))
    if side == "BUY":
        extreme_score = _clip01(max(global_position, local_position, close_position) - 0.50) * 2.0
        extreme_label = "global_or_local_high" if max(global_position, local_position) >= 0.82 else "upper_third" if close_position >= 0.66 else "balanced"
    elif side == "SELL":
        extreme_score = _clip01(0.50 - min(global_position, local_position, close_position)) * 2.0
        extreme_label = "global_or_local_low" if min(global_position, local_position) <= 0.18 else "lower_third" if close_position <= 0.34 else "balanced"
    else:
        extreme_score = 0.0
        extreme_label = "balanced"
    return {
        "latest_price_proxy": latest_price,
        "global_position": round(float(global_position), 4),
        "local_position": round(float(local_position), 4),
        "close_position": round(float(close_position), 4),
        "extreme_score": round(float(_clip01(extreme_score)), 4),
        "extreme_label": extreme_label,
        "sample_size": int(max(len(series), len(_sequence_of_mappings(tracking_summary.get("tracked_candles", []))))),
        "range_sample_size": int(len(range_values)),
    }


def _support_resistance_zone_candidates(
    tracking_summary: Mapping[str, Any],
    latest_signal: Mapping[str, Any],
) -> list[dict[str, Any]]:
    raw_sources: list[Any] = [
        tracking_summary.get("support_resistance_zones"),
        latest_signal.get("support_resistance_zones"),
        _mapping_to_dict(tracking_summary.get("support_resistance_context", {})).get("significant_zones"),
        _mapping_to_dict(latest_signal.get("support_resistance_context", {})).get("significant_zones"),
    ]
    smc_summary = _mapping_to_dict(tracking_summary.get("smart_money_context", {}))
    smc_signal = _mapping_to_dict(latest_signal.get("smart_money_context", {}))
    raw_sources.extend(
        [
            _mapping_to_dict(smc_summary.get("support_resistance", {})).get("significant_zones"),
            _mapping_to_dict(smc_signal.get("support_resistance", {})).get("significant_zones"),
            smc_summary.get("liquidity_pools"),
            smc_signal.get("liquidity_pools"),
        ]
    )
    zones: list[dict[str, Any]] = []
    seen: set[tuple[str, str, int, str]] = set()
    for source in raw_sources:
        for zone in _sequence_of_mappings(source):
            role = str(zone.get("role", "") or "").lower()
            label = str(zone.get("label", zone.get("key", "")) or "")
            line_y = int(round(_float_or(zone.get("line_y", -1), -1.0)))
            key = str(zone.get("key", "") or "")
            identity = (role, label, line_y, key)
            if identity in seen:
                continue
            seen.add(identity)
            zones.append(dict(zone))
    return zones


def _zone_role(zone: Mapping[str, Any]) -> str:
    role = str(zone.get("role", "") or "").strip().lower()
    if role in {"support", "resistance"}:
        return role
    text = " ".join(
        str(zone.get(key, "") or "").lower()
        for key in ("label", "key", "entry_relevance", "kind", "zone_type", "type")
    )
    if "support" in text:
        return "support"
    if "resistance" in text:
        return "resistance"
    direction = _upper_action(zone.get("direction", "HOLD"))
    if direction == "BUY":
        return "support"
    if direction == "SELL":
        return "resistance"
    return ""


def _zone_significance(zone: Mapping[str, Any]) -> float:
    scores = [
        _clip01(zone.get("significance_score", 0.0)),
        _clip01(zone.get("historical_significance", 0.0)),
        _clip01(zone.get("confidence", 0.0)),
    ]
    return _clip01(max(scores))


def _zone_entry_authority_allowed(zone: Mapping[str, Any]) -> bool:
    explicit = zone.get("entry_authority_allowed")
    if isinstance(explicit, bool):
        return explicit
    if isinstance(explicit, str):
        normalized = explicit.strip().lower()
        if normalized in {"true", "1", "yes"}:
            return True
        if normalized in {"false", "0", "no"}:
            return False
    authority_state = str(zone.get("zone_authority_state", "") or "").strip().upper()
    if authority_state in {"BROKEN_REFERENCE", "CONSUMED_REFERENCE"}:
        return False
    freshness_state = str(zone.get("freshness_state", "REFERENCE") or "REFERENCE").strip().upper()
    if freshness_state in {"BROKEN", "CONSUMED"} and not bool(zone.get("role_flip_confirmed", False)):
        return False
    return True


def _opposing_force_zones(
    side: str,
    tracking_summary: Mapping[str, Any],
    latest_signal: Mapping[str, Any],
) -> list[dict[str, Any]]:
    side_action = _upper_action(side)
    wanted_role = "resistance" if side_action == "BUY" else "support" if side_action == "SELL" else ""
    if not wanted_role:
        return []
    wanted_relations = {"above_price", "at_price"} if wanted_role == "resistance" else {"below_price", "at_price"}
    zones = _support_resistance_zone_candidates(tracking_summary, latest_signal)
    candidates: list[dict[str, Any]] = []
    for zone in zones:
        if not _zone_entry_authority_allowed(zone):
            continue
        role = _zone_role(zone)
        if role != wanted_role:
            continue
        relation = str(zone.get("price_relation", "") or "").lower()
        if relation and relation not in wanted_relations:
            continue
        significance = _zone_significance(zone)
        still_significant = bool(zone.get("still_significant", False))
        if significance < 0.34 and not still_significant:
            continue
        distance = _clip01(zone.get("distance_to_latest_norm", 1.0))
        proximity = _clip01(1.0 - distance)
        relation_bonus = 0.18 if relation == "at_price" else 0.0
        persistence_bonus = 0.10 if still_significant else 0.0
        risk = _clip01(significance * (0.44 + 0.56 * proximity) + relation_bonus + persistence_bonus)
        row = dict(zone)
        row["role"] = role
        row["opposing_force_risk"] = round(float(risk), 4)
        row["opposing_force_distance_norm"] = round(float(distance), 4)
        candidates.append(row)
    if not candidates:
        return []
    candidates.sort(
        key=lambda zone: (
            -float(zone.get("opposing_force_risk", 0.0) or 0.0),
            float(zone.get("opposing_force_distance_norm", 1.0) or 1.0),
            -float(zone.get("significance_score", zone.get("confidence", 0.0)) or 0.0),
        )
    )
    return candidates


def _entry_area_zones(
    side: str,
    tracking_summary: Mapping[str, Any],
    latest_signal: Mapping[str, Any],
) -> list[dict[str, Any]]:
    side_action = _upper_action(side)
    wanted_role = "support" if side_action == "BUY" else "resistance" if side_action == "SELL" else ""
    if not wanted_role:
        return []
    wanted_relations = {"below_price", "at_price"} if wanted_role == "support" else {"above_price", "at_price"}
    wanted_relevance = "entry_support" if wanted_role == "support" else "entry_resistance"
    zones = _support_resistance_zone_candidates(tracking_summary, latest_signal)
    candidates: list[dict[str, Any]] = []
    for zone in zones:
        if not _zone_entry_authority_allowed(zone):
            continue
        role = _zone_role(zone)
        if role != wanted_role:
            continue
        relation = str(zone.get("price_relation", "") or "").strip().lower()
        entry_relevance = str(zone.get("entry_relevance", "") or "").strip().lower()
        if relation and relation not in wanted_relations and entry_relevance != wanted_relevance:
            continue
        significance = _zone_significance(zone)
        historical_significance = _clip01(zone.get("historical_significance", significance))
        still_significant = bool(zone.get("still_significant", False))
        explicit_entry_zone = bool(entry_relevance == wanted_relevance or relation == "at_price")
        if significance < 0.30 and historical_significance < 0.34 and not still_significant and not explicit_entry_zone:
            continue
        distance = _clip01(zone.get("distance_to_latest_norm", 1.0))
        if relation != "at_price" and distance > _EXECUTION_ENTRY_AREA_NEAR_DISTANCE and significance < 0.56 and not still_significant:
            continue
        proximity = _clip01(1.0 - distance)
        relation_bonus = 0.18 if relation == "at_price" else 0.08 if relation in wanted_relations else 0.0
        persistence_bonus = 0.10 if still_significant else 0.0
        relevance_bonus = 0.10 if entry_relevance == wanted_relevance else 0.0
        score = _clip01(
            0.38 * significance
            + 0.22 * historical_significance
            + 0.22 * proximity
            + relation_bonus
            + persistence_bonus
            + relevance_bonus
        )
        row = dict(zone)
        row["role"] = role
        row["entry_area_score"] = round(float(score), 4)
        row["entry_area_distance_norm"] = round(float(distance), 4)
        row["entry_area_relation"] = relation or "mapped_history"
        row["entry_area_relevance"] = entry_relevance or wanted_relevance
        candidates.append(row)
    if not candidates:
        return []
    candidates.sort(
        key=lambda zone: (
            -float(zone.get("entry_area_score", 0.0) or 0.0),
            float(zone.get("entry_area_distance_norm", 1.0) or 1.0),
            -float(zone.get("significance_score", zone.get("confidence", 0.0)) or 0.0),
        )
    )
    return candidates


def _nearest_entry_area_zone(
    side: str,
    tracking_summary: Mapping[str, Any],
    latest_signal: Mapping[str, Any],
) -> tuple[dict[str, Any], float, list[dict[str, Any]]]:
    candidates = _entry_area_zones(side, tracking_summary, latest_signal)
    if not candidates:
        return {}, 0.0, []
    nearest = candidates[0]
    return nearest, _clip01(nearest.get("entry_area_score", 0.0)), candidates


def _nearest_opposing_force_zone(
    side: str,
    tracking_summary: Mapping[str, Any],
    latest_signal: Mapping[str, Any],
) -> tuple[dict[str, Any], float, list[dict[str, Any]]]:
    candidates = _opposing_force_zones(side, tracking_summary, latest_signal)
    if not candidates:
        return {}, 0.0, []
    nearest = candidates[0]
    return nearest, _clip01(nearest.get("opposing_force_risk", 0.0)), candidates


def _current_promoted_jpclf_timing_v3(
    tracking_summary: Mapping[str, Any],
    *,
    side: object,
) -> dict[str, Any]:
    """Return only a current, safe, promoted JPCLF timing read.

    A hard duration veto is valid without empirical promotion. Every other
    support/veto must have passed the four-axis replay gate. This helper never
    creates permission; callers may only retain or reduce their existing
    `entry_allowed` result.
    """

    study = _mapping_to_dict(tracking_summary.get("market_study_v3", {}))
    if str(study.get("status") or "").strip().upper() != "STUDIED":
        return {}
    field = _mapping_to_dict(
        study.get(
            "path_clock_liquidity_v3",
            study.get("path_clock_liquidity", {}),
        )
    )
    if (
        field.get("schema_version")
        != "PG_PATH_CLOCK_LIQUIDITY_PUBLIC_STUDY_V3"
        or field.get("study_only") is not True
        or field.get("causal") is not True
        or field.get("execution_authority") is not False
        or field.get("grants_entry_permission") is not False
        or field.get("may_issue_orders") is not False
    ):
        return {}
    timing = _mapping_to_dict(field.get("timing_read", {}))
    if (
        timing.get("study_only") is not True
        or timing.get("causal") is not True
        or timing.get("execution_authority") is not False
        or timing.get("grants_entry_permission") is not False
        or timing.get("may_issue_orders") is not False
    ):
        return {}
    study_key = str(study.get("closed_candle_key") or "").strip()
    field_key = str(field.get("closed_candle_key") or "").strip()
    timing_key = str(timing.get("closed_candle_key") or "").strip()
    if not study_key or field_key != study_key or timing_key != study_key:
        return {}
    expected_side = _upper_action(side)
    timing_side = _upper_action(
        timing.get("side", timing.get("studied_direction", "HOLD"))
    )
    if timing_side in {"UP", "UPTREND", "BULL", "BULLISH"}:
        timing_side = "BUY"
    elif timing_side in {"DOWN", "DOWNTREND", "BEAR", "BEARISH"}:
        timing_side = "SELL"
    if expected_side not in {"BUY", "SELL"} or timing_side != expected_side:
        return {}

    hard_duration_veto = str(timing.get("status") or "").strip().upper() == (
        "HARD_DURATION_VETO"
    )
    gate = _mapping_to_dict(
        timing.get("promotion_gate", field.get("promotion_gate", {}))
    )
    promoted = bool(
        gate.get("passed") is True
        and gate.get("all_axes_improved") is True
        and _mapping_to_dict(gate.get("support", {})).get("passed") is True
    )
    if not hard_duration_veto and not promoted:
        return {}

    if not hard_duration_veto:
        for key in (
            "contract_duration_seconds",
            "candidate_horizon_seconds",
            "remaining_seconds",
        ):
            raw_value = timing.get(key)
            if raw_value is None:
                return {}
            try:
                value = float(raw_value)
            except (TypeError, ValueError, OverflowError):
                return {}
            if (
                not math.isfinite(value)
                or value < MINIMUM_ELIGIBLE_TRADE_DURATION_SECONDS
                or value > MAXIMUM_STUDIED_TRADE_DURATION_SECONDS
            ):
                return {}
    return {
        "status": str(timing.get("status") or ""),
        "state": str(timing.get("state") or ""),
        "side": timing_side,
        "contract_duration_seconds": timing.get("contract_duration_seconds"),
        "candidate_horizon_seconds": timing.get("candidate_horizon_seconds"),
        "remaining_seconds": timing.get("remaining_seconds"),
        "support_count": timing.get("support_count"),
        "survival_probability": timing.get("survival_probability"),
        "probability_worst_drawdown_still_ahead": timing.get(
            "probability_worst_drawdown_still_ahead"
        ),
        "new_entry_eligible": timing.get("new_entry_eligible") is True,
        "timing_supports_entry": timing.get("timing_supports_entry") is True,
        "timing_veto": timing.get("timing_veto") is True,
        "closed_candle_key": timing_key,
        "observed_at": timing.get("observed_at"),
        "valid_until": timing.get("valid_until"),
        "promotion_gate": gate,
        "study_only": True,
        "execution_authority": False,
        "grants_entry_permission": False,
    }


def _build_execution_timing_profile(
    latest_signal: Mapping[str, Any],
    tracking_summary: Mapping[str, Any],
    *,
    lane: str,
) -> dict[str, Any]:
    execution_side = _upper_action(latest_signal.get("execution_action", latest_signal.get("action", "HOLD")))
    candidate_side = _upper_action(
        latest_signal.get(
            "action",
            latest_signal.get("candidate_action", latest_signal.get("headline_action", execution_side)),
        )
    )
    side = execution_side if execution_side in {"BUY", "SELL"} else candidate_side
    timeframe = latest_signal.get("focus_timeframe") or tracking_summary.get("detected_timeframe")
    timeframe_sec = _strict_execution_timeframe_seconds(timeframe)
    decision_kernel = _mapping_to_dict(tracking_summary.get("decision_kernel", latest_signal.get("decision_kernel", {})))
    if not decision_kernel:
        raise ValueError("strict execution requires a decision_kernel")
    try:
        target_horizon = int(decision_kernel["target_horizon_candles"])
    except (KeyError, TypeError, ValueError) as exc:
        raise ValueError("strict execution requires target_horizon_candles") from exc
    if target_horizon <= 0:
        raise ValueError("strict execution requires positive target_horizon_candles")

    lane_key = str(lane or "PRIMARY").upper()
    if lane_key == "COUNTERTREND_SCALP":
        try:
            countertrend_window = int(decision_kernel["countertrend_window_candles"])
        except (KeyError, TypeError, ValueError) as exc:
            raise ValueError("strict countertrend execution requires countertrend_window_candles") from exc
        if countertrend_window <= 0:
            raise ValueError("strict countertrend execution requires positive countertrend_window_candles")
    else:
        countertrend_window = 0

    if lane_key == _HIGH_FREQUENCY_LANE:
        fixed_expiry = int(_high_frequency_profile_expiry_seconds(timeframe))
        jpclf_timing = _current_promoted_jpclf_timing_v3(
            tracking_summary,
            side=side,
        )
        if bool(jpclf_timing.get("timing_supports_entry", False)):
            try:
                supported_duration = int(
                    _float_or(
                        jpclf_timing.get("contract_duration_seconds"),
                        float(fixed_expiry),
                    )
                )
            except (TypeError, ValueError, OverflowError):
                supported_duration = fixed_expiry
            fixed_expiry = int(
                max(
                    MINIMUM_ELIGIBLE_TRADE_DURATION_SECONDS,
                    min(MAXIMUM_STUDIED_TRADE_DURATION_SECONDS, supported_duration),
                )
            )
        jpclf_veto = bool(
            jpclf_timing
            and (
                jpclf_timing.get("timing_veto") is True
                or jpclf_timing.get("new_entry_eligible") is not True
            )
        )
        fixed_horizon = max(
            int(_HIGH_FREQUENCY_HORIZON_CANDLES),
            int(math.ceil(fixed_expiry / float(max(1, timeframe_sec)))),
        )
        duration_policy = duration_eligibility_contract_v3(fixed_expiry)
        return {
            "version": "jpclf_minimum_duration_timing_v3",
            "side": execution_side if execution_side in {"BUY", "SELL"} else "HOLD",
            "candidate_side": side if side in {"BUY", "SELL"} else "HOLD",
            "lane": lane_key,
            "timeframe": str(timeframe or _HIGH_FREQUENCY_TIMEFRAME).upper(),
            "timeframe_seconds": int(timeframe_sec),
            "target_horizon_candles": fixed_horizon,
            "target_horizon_seconds": int(fixed_horizon * timeframe_sec),
            "eta_trigger_candles": 0,
            "eta_trigger_seconds": 0,
            "eta_target_after_trigger_candles": fixed_horizon,
            "eta_target_after_trigger_seconds": int(fixed_horizon * timeframe_sec),
            "eta_invalidation_candles": fixed_horizon,
            "eta_invalidation_seconds": int(fixed_horizon * timeframe_sec),
            "stale_after_candles": fixed_horizon,
            "stale_after_seconds": int(fixed_horizon * timeframe_sec),
            "hold_for_candles": fixed_horizon,
            "hold_intent_seconds": fixed_expiry,
            "structural_target_seconds": fixed_expiry,
            "countertrend_window_candles": 0,
            "recommended_expiry_seconds": fixed_expiry,
            "expiry_seconds": fixed_expiry,
            "recommended_candles": round(float(fixed_expiry) / float(max(1, timeframe_sec)), 3),
            "minimum_seconds": fixed_expiry,
            "maximum_seconds": fixed_expiry,
            "timing_class": "minimum_duration_direction_cycle",
            "entry_allowed": not jpclf_veto,
            "block_reason": (
                "JPCLF timing vetoed this new entry; keep observing the "
                "late sweep/pullback instead of forcing the clock."
                if jpclf_veto
                else ""
            ),
            "rationale": (
                f"current {str(timeframe or _HIGH_FREQUENCY_TIMEFRAME).upper()} candle "
                "closed; retain the direction study but use no contract shorter than "
                "the 15-minute JPCLF eligibility floor"
            ),
            "quick_profit_mode": False,
            "hold_intent": "minimum_eligible_path_clock_window",
            "duration_policy": duration_policy,
            "minimum_eligible_duration_seconds": (
                MINIMUM_ELIGIBLE_TRADE_DURATION_SECONDS
            ),
            "under_15_minutes_excluded": True,
            "path_clock_liquidity_timing_v3": jpclf_timing,
            "jpclf_timing_supports_entry": bool(
                jpclf_timing.get("timing_supports_entry", False)
            ),
            "jpclf_timing_veto": jpclf_veto,
            "price_position": {},
            "global_extreme_risk": 0.0,
            "history_area_risk": 0.0,
            "history_area_label": "two_candle_boundary",
            "history_area_position": 0.5,
            "history_area_sample_size": 0,
            "favorable_history_reclaim": False,
            "favorable_history_rejection": False,
            "historical_entry_anchor": True,
            "significant_entry_context": True,
            "significant_zone_entry_context": False,
            "entry_area_score": 1.0,
            "opposing_force_risk": 0.0,
            "current_flow_continuation_ready": True,
            "breakout_confirmation": True,
            "current_candle_closed": True,
            "targets_future_candle_window": True,
            "do_not_render_synthetic_candles": True,
            "uses_unseen_future_candles": False,
        }

    min_sec, tactical_sec, standard_sec, max_sec = _execution_expiry_window(timeframe_sec)
    price_position = _execution_price_position_payload(latest_signal, tracking_summary, side_override=side)
    extreme_risk = _clip01(price_position.get("extreme_score", 0.0))
    global_position = _clip01(price_position.get("global_position", 0.5))
    local_position = _clip01(price_position.get("local_position", 0.5))
    favorable_history_reclaim = bool(
        side == "BUY"
        and global_position <= _EXECUTION_BUY_FAVORABLE_GLOBAL_MAX_POSITION
        and local_position >= 0.50
    )
    favorable_history_rejection = bool(
        side == "SELL"
        and global_position >= _EXECUTION_SELL_FAVORABLE_GLOBAL_MIN_POSITION
        and local_position <= 0.50
    )
    if favorable_history_reclaim:
        extreme_risk = min(extreme_risk, _clip01((global_position - 0.50) * 2.0))
    elif favorable_history_rejection:
        extreme_risk = min(extreme_risk, _clip01((0.50 - global_position) * 2.0))
    try:
        history_sample_size = int(price_position.get("sample_size", 0) or 0)
    except (TypeError, ValueError):
        history_sample_size = 0
    history_positions = [global_position, local_position]
    history_area_position = 0.5
    history_area_risk = 0.0
    history_area_label = "balanced"
    if side == "BUY":
        if favorable_history_reclaim:
            history_area_position = global_position
            history_area_label = "lower_studied_reclaim"
            history_area_risk = 0.0
        else:
            history_area_position = max(history_positions)
            history_area_risk = _clip01((history_area_position - 0.50) * 2.0)
            if history_area_position >= _EXECUTION_BUY_HISTORY_STRETCH_POSITION:
                history_area_label = "studied_high_extreme"
            elif history_area_position >= _EXECUTION_BUY_HISTORY_HIGH_POSITION:
                history_area_label = "upper_studied_history"
    elif side == "SELL":
        if favorable_history_rejection:
            history_area_position = global_position
            history_area_label = "upper_studied_rejection"
            history_area_risk = 0.0
        else:
            history_area_position = min(history_positions)
            history_area_risk = _clip01((0.50 - history_area_position) * 2.0)
            if history_area_position <= _EXECUTION_SELL_HISTORY_STRETCH_POSITION:
                history_area_label = "studied_low_extreme"
            elif history_area_position <= _EXECUTION_SELL_HISTORY_LOW_POSITION:
                history_area_label = "lower_studied_history"
    opposing_zone, opposing_force_risk, opposing_zones = _nearest_opposing_force_zone(side, tracking_summary, latest_signal)
    entry_area_zone, entry_area_score, entry_area_zones = _nearest_entry_area_zone(side, tracking_summary, latest_signal)
    entry_area_distance = _clip01(
        entry_area_zone.get(
            "entry_area_distance_norm",
            entry_area_zone.get("distance_to_latest_norm", 1.0),
        )
    )
    entry_area_relation = str(
        entry_area_zone.get(
            "entry_area_relation",
            entry_area_zone.get("price_relation", ""),
        )
        or ""
    ).strip().lower()
    entry_area_near = bool(
        entry_area_relation == "at_price"
        or entry_area_distance <= _EXECUTION_ENTRY_AREA_LIVE_NEAR_DISTANCE
    )
    historical_entry_anchor = bool(
        history_sample_size >= _EXECUTION_HISTORY_AREA_MIN_SAMPLE
        and (
            (
                side == "BUY"
                and global_position <= _EXECUTION_BUY_FAVORABLE_GLOBAL_MAX_POSITION
                and local_position >= 0.38
            )
            or (
                side == "SELL"
                and global_position >= _EXECUTION_SELL_FAVORABLE_GLOBAL_MIN_POSITION
                and local_position <= 0.62
            )
        )
    )
    significant_zone_entry_context = bool(
        side in {"BUY", "SELL"}
        and entry_area_score >= _EXECUTION_SIGNIFICANT_ENTRY_MIN_SCORE
        and entry_area_near
    )
    significant_entry_context = bool(
        significant_zone_entry_context
        or favorable_history_reclaim
        or favorable_history_rejection
        or historical_entry_anchor
    )
    preferred_entry_area = (
        "historical support or studied low"
        if side == "BUY"
        else "historical resistance or studied high"
        if side == "SELL"
        else "balanced"
    )
    kernel_state = str(decision_kernel.get("state", latest_signal.get("setup_state", "")) or "").upper()
    entry_state = str(latest_signal.get("entry_state", tracking_summary.get("entry_state", kernel_state)) or kernel_state).upper()
    p_target = _clip01(decision_kernel.get("p_target_before_invalidation", latest_signal.get("target_first_probability", 0.0)))
    p_trigger_next_1 = _clip01(decision_kernel.get("p_trigger_next_1", 0.0))
    p_trigger_next_3 = _clip01(decision_kernel.get("p_trigger_next_3", p_trigger_next_1))
    p_expire_before_trigger = _clip01(decision_kernel.get("p_expire_before_trigger", 0.0))
    p_next_side = _clip01(decision_kernel.get("p_next_buy" if side == "BUY" else "p_next_sell", 0.0))
    hazard_trigger = _clip01(decision_kernel.get("hazard_trigger", p_trigger_next_1))
    hazard_invalidation = _clip01(decision_kernel.get("hazard_invalidation", 1.0 - p_target))
    next_event = str(decision_kernel.get("next_most_likely_event", "") or "").strip().lower()
    kernel_decision = str(decision_kernel.get("decision", "") or "").strip().upper()
    kernel_trade_mode = str(decision_kernel.get("trade_mode", "") or "").strip().upper()
    candle_stats = _mapping_to_dict(tracking_summary.get("candle_statistics", {}))
    opposing_ratio = _clip01(candle_stats.get("opposing_ratio", 0.0))
    continuation_score = _clip01(tracking_summary.get("continuation_score", latest_signal.get("continuation_score", 0.0)))
    reversal_score = _clip01(tracking_summary.get("reversal_score", latest_signal.get("reversal_score", 0.0)))
    force_risk = _clip01(max(extreme_risk, opposing_force_risk, history_area_risk))
    try:
        eta_target_candles = int(decision_kernel.get("eta_target_after_trigger_candles", target_horizon) or target_horizon)
    except (TypeError, ValueError):
        eta_target_candles = target_horizon
    try:
        hold_for_candles = int(decision_kernel.get("hold_for_candles", target_horizon) or target_horizon)
    except (TypeError, ValueError):
        hold_for_candles = target_horizon
    try:
        eta_trigger_candles = int(decision_kernel.get("eta_trigger_candles", 0) or 0)
    except (TypeError, ValueError):
        eta_trigger_candles = 0
    try:
        eta_invalidation_candles = int(decision_kernel.get("eta_invalidation_candles", max(1, eta_target_candles)) or max(1, eta_target_candles))
    except (TypeError, ValueError):
        eta_invalidation_candles = max(1, eta_target_candles)
    try:
        stale_after_candles = int(decision_kernel.get("stale_after_candles", max(1, eta_target_candles + 1)) or max(1, eta_target_candles + 1))
    except (TypeError, ValueError):
        stale_after_candles = max(1, eta_target_candles + 1)
    eta_trigger_candles = max(0, eta_trigger_candles)
    eta_invalidation_candles = max(1, eta_invalidation_candles)
    stale_after_candles = max(1, stale_after_candles)
    eta_target_candles = max(1, eta_target_candles)
    hold_for_candles = max(1, hold_for_candles)
    map_horizon_seconds = int(max(timeframe_sec, target_horizon * timeframe_sec))
    eta_target_seconds = int(max(timeframe_sec, eta_target_candles * timeframe_sec))
    eta_trigger_seconds = int(max(0, eta_trigger_candles * timeframe_sec))
    eta_invalidation_seconds = int(max(timeframe_sec, eta_invalidation_candles * timeframe_sec))
    stale_after_seconds = int(max(timeframe_sec, stale_after_candles * timeframe_sec))
    hold_intent_seconds = int(max(timeframe_sec, hold_for_candles * timeframe_sec))
    structural_target_seconds = int(max(eta_target_seconds, min(map_horizon_seconds, hold_intent_seconds)))
    current_direction = _upper_action(tracking_summary.get("impulse_direction", latest_signal.get("impulse_direction", "HOLD")))
    local_flow_direction = _upper_action(tracking_summary.get("local_direction", latest_signal.get("local_direction", "HOLD")))
    global_flow_direction = _upper_action(tracking_summary.get("global_direction", latest_signal.get("global_direction", "HOLD")))
    latest_candle_direction = _upper_action(
        tracking_summary.get("latest_candle_direction", latest_signal.get("latest_candle_direction", "HOLD"))
    )
    candle_direction = _upper_action(decision_kernel.get("candle_execution_side", decision_kernel.get("next_candle_bias", "HOLD")))
    breakout_confirmation = bool(
        side in {"BUY", "SELL"}
        and current_direction == side
        and p_target >= 0.70
        and p_next_side >= 0.64
        and (continuation_score >= 0.54 or p_trigger_next_3 >= 0.62 or next_event in {"target", "trigger"})
    )
    clear_path_score = _clip01(
        0.42 * p_target
        + 0.24 * p_next_side
        + 0.20 * continuation_score
        + 0.14 * _clip01(1.0 - max(opposing_force_risk, opposing_ratio, reversal_score))
    )
    alignment_values = (
        latest_signal.get("execution_action"),
        latest_signal.get("action"),
        latest_signal.get("candidate_action"),
        tracking_summary.get("global_direction"),
        tracking_summary.get("local_direction"),
        tracking_summary.get("impulse_direction"),
        decision_kernel.get("dominant_side"),
        decision_kernel.get("major_trend_side"),
        decision_kernel.get("candle_execution_side"),
        decision_kernel.get("next_candle_bias"),
    )
    current_flow_alignment = 0
    current_flow_conflicts = 0
    for raw_value in alignment_values:
        parsed_side = _upper_action(raw_value, fallback="")
        if parsed_side == side:
            current_flow_alignment += 1
        elif parsed_side in {"BUY", "SELL"} and side in {"BUY", "SELL"}:
            current_flow_conflicts += 1
    history_extension_against_side = bool(
        side == "BUY"
        and history_sample_size >= _EXECUTION_HISTORY_AREA_MIN_SAMPLE
        and history_area_position >= _EXECUTION_BUY_HISTORY_HIGH_POSITION
    ) or bool(
        side == "SELL"
        and history_sample_size >= _EXECUTION_HISTORY_AREA_MIN_SAMPLE
        and history_area_position <= _EXECUTION_SELL_HISTORY_LOW_POSITION
    )
    history_extension_stretched = bool(
        side == "BUY" and history_area_position >= _EXECUTION_BUY_HISTORY_STRETCH_POSITION
    ) or bool(
        side == "SELL" and history_area_position <= _EXECUTION_SELL_HISTORY_STRETCH_POSITION
    )
    current_flow_min_p1 = 0.84 if history_extension_stretched else _EXECUTION_CURRENT_FLOW_MIN_P1
    current_flow_min_p3 = 0.94 if history_extension_stretched else _EXECUTION_CURRENT_FLOW_MIN_P3
    current_flow_min_target = 0.68 if history_extension_stretched else _EXECUTION_CURRENT_FLOW_MIN_TARGET
    current_flow_min_alignment = _EXECUTION_CURRENT_FLOW_MIN_ALIGNMENT + (1 if history_extension_stretched else 0)
    immediate_trigger_intent = bool(
        next_event in {"trigger", "target"}
        or kernel_state in {"TRIGGERED", "ACTIVE"}
        or "TRIGGER" in kernel_decision
        or "EXECUTE" in kernel_decision
    )
    current_flow_hazard_ready = bool(
        hazard_trigger > 0.0
        and hazard_trigger >= max(0.08, hazard_invalidation * 1.10)
    )
    current_flow_path_ready = bool(
        clear_path_score >= _EXECUTION_CURRENT_FLOW_MIN_CLEAR_PATH
        or p_target >= 0.74
        or opposing_force_risk <= 0.52
    )
    stretched_breakout_ready = bool(
        not history_extension_stretched
        or (
            breakout_confirmation
            and clear_path_score >= _EXECUTION_CURRENT_FLOW_STRETCHED_MIN_CLEAR_PATH
            and p_target >= _EXECUTION_CURRENT_FLOW_STRETCHED_MIN_TARGET
            and p_next_side >= 0.68
            and opposing_force_risk <= 0.46
            and reversal_score <= 0.40
        )
    )
    current_flow_direction_confirmed = bool(
        side in {"BUY", "SELL"}
        and (
            (
                current_direction == side
                and local_flow_direction == side
                and p_next_side >= 0.56
            )
            or (
                local_flow_direction == side
                and current_flow_alignment >= current_flow_min_alignment
                and p_next_side >= 0.58
            )
            or (
                global_flow_direction == side
                and local_flow_direction == side
                and candle_direction == side
                and p_trigger_next_3 >= current_flow_min_p3
            )
            or (
                latest_candle_direction == side
                and local_flow_direction == side
                and p_trigger_next_1 >= current_flow_min_p1
            )
        )
    )
    current_flow_continuation_ready = bool(
        side in {"BUY", "SELL"}
        and history_extension_against_side
        and kernel_trade_mode == "TREND_FOLLOW"
        and kernel_state in {"ARMED", "TRIGGERED", "ACTIVE"}
        and immediate_trigger_intent
        and current_flow_direction_confirmed
        and current_flow_alignment >= current_flow_min_alignment
        and current_flow_conflicts == 0
        and p_trigger_next_1 >= current_flow_min_p1
        and p_trigger_next_3 >= current_flow_min_p3
        and p_target >= current_flow_min_target
        and eta_target_candles >= 2
        and p_expire_before_trigger <= _EXECUTION_CURRENT_FLOW_MAX_EXPIRE
        and current_flow_hazard_ready
        and current_flow_path_ready
        and stretched_breakout_ready
        and opposing_ratio <= _EXECUTION_CURRENT_FLOW_MAX_OPPOSING_RATIO
        and reversal_score <= _EXECUTION_CURRENT_FLOW_MAX_REVERSAL
    )
    if current_flow_continuation_ready:
        breakout_confirmation = True
        history_area_risk = min(history_area_risk, 0.28)
        force_risk = _clip01(max(extreme_risk, opposing_force_risk, history_area_risk))

    entry_allowed = True
    block_reason = ""
    if side in {"BUY", "SELL"}:
        if (
            side == "BUY"
            and history_sample_size >= _EXECUTION_HISTORY_AREA_MIN_SAMPLE
            and history_area_position >= _EXECUTION_BUY_HISTORY_HIGH_POSITION
        ):
            if current_flow_continuation_ready:
                history_area_label = f"{history_area_label}_live_flow_break"
            else:
                entry_allowed = False
                block_reason = "BUY is already in the upper studied history area; wait for a lower support pullback or a clean retest."
        elif (
            side == "SELL"
            and history_sample_size >= _EXECUTION_HISTORY_AREA_MIN_SAMPLE
            and history_area_position <= _EXECUTION_SELL_HISTORY_LOW_POSITION
        ):
            if current_flow_continuation_ready:
                history_area_label = f"{history_area_label}_live_flow_break"
            else:
                entry_allowed = False
                block_reason = "SELL is already in the lower studied history area; wait for a resistance pullback or a clean retest."
        elif history_sample_size >= _EXECUTION_HISTORY_AREA_MIN_SAMPLE and not significant_entry_context:
            entry_allowed = False
            block_reason = (
                f"{side} requires a significant {preferred_entry_area} before live execution; "
                "current price is not at a mapped favorable area."
            )
        elif extreme_risk >= 0.82 and opposing_force_risk >= 0.42 and not breakout_confirmation:
            entry_allowed = False
            block_reason = "Price is entering a major opposing-force extreme; wait for rejection or breakout confirmation."
        elif extreme_risk >= 0.88 and p_target < 0.78 and not breakout_confirmation:
            entry_allowed = False
            block_reason = "Price is at the global/local extreme for this side; avoid buying highs or selling lows."
        elif opposing_force_risk >= 0.68 and p_target < 0.74 and not breakout_confirmation:
            entry_allowed = False
            block_reason = "Nearest significant support/resistance is opposing the entry before a clean trigger."

    jpclf_timing = _current_promoted_jpclf_timing_v3(
        tracking_summary,
        side=side,
    )
    jpclf_recommended_duration_seconds = 0
    if jpclf_timing:
        if bool(jpclf_timing.get("timing_veto", False)) or not bool(
            jpclf_timing.get("new_entry_eligible", False)
        ):
            entry_allowed = False
            timing_state = str(jpclf_timing.get("state") or "").upper()
            if timing_state == "DRAWDOWN_AHEAD":
                block_reason = (
                    "JPCLF timing says the worst historical pullback is likely "
                    "still ahead; stand aside for this entry window."
                )
            elif timing_state == "SWEEP_RISK":
                block_reason = (
                    "JPCLF timing shows insufficient stop survival for this "
                    "clock; stand aside instead of entering into the sweep."
                )
            else:
                block_reason = (
                    "JPCLF timing has not admitted a new entry inside the "
                    "15-minute minimum-duration contract."
                )
        elif bool(jpclf_timing.get("timing_supports_entry", False)):
            try:
                jpclf_recommended_duration_seconds = int(
                    _float_or(
                        jpclf_timing.get("contract_duration_seconds"),
                        0.0,
                    )
                )
            except (TypeError, ValueError, OverflowError):
                jpclf_recommended_duration_seconds = 0

    compression_pressure = bool(
        force_risk >= 0.52
        or p_expire_before_trigger >= 0.42
        or opposing_ratio >= 0.42
        or reversal_score >= 0.54
    )
    entry_ready = entry_state in {"SNIPER_READY", "TRIGGER_READY", "TRIGGERED", "ACTIVE", "EXECUTE"} or kernel_state in {"TRIGGERED", "ACTIVE"}
    strong_clean_continuation = bool(
        p_target >= 0.72
        and p_next_side >= 0.62
        and p_trigger_next_3 >= 0.58
        and force_risk < 0.46
        and opposing_ratio < 0.34
    )
    current_market_lane = lane_key in {"LIVE_MARKET_FLOW", "OPPOSING_FORCE_REACTION"}
    reaction_lane = lane_key == "OPPOSING_FORCE_REACTION"

    def current_market_expiry_seconds() -> int:
        # Live flow and opposing-force reactions are timing-sensitive. Do not
        # floor these lanes to the standard M15 window; first capture the active
        # leg, then extend only when the path is clean enough to justify it.
        target_cap = min(
            max_sec,
            max(timeframe_sec, structural_target_seconds),
            max(timeframe_sec, eta_target_seconds),
            max(timeframe_sec, stale_after_seconds),
            max(timeframe_sec, eta_invalidation_seconds),
        )
        trigger_capture = max(
            tactical_sec,
            int(max(1, min(max(1, eta_trigger_candles + 1), 2)) * timeframe_sec),
        )
        immediate_trigger = bool(p_trigger_next_1 >= 0.84 or (eta_target_candles <= 1 and p_trigger_next_1 >= 0.78))
        clean_extension = bool(
            clear_path_score >= 0.72
            and p_target >= 0.76
            and p_next_side >= 0.64
            and opposing_force_risk <= 0.42
            and opposing_ratio <= 0.34
            and reversal_score <= 0.36
        )
        if immediate_trigger:
            candidate = tactical_sec
        elif reaction_lane or compression_pressure:
            candidate = min(target_cap, trigger_capture)
            if clean_extension:
                candidate = min(target_cap, max(candidate, int(2 * timeframe_sec)))
        elif clean_extension or strong_clean_continuation:
            candidate = min(target_cap, max(standard_sec, structural_target_seconds))
        else:
            candidate = min(target_cap, max(tactical_sec, int(2 * timeframe_sec)))
        return int(max(min_sec, min(max_sec, candidate)))

    if not entry_allowed:
        recommended = max(tactical_sec, min(standard_sec, eta_target_seconds))
        if "studied history area" in block_reason or "significant" in block_reason or (
            history_area_label != "balanced" and history_area_risk + 0.001 >= max(opposing_force_risk, extreme_risk)
        ):
            timing_class = "history_area_wait"
        else:
            timing_class = "opposing_force_wait" if opposing_force_risk >= extreme_risk else "extreme_trap_wait"
    elif lane_key == "COUNTERTREND_SCALP":
        window_candles = countertrend_window
        recommended = int(max(tactical_sec, window_candles * timeframe_sec))
        timing_class = "countertrend_window"
    elif reaction_lane:
        recommended = current_market_expiry_seconds()
        timing_class = "opposing_force_reaction"
    elif current_market_lane and compression_pressure and not breakout_confirmation:
        recommended = current_market_expiry_seconds()
        timing_class = "current_flow_capture"
    elif current_market_lane and entry_ready:
        recommended = current_market_expiry_seconds()
        timing_class = "current_flow_trigger"
    elif current_market_lane and strong_clean_continuation:
        recommended = int(max(standard_sec, min(map_horizon_seconds, structural_target_seconds)))
        timing_class = "current_flow_extension"
    elif compression_pressure and not breakout_confirmation:
        recommended = int(max(standard_sec, min(structural_target_seconds, eta_target_seconds)))
        timing_class = "measured_reaction_window"
    elif breakout_confirmation:
        recommended = int(max(structural_target_seconds, min(map_horizon_seconds, max(eta_target_seconds, standard_sec))))
        timing_class = "breakout_extension"
    elif entry_ready and strong_clean_continuation:
        recommended = int(max(structural_target_seconds, map_horizon_seconds))
        timing_class = "mapped_excursion"
    elif entry_ready:
        recommended = int(max(standard_sec, structural_target_seconds))
        timing_class = "trigger_confirmation"
    elif strong_clean_continuation:
        recommended = int(max(standard_sec, min(map_horizon_seconds, structural_target_seconds)))
        timing_class = "clean_continuation"
    else:
        recommended = int(max(standard_sec, min(map_horizon_seconds, structural_target_seconds)))
        timing_class = "measured_continuation"
    recommended = int(max(min_sec, min(max_sec, recommended)))
    if (
        entry_allowed
        and jpclf_recommended_duration_seconds
        >= MINIMUM_ELIGIBLE_TRADE_DURATION_SECONDS
    ):
        recommended = int(
            max(
                min_sec,
                min(max_sec, jpclf_recommended_duration_seconds),
            )
        )

    rationale = (
        "wait for price to rotate into the mapped significant entry area"
        if not entry_allowed and "significant" in block_reason
        else "wait for rejection/breakout at opposing force"
        if not entry_allowed
        else "use the mapped countertrend window; do not force a fixed M3/M5 expiry"
        if lane_key == "COUNTERTREND_SCALP"
        else "active opposing force reaction uses the mapped target/stale/invalidation timing window"
        if reaction_lane
        else "current live flow uses adaptive target timing above the 15-minute eligibility floor"
        if current_market_lane
        else "compress only because reversal/opposing-force pressure is active"
        if compression_pressure and not breakout_confirmation
        else "breakout confirmation allows the trade to seek the mapped excursion beyond resistance/support"
        if breakout_confirmation
        else "trigger accepted; let price travel toward the studied target map"
        if entry_ready
        else "clean continuation with mapped timing above the 15-minute eligibility floor"
        if strong_clean_continuation
        else "measured continuation using historical target timing"
    )
    duration_policy = duration_eligibility_contract_v3(recommended)
    return {
        "version": "jpclf_aware_timing_v3",
        "side": execution_side if execution_side in {"BUY", "SELL"} else "HOLD",
        "candidate_side": side if side in {"BUY", "SELL"} else "HOLD",
        "lane": lane_key,
        "timeframe": str(timeframe or "").upper(),
        "timeframe_seconds": int(timeframe_sec),
        "target_horizon_candles": int(target_horizon),
        "target_horizon_seconds": int(map_horizon_seconds),
        "eta_trigger_candles": int(eta_trigger_candles),
        "eta_trigger_seconds": int(eta_trigger_seconds),
        "eta_target_after_trigger_candles": int(eta_target_candles),
        "eta_target_after_trigger_seconds": int(eta_target_seconds),
        "eta_invalidation_candles": int(eta_invalidation_candles),
        "eta_invalidation_seconds": int(eta_invalidation_seconds),
        "stale_after_candles": int(stale_after_candles),
        "stale_after_seconds": int(stale_after_seconds),
        "hold_for_candles": int(hold_for_candles),
        "hold_intent_seconds": int(hold_intent_seconds),
        "structural_target_seconds": int(structural_target_seconds),
        "countertrend_window_candles": int(countertrend_window),
        "recommended_expiry_seconds": int(recommended),
        "expiry_seconds": int(recommended),
        "recommended_candles": round(float(recommended) / float(max(1, timeframe_sec)), 3),
        "minimum_seconds": int(min_sec),
        "maximum_seconds": int(max_sec),
        "timing_class": timing_class,
        "entry_allowed": bool(entry_allowed),
        "block_reason": block_reason,
        "rationale": rationale,
        "quick_profit_mode": bool(recommended <= standard_sec),
        "hold_intent": "mapped_excursion" if recommended > standard_sec else "compressed_or_tactical",
        "duration_policy": duration_policy,
        "minimum_eligible_duration_seconds": (
            MINIMUM_ELIGIBLE_TRADE_DURATION_SECONDS
        ),
        "under_15_minutes_excluded": True,
        "path_clock_liquidity_timing_v3": jpclf_timing,
        "jpclf_timing_supports_entry": bool(
            jpclf_timing.get("timing_supports_entry", False)
        ),
        "jpclf_timing_veto": bool(jpclf_timing.get("timing_veto", False)),
        "price_position": price_position,
        "global_extreme_risk": round(float(extreme_risk), 4),
        "history_area_risk": round(float(history_area_risk), 4),
        "history_area_label": history_area_label,
        "history_area_position": round(float(history_area_position), 4),
        "history_area_sample_size": int(history_sample_size),
        "favorable_history_reclaim": bool(favorable_history_reclaim),
        "favorable_history_rejection": bool(favorable_history_rejection),
        "historical_entry_anchor": bool(historical_entry_anchor),
        "significant_entry_context": bool(significant_entry_context),
        "significant_zone_entry_context": bool(significant_zone_entry_context),
        "preferred_entry_area": preferred_entry_area,
        "must_wait_for_significant_area": bool(
            side in {"BUY", "SELL"}
            and history_sample_size >= _EXECUTION_HISTORY_AREA_MIN_SAMPLE
            and not significant_entry_context
            and not current_flow_continuation_ready
        ),
        "entry_area_score": round(float(entry_area_score), 4),
        "entry_area_distance_norm": round(float(entry_area_distance), 4),
        "entry_area_relation": entry_area_relation,
        "entry_area_near": bool(entry_area_near),
        "entry_area_zone": entry_area_zone,
        "entry_area_zones": entry_area_zones[:8],
        "entry_area_count": int(len(entry_area_zones)),
        "historical_area_rule": "buy_lows_sell_highs",
        "opposing_force_risk": round(float(opposing_force_risk), 4),
        "opposing_force_zone": opposing_zone,
        "opposing_force_zones": opposing_zones[:8],
        "opposing_force_count": int(len(opposing_zones)),
        "clear_path_score": round(float(clear_path_score), 4),
        "compression_pressure": bool(compression_pressure),
        "breakout_confirmation": bool(breakout_confirmation),
        "current_flow_continuation_ready": bool(current_flow_continuation_ready),
        "current_flow_direction_confirmed": bool(current_flow_direction_confirmed),
        "current_flow_alignment": int(current_flow_alignment),
        "current_flow_conflicts": int(current_flow_conflicts),
        "current_flow_score": round(
            float(
                _clip01(
                    0.24 * p_trigger_next_1
                    + 0.22 * p_trigger_next_3
                    + 0.22 * p_target
                    + 0.16 * p_next_side
                    + 0.16 * clear_path_score
                )
            ),
            4,
        ),
        "history_extension_against_side": bool(history_extension_against_side),
        "history_extension_stretched": bool(history_extension_stretched),
        "p_target_before_invalidation": round(float(p_target), 4),
        "p_trigger_next_1": round(float(p_trigger_next_1), 4),
        "p_trigger_next_3": round(float(p_trigger_next_3), 4),
        "p_expire_before_trigger": round(float(p_expire_before_trigger), 4),
        "p_next_side": round(float(p_next_side), 4),
        "hazard_trigger": round(float(hazard_trigger), 4),
        "hazard_invalidation": round(float(hazard_invalidation), 4),
        "opposing_ratio": round(float(opposing_ratio), 4),
        "reversal_score": round(float(reversal_score), 4),
        "continuation_score": round(float(continuation_score), 4),
        "entry_state": entry_state,
        "kernel_state": kernel_state,
    }


def _kernel_trigger_promotion_decision(
    latest_signal: Mapping[str, Any],
    tracking_summary: Mapping[str, Any],
    timing_profile: Mapping[str, Any],
) -> dict[str, Any]:
    execution_side = _upper_action(latest_signal.get("execution_action", "HOLD"))
    side = _upper_action(
        latest_signal.get(
            "action",
            latest_signal.get("candidate_action", latest_signal.get("headline_action", "HOLD")),
        )
    )
    if execution_side in {"BUY", "SELL"}:
        return {"accepted": False, "side": execution_side, "reason": "Signal is already executable."}
    if side not in {"BUY", "SELL"}:
        return {"accepted": False, "side": "HOLD", "reason": "No BUY/SELL candidate side is present."}
    if not bool(timing_profile.get("entry_allowed", True)):
        return {
            "accepted": False,
            "side": side,
            "reason": str(timing_profile.get("block_reason", "Timing profile rejected this area.") or "Timing profile rejected this area."),
        }

    kernel = _mapping_to_dict(tracking_summary.get("decision_kernel", latest_signal.get("decision_kernel", {})))
    if not kernel:
        return {"accepted": False, "side": side, "reason": "Decision kernel is missing."}
    kernel_state = str(kernel.get("state", latest_signal.get("setup_state", "")) or "").upper()
    entry_state = str(latest_signal.get("entry_state", tracking_summary.get("entry_state", "")) or "").upper()
    trade_mode = str(kernel.get("trade_mode", "") or "").upper()
    next_event = str(kernel.get("next_most_likely_event", "") or "").strip().lower()
    decision = str(kernel.get("decision", "") or "").upper()
    if entry_state in {"INVALIDATED", "COMPLETE"} or kernel_state in {"INVALIDATED", "COMPLETE", "STALE"}:
        return {"accepted": False, "side": side, "reason": f"Setup is {entry_state or kernel_state}; no promotion allowed."}
    if trade_mode != "TREND_FOLLOW":
        return {"accepted": False, "side": side, "reason": f"Kernel mode {trade_mode or 'MISSING'} is not a trend-follow trigger."}
    if kernel_state not in {"ARMED", "TRIGGERED", "ACTIVE"}:
        return {"accepted": False, "side": side, "reason": f"Kernel state {kernel_state or 'MISSING'} is not armed."}
    if decision in {"STAND_ASIDE", "INVALIDATE", "CANCEL", "CANCELLED"}:
        return {"accepted": False, "side": side, "reason": f"Kernel decision is {decision}."}
    if next_event != "trigger" and kernel_state not in {"TRIGGERED", "ACTIVE"}:
        return {"accepted": False, "side": side, "reason": f"Kernel expects {next_event or 'no event'} next, not trigger."}

    dominant_side = _upper_action(kernel.get("dominant_side", "HOLD"))
    major_side = _upper_action(kernel.get("major_trend_side", "HOLD"))
    candle_side = _upper_action(kernel.get("candle_execution_side", "HOLD"))
    next_bias = _upper_action(kernel.get("next_candle_bias", "HOLD"))
    for label, value in (
        ("dominant side", dominant_side),
        ("major trend side", major_side),
        ("candle side", candle_side),
        ("next candle bias", next_bias),
    ):
        if value in {"BUY", "SELL"} and value != side:
            return {"accepted": False, "side": side, "reason": f"Kernel {label} {value} conflicts with {side}."}

    p_trigger_next_1 = _clip01(kernel.get("p_trigger_next_1", 0.0))
    p_trigger_next_3 = _clip01(kernel.get("p_trigger_next_3", p_trigger_next_1))
    p_target = _clip01(kernel.get("p_target_before_invalidation", latest_signal.get("target_first_probability", 0.0)))
    p_expire_before_trigger = _clip01(kernel.get("p_expire_before_trigger", 0.0))
    if p_trigger_next_1 < _EXECUTION_KERNEL_TRIGGER_MIN_P1 and p_trigger_next_3 < _EXECUTION_KERNEL_TRIGGER_MIN_P3:
        return {"accepted": False, "side": side, "reason": "Trigger probability is not strong enough for early execution."}
    if p_target < _EXECUTION_KERNEL_TRIGGER_MIN_TARGET:
        return {"accepted": False, "side": side, "reason": "Target-before-invalidation probability is too weak."}
    if p_expire_before_trigger >= 0.55:
        return {"accepted": False, "side": side, "reason": "Setup is too likely to expire before trigger."}

    trigger_distances: list[float] = []
    for raw_value in (
        kernel.get("distance_to_trigger"),
        _mapping_to_dict(latest_signal.get("entry_distance", {})).get("trigger"),
        _mapping_to_dict(tracking_summary.get("entry_distance", {})).get("trigger"),
    ):
        distance = _float_or(raw_value, float("nan"))
        if np.isfinite(distance):
            trigger_distances.append(_clip01(distance))
    tokens = _sequence_of_mappings(_mapping_to_dict(tracking_summary.get("behavior", {})).get("candle_tokens", []))
    if tokens:
        distance = _float_or(tokens[-1].get("distance_to_trigger"), float("nan"))
        if np.isfinite(distance):
            trigger_distances.append(_clip01(distance))
    trigger_distance = min(trigger_distances) if trigger_distances else 1.0
    try:
        eta_trigger = int(kernel.get("eta_trigger_candles", 99) or 99)
    except (TypeError, ValueError):
        eta_trigger = 99
    if trigger_distance > _EXECUTION_KERNEL_TRIGGER_NEAR_DISTANCE and eta_trigger > 1 and p_trigger_next_1 < 0.86:
        return {"accepted": False, "side": side, "reason": "Trigger is still too far from the current candle."}

    price_position = _mapping_to_dict(timing_profile.get("price_position", {}))
    global_position = _clip01(price_position.get("global_position", 0.5))
    local_position = _clip01(price_position.get("local_position", 0.5))
    close_position = _clip01(price_position.get("close_position", local_position))
    current_flow_ready = bool(timing_profile.get("current_flow_continuation_ready", False))
    if side == "BUY" and max(global_position, local_position, close_position) >= _EXECUTION_BUY_HISTORY_HIGH_POSITION:
        if not bool(timing_profile.get("favorable_history_reclaim", False)) and not current_flow_ready:
            return {"accepted": False, "side": side, "reason": "BUY trigger is already stretched into upper studied history."}
    if side == "SELL" and min(global_position, local_position, close_position) <= _EXECUTION_SELL_HISTORY_LOW_POSITION:
        if not bool(timing_profile.get("favorable_history_rejection", False)) and not current_flow_ready:
            return {"accepted": False, "side": side, "reason": "SELL trigger is already stretched into lower studied history."}
    timing_history_sample = int(_float_or(timing_profile.get("history_area_sample_size", 0), 0.0) or 0)
    if (
        timing_history_sample >= _EXECUTION_HISTORY_AREA_MIN_SAMPLE
        and not bool(timing_profile.get("significant_entry_context", True))
        and not current_flow_ready
    ):
        return {"accepted": False, "side": side, "reason": "Trigger is not located at a significant historical support/resistance entry area."}

    opposing_force_risk = _clip01(timing_profile.get("opposing_force_risk", 0.0))
    clear_path_score = _clip01(timing_profile.get("clear_path_score", 0.0))
    if opposing_force_risk >= 0.68 and p_target < 0.74:
        return {"accepted": False, "side": side, "reason": "Nearest opposing force is too close for early trigger execution."}
    if clear_path_score < 0.46 and p_trigger_next_1 < 0.84:
        return {"accepted": False, "side": side, "reason": "Mapped path is not clean enough for early trigger execution."}

    return {
        "accepted": True,
        "side": side,
        "reason": (
            f"Kernel trigger accepted: p1={p_trigger_next_1:.2f}, p3={p_trigger_next_3:.2f}, "
            f"target={p_target:.2f}, distance={trigger_distance:.2f}."
        ),
        "trigger_distance": round(float(trigger_distance), 4),
        "eta_trigger_candles": int(eta_trigger),
    }




def _friendly_phrase(value: Any, fallback: str = "--") -> str:
    text = str(value or "").strip().replace("_", " ")
    text = re.sub(r"\s+", " ", text)
    return text or fallback


def _slugify(value: str, fallback: str) -> str:
    slug = re.sub(r"[^A-Za-z0-9._-]+", "_", str(value or "")).strip("._").lower()
    return slug or fallback


def _read_json_payload(path: Path) -> Any:
    data = path.read_bytes()
    try:
        import orjson

        return orjson.loads(data)
    except ImportError:
        return json.loads(data.decode("utf-8"))
    except Exception:
        return json.loads(data.decode("utf-8"))


def _read_json(path: Path, default: Any) -> Any:
    last_error: Exception | None = None
    primary_payload: Any = None
    primary_loaded = False
    primary_mtime_ns = 0
    for attempt in range(5):
        try:
            primary_payload = _read_json_payload(path)
            primary_loaded = True
            try:
                primary_mtime_ns = int(path.stat().st_mtime_ns)
            except OSError:
                primary_mtime_ns = 0
            break
        except (FileNotFoundError, PermissionError, OSError) as exc:
            last_error = exc
        except (json.JSONDecodeError, ValueError) as exc:
            last_error = exc
        except Exception as exc:
            last_error = exc
            break
        time.sleep(0.02 * float(attempt + 1))

    fallback_path = path.with_suffix(path.suffix + ".last_good")
    fallback_payload: Any = None
    fallback_loaded = False
    fallback_mtime_ns = 0
    if fallback_path.exists():
        try:
            fallback_mtime_ns = int(fallback_path.stat().st_mtime_ns)
        except OSError:
            fallback_mtime_ns = 0
        fallback_may_be_newer = (not primary_loaded) or fallback_mtime_ns + 1_000_000 >= primary_mtime_ns
    else:
        fallback_may_be_newer = False
    if fallback_may_be_newer:
        try:
            fallback_payload = _read_json_payload(fallback_path)
            fallback_loaded = True
        except Exception:
            pass
    if primary_loaded:
        if fallback_loaded and _json_snapshot_freshness_key(fallback_payload, fallback_mtime_ns) > _json_snapshot_freshness_key(
            primary_payload,
            primary_mtime_ns,
        ):
            return fallback_payload
        return primary_payload
    if fallback_loaded:
        return fallback_payload
    if last_error is not None:
        LOGGER.debug("Unable to read JSON from %s; returning default: %s", path, last_error)
    return default


def _encode_json_mapping(payload: Mapping[str, Any]) -> bytes:
    try:
        import orjson

        return orjson.dumps(
            dict(payload),
            option=orjson.OPT_NON_STR_KEYS,
            default=str,
        )
    except Exception:
        return json.dumps(
            dict(payload),
            ensure_ascii=True,
            separators=(",", ":"),
            default=str,
        ).encode("utf-8")


def _json_snapshot_freshness_key(payload: Any, mtime_ns: int) -> tuple[float, int, int]:
    if not isinstance(payload, Mapping):
        return (0.0, 0, int(mtime_ns or 0))
    row = cast(Mapping[str, Any], payload)
    latest_signal = row.get("latest_signal", {})
    latest_signal_payload = _mapping_to_dict(latest_signal)
    epoch = max(
        _float_or(row.get("last_capture_epoch") or row.get("last_capture_started_epoch"), 0.0),
        _float_or(latest_signal_payload.get("published_epoch") or latest_signal_payload.get("capture_started_epoch"), 0.0),
    )
    version = int(
        max(
            _float_or(row.get("state_version"), 0.0),
            _float_or(row.get("decision_version"), 0.0),
            _float_or(row.get("capture_count"), 0.0),
            _float_or(row.get("frame_index"), 0.0),
        )
    )
    return (float(epoch), int(version), int(mtime_ns or 0))


def _write_json_atomic(path: Path, payload: Mapping[str, Any]) -> None:
    path.parent.mkdir(parents=True, exist_ok=True)
    payload_bytes = _encode_json_mapping(payload)
    last_error: Exception | None = None
    for attempt in range(10):
        tmp_path = path.with_name(f"{path.name}.{uuid4().hex}.tmp")
        try:
            tmp_path.write_bytes(payload_bytes)
            tmp_path.replace(path)
            return
        except (FileNotFoundError, PermissionError, OSError) as exc:
            last_error = exc
            try:
                if tmp_path.exists():
                    tmp_path.unlink()
            except OSError:
                pass
            time.sleep(0.05 * float(attempt + 1))
    fallback_path = path.with_suffix(path.suffix + ".last_good")
    try:
        fallback_path.write_bytes(payload_bytes)
        LOGGER.warning(
            "Session JSON atomic replace stayed locked; wrote fallback snapshot to %s instead of crashing worker: %s",
            fallback_path,
            last_error,
        )
        return
    except Exception:
        if last_error is not None:
            raise last_error
        raise


def write_json_atomic(path: Path, payload: Mapping[str, Any]) -> None:
    _write_json_atomic(path, payload)


def _memory_bank_cache_fingerprint(bank_dir: Path) -> tuple[int, ...]:
    candidates = (
        bank_dir,
        bank_dir / "metadata.json",
        bank_dir / "stats.json",
        bank_dir / "index" / "id_map.json",
        bank_dir / "index" / "numpy_vecs.npy",
        bank_dir / "index" / "hnsw.bin",
    )
    parts: list[int] = []
    for candidate in candidates:
        try:
            stat = candidate.stat()
        except OSError:
            parts.extend((0, 0))
            continue
        parts.extend((int(stat.st_mtime_ns), int(stat.st_size)))
    return tuple(parts)


@lru_cache(maxsize=4)
def _load_phoenixguard_memory_bank_cached(bank_dir: str, fingerprint: tuple[int, ...]) -> Any | None:
    _ = fingerprint
    try:
        from phoenixguard.memory.memory_ingest import MemoryBank
    except Exception as exc:
        LOGGER.warning("PhoenixGuard memory import failed: %s", exc)
        return None
    try:
        bank = MemoryBank.load(Path(bank_dir), logger=LOGGER)
    except Exception as exc:
        LOGGER.warning("PhoenixGuard memory load failed from %s: %s", bank_dir, exc)
        return None
    if getattr(bank, "is_loaded", False):
        return bank
    return None


def _load_phoenixguard_memory_bank(bank_dir: Path) -> Any | None:
    resolved = bank_dir.resolve()
    fingerprint = _memory_bank_cache_fingerprint(resolved)
    # ``lru_cache`` is coherent but may execute the same uncached call twice
    # when warmup and an operator click arrive together.  Serializing only the
    # cold load prevents two native model stacks from competing for memory.
    with _PHOENIXGUARD_MEMORY_BANK_LOAD_LOCK:
        return _load_phoenixguard_memory_bank_cached(str(resolved), fingerprint)


def _resolve_memory_source_path(image_path: Any) -> Path:
    raw = str(image_path or "").strip()
    if not raw:
        return Path("")
    try:
        from phoenixguard.memory import memory_ingest
    except Exception:
        return Path(raw)
    try:
        resolve_memory_image_path = getattr(memory_ingest, "_resolve_memory_image_path", None)
        if callable(resolve_memory_image_path):
            resolved_path = resolve_memory_image_path(raw)
            return Path(str(resolved_path))
    except Exception:
        pass
    return Path(raw)


def _title_matches_query(title: Any, query: Any) -> bool:
    lowered_title = str(title or "").strip().lower()
    lowered_query = str(query or "").strip().lower()
    if not lowered_query:
        return True
    if lowered_query in lowered_title:
        return True
    compact_query = _compact_text(lowered_query)
    return bool(compact_query) and compact_query in _compact_text(lowered_title)


def _window_query_fallback_tokens(query: Any) -> tuple[str, ...]:
    lowered_query = str(query or "").strip().lower()
    compact_query = _compact_text(lowered_query)
    tokens: list[str] = []
    if compact_query in {"pocketoption", "pocketoptions"} or "pocket option" in lowered_query:
        tokens.extend(_POCKET_OPTION_WINDOW_FALLBACK_TOKENS)
    elif "tradingview" in compact_query or "trading view" in lowered_query:
        tokens.extend(_TRADINGVIEW_WINDOW_FALLBACK_TOKENS)
    elif compact_query in {"edge", "chrome", "browser", "firefox", "opera"}:
        tokens.extend(_BROWSER_TITLE_TOKENS)
    return tuple(dict.fromkeys(token for token in tokens if str(token).strip()))


def _is_pocket_option_query(query: Any) -> bool:
    lowered_query = str(query or "").strip().lower()
    compact_query = _compact_text(lowered_query)
    return (
        "pocket option" in lowered_query
        or compact_query in {"pocketoption", "pocketoptions"}
        or "the most innovative trading platform" in lowered_query
    )


def _is_pocket_option_like_title(title: Any) -> bool:
    lowered_title = str(title or "").strip().lower()
    compact_title = _compact_text(lowered_title)
    return (
        "pocket option" in lowered_title
        or "pocketoption" in compact_title
        or "the most innovative trading platform" in lowered_title
    )


def _is_tradingview_query(query: Any) -> bool:
    lowered_query = str(query or "").strip().lower()
    compact_query = _compact_text(lowered_query)
    return "tradingview" in compact_query or "trading view" in lowered_query


def _is_tradingview_like_title(title: Any) -> bool:
    lowered_title = str(title or "").strip().lower()
    compact_title = _compact_text(lowered_title)
    return "tradingview" in compact_title or "trading view" in lowered_title or "supercharts" in compact_title


class CaptureSurfaceUnavailableError(RuntimeError):
    """Raised when a matched browser window is visible but does not contain a usable trading surface."""


class StaleCPUStreamKeyframeError(RuntimeError):
    """Raised when an immutable stream keyframe no longer matches live session identity."""


class ExternalSourceLeaseError(RuntimeError):
    """Raised when a generation-fenced source mutation targets a stale lease."""

    def __init__(self, *, status_code: int, reason_code: str, message: str) -> None:
        super().__init__(str(message or reason_code or "External source lease is not current."))
        self.status_code = int(status_code)
        self.reason_code = str(reason_code or "SOURCE_SUPERSEDED")
        self.message = str(message or "External source lease is not current.")

    def as_detail(self) -> dict[str, str]:
        return {
            "reason_code": self.reason_code,
            "message": self.message,
        }


def _capture_looks_like_pocket_option_surface(image: Image.Image) -> bool:
    try:
        width, height = image.size
    except Exception:
        return False
    if width < 480 or height < 320:
        return False
    try:
        arr = np.asarray(image.convert("RGB"))
    except Exception:
        return False
    if arr.ndim != 3 or arr.shape[2] < 3:
        return False

    # PocketOption's full broker surface has large BUY/SELL controls in the
    # right control rail. A stale browser title can otherwise point at another
    # tab, so require those controls before using the image for live studies.
    y0 = max(0, int(round(height * 0.22)))
    y1 = min(height, int(round(height * 0.70)))
    x0 = max(0, int(round(width * 0.76)))
    x1 = min(width, int(round(width * 0.98)))
    panel = arr[y0:y1, x0:x1, :3].astype(np.int16, copy=False)
    if panel.size == 0:
        return False
    red = panel[:, :, 0]
    green = panel[:, :, 1]
    blue = panel[:, :, 2]
    green_pixels = int(
        np.count_nonzero(
            (green >= 120)
            & (red <= 115)
            & (blue <= 145)
            & ((green - red) >= 45)
            & ((green - blue) >= 25)
        )
    )
    red_pixels = int(
        np.count_nonzero(
            (red >= 165)
            & (green <= 130)
            & (blue <= 140)
            & ((red - green) >= 45)
        )
    )
    area = max(1, int(panel.shape[0] * panel.shape[1]))
    minimum_pixels = max(240, int(round(area * 0.0035)))
    return bool(green_pixels >= minimum_pixels and red_pixels >= minimum_pixels)


def _capture_looks_like_pocket_option_visible_surface(
    image: Image.Image,
    descriptor: Mapping[str, Any] | None = None,
    *,
    require_broker_page_evidence: bool = False,
) -> bool:
    row = _mapping_to_dict(descriptor or {})
    visible_title = str(
        row.get("visible_title", row.get("current_title", row.get("foreground_title", ""))) or ""
    ).strip()
    if visible_title and (
        not _is_pocket_option_like_title(visible_title)
        or _title_has_any_token(visible_title, _WINDOW_REACQUIRE_BLOCK_TOKENS)
    ):
        return False
    expected_hwnd = int(row.get("hwnd", row.get("window_handle", 0)) or 0)
    foreground_before = int(row.get("foreground_hwnd_before", expected_hwnd) or 0)
    foreground_after = int(row.get("foreground_hwnd_after", expected_hwnd) or 0)
    if expected_hwnd > 0 and (
        foreground_before != expected_hwnd or foreground_after != expected_hwnd
    ):
        return False
    if _capture_looks_like_pocket_option_surface(image):
        return True
    if require_broker_page_evidence:
        # A PhoenixGuard dashboard can contain a real broker screenshot and
        # therefore look chart-like. Visible recovery is allowed to accept
        # only positive Pocket Option page evidence, never a generic chart.
        return False
    try:
        lock = _broker_source_lock_dict_v3(
            row,
            image,
            window_query=row.get("title", row.get("window_query", "")),
            study_source_expected=True,
        )
    except Exception:
        return False
    reason_codes = {str(item) for item in cast(Sequence[Any], lock.get("reason_codes", []))}
    return bool(lock.get("valid", False)) and bool(
        reason_codes.intersection({"CHART_SOURCE_PIXELS_CONFIRMED", "CHART_STUDY_SOURCE_LOCKED"})
    )


def _broker_source_lock_payload_v3(
    descriptor: Mapping[str, Any],
    window_image: Image.Image,
    *,
    broker_surface: Mapping[str, Any] | None = None,
    window_query: Any = "",
    study_source_expected: bool = False,
) -> dict[str, Any]:
    try:
        width, height = window_image.size
    except Exception:
        width, height = (0, 0)
    row = _mapping_to_dict(descriptor)
    title = str(row.get("title", row.get("window_title", "")) or "")
    query_text = str(window_query or row.get("window_query", "") or "").strip()
    row.update(
        {
            "title": title,
            "locked_title": title,
            "window_query": query_text,
            "window_handle": str(row.get("window_handle", row.get("hwnd", row.get("handle", ""))) or ""),
            "hwnd": str(row.get("hwnd", row.get("window_handle", "")) or ""),
            "viewport": {"width": int(width), "height": int(height)},
            "width": int(width),
            "height": int(height),
        }
    )
    if broker_surface is not None:
        row["broker_surface"] = dict(broker_surface)
    if _is_tradingview_query(query_text) or (not query_text and _is_tradingview_like_title(title)):
        row["expected_broker_source_lock"] = {
            "source_role": "study",
            "source_kind": "tradingview",
            "required_browser": "any",
            "broker_title_tokens": ["tradingview", "trading view"],
            "broker_url_tokens": ["tradingview.com", "tradingview"],
        }
    elif study_source_expected:
        pocket_source = _is_pocket_option_query(query_text) or _is_pocket_option_like_title(title)
        generic_title_tokens = [query_text] if query_text else ([title] if title else [])
        row["expected_broker_source_lock"] = {
            "source_role": "study",
            "source_kind": "pocket_option_chart" if pocket_source else "visible_chart",
            "required_browser": "edge" if pocket_source else "any",
            "broker_title_tokens": (
                ["pocket option", "pocketoption", "the most innovative trading platform"]
                if pocket_source
                else generic_title_tokens
            ),
            "broker_url_tokens": ["pocketoption.com", "pocketoption"] if pocket_source else [],
        }
    return row


def _broker_source_lock_dict_v3(
    descriptor: Mapping[str, Any],
    window_image: Image.Image,
    *,
    broker_surface: Mapping[str, Any] | None = None,
    window_query: Any = "",
    study_source_expected: bool = False,
) -> dict[str, Any]:
    return build_broker_source_lock_v3(
        _broker_source_lock_payload_v3(
            descriptor,
            window_image,
            broker_surface=broker_surface,
            window_query=window_query,
            study_source_expected=study_source_expected,
        ),
        image=window_image,
    ).as_dict()


def _broker_source_lock_is_study_only(lock: Mapping[str, Any]) -> bool:
    reason_codes = [str(item) for item in cast(Sequence[Any], lock.get("reason_codes", []))]
    if "CHART_STUDY_SOURCE_LOCKED" in reason_codes:
        return True
    evidence = _mapping_to_dict(lock.get("evidence", {}))
    return bool(evidence.get("study_source_expected", False) or evidence.get("chart_source_like", False))


def _external_frame_source_lock_v3(
    source: Mapping[str, Any],
    window_image: Image.Image,
    *,
    window_signature: str,
) -> dict[str, Any]:
    source_id = str(source.get("source_id", "external-frame-feed") or "external-frame-feed").strip()
    source_url = str(source.get("source_url", "") or "").strip()
    sequence_id = str(source.get("sequence_id", "") or "").strip()
    symbol = str(source.get("symbol", "") or "").strip().upper()
    timeframe = str(source.get("timeframe", "") or "").strip().upper()
    source_type = str(source.get("source_type", "external_frame_feed") or "external_frame_feed").strip()
    coordinate_space = str(source.get("coordinate_space", "external_frame_v1") or "external_frame_v1").strip()
    metadata = _mapping_to_dict(source.get("metadata", {}))
    extension_id = str(metadata.get("extension_id", "") or "").strip()
    locked_tab_id = str(metadata.get("locked_tab_id", "") or "").strip()
    lock_basis = "|".join(
        [
            source_id,
            source_type,
            extension_id,
            locked_tab_id,
            sequence_id,
            coordinate_space,
        ]
    )
    lock_id = hashlib.sha256(lock_basis.encode("utf-8", errors="ignore")).hexdigest()[:24]
    return {
        "schema_version": "BROKER_SOURCE_LOCK_V3",
        "status": "VALID",
        "valid": True,
        "broker_source_locked": True,
        "reason": "External frame feed supplied a fresh chart image through the frame-ingest contract.",
        "reason_codes": ["EXTERNAL_FRAME_FEED_LOCKED", "CHART_STUDY_SOURCE_LOCKED"],
        "selected_target": {
            "browser": "edge_extension" if source_type == "browser_extension_capture" else "external_frame_feed",
            "url": source_url,
            "title": source_id,
            "window_handle": "",
            "target_id": lock_id,
            "viewport": {"width": int(window_image.width), "height": int(window_image.height)},
            "candidate_id": lock_id,
        },
        "candidate_count": 1,
        "matching_candidate_count": 1,
        "surface_guard": {
            "schema_version": "DASHBOARD_WINDOW_CAPTURE_GUARD_V3",
            "surface_class": "BROKER_SURFACE",
            "wrong_surface": False,
            "capture_safe": True,
            "broker_like_pixels": True,
            "confidence": 1.0,
            "reason": "External feed is accepted as a study source after API token and freshness validation.",
            "reason_codes": ["EXTERNAL_FRAME_SOURCE"],
            "evidence": {
                "source_id": source_id,
                "source_url": source_url,
                "sequence_id": sequence_id,
                "symbol": symbol,
                "timeframe": timeframe,
                "source_type": source_type,
                "coordinate_space": coordinate_space,
                "extension_id": extension_id,
                "locked_tab_id": locked_tab_id,
            },
        },
        "broker_pixel_fingerprint": window_signature,
        "broker_control_fingerprint": lock_id,
        "viewport_fingerprint": lock_id,
        "evidence": {
            "source_type": source_type,
            "source_id": source_id,
            "source_url": source_url,
            "sequence_id": sequence_id,
            "symbol": symbol,
            "timeframe": timeframe,
            "coordinate_space": coordinate_space,
            "extension_id": extension_id,
            "locked_tab_id": locked_tab_id,
            "study_source_expected": True,
            "chart_source_like": True,
            "study_source_only": True,
            "broker_click_safe": False,
            "chart": {
                "chart_like_pixels": True,
                "source": "frame_ingest_contract",
                "width": int(window_image.width),
                "height": int(window_image.height),
            },
        },
    }


def _external_wgc_broker_identity_attestation_v3(
    source: Mapping[str, Any],
    source_lock: Mapping[str, Any],
    identity_surface: Mapping[str, Any],
    *,
    window_signature: str,
    capture_epoch: float,
) -> dict[str, Any]:
    """Attest chart identity read from the exact leased WGC frame.

    This proof is private to the in-process study call. It lets the full selected
    surface provide instrument identity when the derived candle plane excludes
    the chart header. The reader is deliberately broker-agnostic; authority
    still comes only from the exact WGC lease, lock, pixel signature, and capture
    epoch, and the study source never becomes click-safe.
    """

    source_row = _mapping_to_dict(source)
    metadata = _mapping_to_dict(source_row.get("metadata", {}))
    lock_row = _mapping_to_dict(source_lock)
    lock_evidence = _mapping_to_dict(lock_row.get("evidence", {}))
    surface = _mapping_to_dict(identity_surface)
    source_id = str(source_row.get("source_id", "") or "").strip()
    sequence_id = str(source_row.get("sequence_id", "") or "").strip()
    source_type = str(source_row.get("source_type", "") or "").strip()
    coordinate_space = str(source_row.get("coordinate_space", "") or "").strip()
    source_generation = int(_float_or(source_row.get("source_generation"), 0.0) or 0)
    source_lease_id = str(metadata.get("source_lease_id", "") or "").strip()
    reason_codes = {
        str(item).strip()
        for item in cast(Sequence[Any], lock_row.get("reason_codes", []))
        if str(item).strip()
    }
    exact_wgc_lease = bool(
        source_type == "windows_graphics_capture_roi"
        and coordinate_space == "wgc_hwnd_roi_v1"
        and source_id == "windows-region-capture-v3"
        and sequence_id
        and source_generation > 0
        and source_lease_id
        and bool(lock_row.get("valid", False))
        and str(lock_row.get("status", "") or "").upper() == "VALID"
        and bool(lock_row.get("broker_source_locked", False))
        and _broker_source_lock_is_study_only(lock_row)
        and "EXTERNAL_FRAME_FEED_LOCKED" in reason_codes
        and "CHART_STUDY_SOURCE_LOCKED" in reason_codes
        and str(lock_evidence.get("source_id", "") or "").strip() == source_id
        and str(lock_evidence.get("sequence_id", "") or "").strip() == sequence_id
        and str(lock_evidence.get("source_type", "") or "").strip() == source_type
        and str(lock_evidence.get("coordinate_space", "") or "").strip()
        == coordinate_space
    )
    normalized_signature = str(window_signature or "").strip()
    same_frame_surface = bool(
        normalized_signature
        and str(lock_row.get("broker_pixel_fingerprint", "") or "").strip()
        == normalized_signature
        and str(surface.get("broker_surface_hash", "") or "").strip()
        == normalized_signature
    )
    market = _complete_fx_market_candidate_v3(surface.get("detected_market", ""))
    timeframe = str(surface.get("detected_timeframe", "") or "").strip().upper()
    market_confidence = _clip01(surface.get("market_confidence", 0.0)) if market else 0.0
    timeframe_confidence = _clip01(surface.get("timeframe_confidence", 0.0))
    complete_pair = bool(market)
    recognized_timeframe = timeframe in _TIMEFRAME_LABELS
    if not (
        exact_wgc_lease
        and same_frame_surface
        and not bool(surface.get("identity_conflict", False))
        and complete_pair
        and recognized_timeframe
        and float(capture_epoch or 0.0) > 0.0
    ):
        return {}

    attestation_basis = "|".join(
        (
            source_id,
            sequence_id,
            str(source_generation),
            normalized_signature,
            market,
            timeframe,
        )
    )
    return {
        "schema_version": "PG_WGC_BROKER_IDENTITY_ATTESTATION_V3",
        "attestation_id": hashlib.sha256(
            attestation_basis.encode("utf-8", errors="ignore")
        ).hexdigest()[:24],
        "source_verified": True,
        "study_source_only": True,
        "broker_click_safe": False,
        "source_type": source_type,
        "coordinate_space": coordinate_space,
        "source_id": source_id,
        "sequence_id": sequence_id,
        "source_generation": source_generation,
        "source_frame_signature": normalized_signature,
        "capture_epoch": float(capture_epoch),
        "market": market,
        "market_confidence": market_confidence,
        "market_source": str(
            surface.get("market_source", "chart_header_identity")
            or "chart_header_identity"
        ),
        "timeframe": timeframe,
        "timeframe_confidence": timeframe_confidence,
        "timeframe_source": str(
            surface.get("timeframe_source", "chart_header_identity")
            or "chart_header_identity"
        ),
    }


def _reconcile_wgc_broker_identity_attestation_v3(
    market_selector: Mapping[str, Any],
    timeframe_selector: Mapping[str, Any],
    session_payload: Mapping[str, Any],
    execution_controls: Mapping[str, Any],
) -> tuple[dict[str, Any], dict[str, Any]]:
    """Reconcile a same-frame WGC identity proof with chart-plane selectors."""

    market_row = _mapping_to_dict(market_selector)
    timeframe_row = _mapping_to_dict(timeframe_selector)
    attestation = _mapping_to_dict(
        session_payload.get("_broker_identity_attestation_v3", {})
    )
    capture_epoch = _float_or(
        session_payload.get("_capture_started_epoch_v3"),
        0.0,
    )
    attested_epoch = _float_or(attestation.get("capture_epoch"), 0.0)
    attested_market = _complete_fx_market_candidate_v3(attestation.get("market", ""))
    attested_timeframe = str(attestation.get("timeframe", "") or "").strip().upper()
    min_market_confidence = _clip01(
        execution_controls.get("min_market_confidence", 0.42)
    )
    min_timeframe_confidence = _clip01(
        execution_controls.get("min_timeframe_confidence", 0.42)
    )
    attested_market_confidence = _clip01(attestation.get("market_confidence", 0.0))
    attested_timeframe_confidence = _clip01(
        attestation.get("timeframe_confidence", 0.0)
    )
    proof_valid = bool(
        attestation.get("schema_version")
        == "PG_WGC_BROKER_IDENTITY_ATTESTATION_V3"
        and attestation.get("source_verified") is True
        and attestation.get("study_source_only") is True
        and attestation.get("broker_click_safe") is False
        and str(attestation.get("source_type", "") or "")
        == "windows_graphics_capture_roi"
        and str(attestation.get("coordinate_space", "") or "")
        == "wgc_hwnd_roi_v1"
        and str(attestation.get("attestation_id", "") or "").strip()
        and str(attestation.get("source_frame_signature", "") or "").strip()
        and capture_epoch > 0.0
        and abs(attested_epoch - capture_epoch) <= 0.001
        and bool(attested_market)
        and attested_timeframe in _TIMEFRAME_LABELS
        and attested_market_confidence >= min_market_confidence
        and attested_timeframe_confidence >= min_timeframe_confidence
    )
    if not proof_valid:
        return market_row, timeframe_row

    current_market = _complete_fx_market_candidate_v3(market_row.get("value", ""))
    current_timeframe = str(timeframe_row.get("value", "") or "").strip().upper()
    current_market_root = re.sub(r"\s+OTC$", "", current_market).strip()
    attested_market_root = re.sub(r"\s+OTC$", "", attested_market).strip()
    current_market_pending = bool(
        market_row.get("market_selector_rebind_required", False)
        or market_row.get("studying_new_pair", False)
    )
    market_conflict = bool(
        current_market
        and current_market_root
        and (
            current_market_root != attested_market_root
            or (
                current_market != attested_market
                and not current_market_pending
            )
        )
    )
    timeframe_conflict = bool(
        current_timeframe and current_timeframe != attested_timeframe
    )
    if market_conflict or timeframe_conflict:
        market_row["market_selector_rebind_required"] = True
        market_row["studying_new_pair"] = True
        market_row["broker_identity_attestation_conflict"] = True
        market_row["broker_identity_attestation_id"] = str(
            attestation.get("attestation_id", "") or ""
        )
        timeframe_row["broker_identity_attestation_conflict"] = True
        return market_row, timeframe_row

    identity_was_pending = bool(
        market_row.get("market_selector_rebind_required", False)
        or market_row.get("studying_new_pair", False)
        or not current_market
    )
    market_row.update(
        {
            "value": attested_market,
            "source": "same_frame_wgc_broker_identity",
            "confidence": attested_market_confidence,
            "market_selector_rebind_required": False,
            "studying_new_pair": False,
            "market_selector_identity_rebound": identity_was_pending,
            "broker_identity_attestation_conflict": False,
            "broker_identity_attestation_id": str(
                attestation.get("attestation_id", "") or ""
            ),
        }
    )
    timeframe_row.update(
        {
            "value": attested_timeframe,
            "source": "same_frame_wgc_broker_identity",
            "confidence": attested_timeframe_confidence,
            "broker_identity_attestation_conflict": False,
            "broker_identity_attestation_id": str(
                attestation.get("attestation_id", "") or ""
            ),
        }
    )
    return market_row, timeframe_row


def _browser_family(title: Any) -> str:
    lowered = str(title or "").strip().lower()
    compact = _compact_text(lowered)
    if "microsoft edge" in lowered or "msedge" in compact or "microsoftedge" in compact:
        return "edge"
    if "google chrome" in lowered or compact.endswith("chrome") or "chrome" in lowered:
        return "chrome"
    if "firefox" in lowered:
        return "firefox"
    if "opera" in lowered:
        return "opera"
    return ""


def _title_has_any_token(title: Any, tokens: Sequence[str]) -> bool:
    lowered = str(title or "").strip().lower()
    return any(str(token or "").strip().lower() in lowered for token in tokens if str(token or "").strip())


def _title_matches_window_query(title: Any, query: Any) -> bool:
    if _is_pocket_option_query(query):
        return _is_pocket_option_like_title(title)
    if _is_tradingview_query(query):
        return _is_tradingview_like_title(title)
    if _title_matches_query(title, query):
        return True
    lowered_title = str(title or "").strip().lower()
    compact_title = _compact_text(lowered_title)
    for token in _window_query_fallback_tokens(query):
        lowered_token = str(token or "").strip().lower()
        compact_token = _compact_text(lowered_token)
        if lowered_token and lowered_token in lowered_title:
            return True
        if compact_token and compact_token in compact_title:
            return True
    return False


def _window_descriptor_is_capture_usable(descriptor: Mapping[str, Any]) -> bool:
    if bool(descriptor.get("is_minimized", False)):
        return False
    try:
        width = int(descriptor.get("width", 0) or 0)
        height = int(descriptor.get("height", 0) or 0)
    except (TypeError, ValueError):
        width = 0
        height = 0
    if width < 600 or height < 360:
        return False
    bbox = cast(Sequence[Any], descriptor.get("bbox", []))
    if len(bbox) >= 4:
        try:
            x0, y0, x1, y1 = [int(round(float(value))) for value in bbox[:4]]
            if x0 <= -30000 or y0 <= -30000:
                return False
            if x1 - x0 < 600 or y1 - y0 < 360:
                return False
        except (TypeError, ValueError):
            return False
    return True


def _native_window_identity_fields_v3(user32: Any, hwnd: Any) -> dict[str, Any]:
    """Read stable native identity fields when the desktop API exposes them."""

    try:
        import ctypes
        from ctypes import wintypes

        hwnd_value = wintypes.HWND(int(hwnd or 0))
        if int(hwnd or 0) <= 0:
            return {}
        result: dict[str, Any] = {}
        process_reader = getattr(user32, "GetWindowThreadProcessId", None)
        if callable(process_reader):
            process_id = wintypes.DWORD()
            process_reader(hwnd_value, ctypes.byref(process_id))
            if int(process_id.value) > 0:
                result["process_id"] = int(process_id.value)
        class_reader = getattr(user32, "GetClassNameW", None)
        if callable(class_reader):
            class_buffer = ctypes.create_unicode_buffer(256)
            class_name_length = cast(Callable[..., Any], class_reader)(
                hwnd_value,
                class_buffer,
                len(class_buffer),
            )
            if int(class_name_length or 0) > 0:
                class_name = str(class_buffer.value or "").strip()
                if class_name:
                    result["class_name"] = class_name
        return result
    except Exception:
        return {}


def _cpu_stream_window_identity_matches_v3(
    locked: Mapping[str, Any],
    current: Mapping[str, Any],
    *,
    require_geometry: bool = True,
) -> bool:
    """Match stable identity while tolerating benign browser-title drift."""

    try:
        locked_hwnd = int(locked.get("hwnd", 0) or 0)
        current_hwnd = int(current.get("hwnd", 0) or 0)
    except (TypeError, ValueError):
        return False
    if locked_hwnd <= 0 or current_hwnd != locked_hwnd:
        return False
    if not _window_descriptor_is_capture_usable(current):
        return False

    locked_title = str(locked.get("title", "") or "").strip()
    title_query = str(locked.get("window_query", "") or locked_title).strip()
    current_title = str(current.get("title", "") or "").strip()
    if (
        not title_query
        or not current_title
        or not _title_matches_window_query(current_title, title_query)
        or _title_has_any_token(current_title, _WINDOW_REACQUIRE_BLOCK_TOKENS)
    ):
        return False

    try:
        expected_process = int(
            locked.get("process_id", locked.get("pid", 0)) or 0
        )
        current_process = int(
            current.get("process_id", current.get("pid", 0)) or 0
        )
    except (TypeError, ValueError):
        return False
    if expected_process > 0 and current_process != expected_process:
        return False
    expected_class = str(
        locked.get("class_name", locked.get("window_class", "")) or ""
    ).strip().casefold()
    current_class = str(
        current.get("class_name", current.get("window_class", "")) or ""
    ).strip().casefold()
    if expected_class and current_class != expected_class:
        return False

    if require_geometry:
        locked_bbox = list(cast(Sequence[Any], locked.get("bbox", [])))[:4]
        current_bbox = list(cast(Sequence[Any], current.get("bbox", [])))[:4]
        if len(locked_bbox) == 4 and current_bbox != locked_bbox:
            return False
        if len(locked_bbox) != 4:
            for dimension in ("width", "height"):
                try:
                    expected = int(locked.get(dimension, 0) or 0)
                    observed = int(current.get(dimension, 0) or 0)
                except (TypeError, ValueError):
                    return False
                if expected > 0 and observed != expected:
                    return False
    return True


def _normalize_focus_region_bbox(
    normalized_bbox: Sequence[Any],
    *,
    min_fraction: float = 0.04,
) -> list[float]:
    if len(normalized_bbox) < 4:
        raise ValueError("Focus region must contain four normalized coordinates.")
    left = max(0.0, min(1.0, float(normalized_bbox[0])))
    top = max(0.0, min(1.0, float(normalized_bbox[1])))
    right = max(left + 1e-6, min(1.0, float(normalized_bbox[2])))
    bottom = max(top + 1e-6, min(1.0, float(normalized_bbox[3])))
    if (right - left) < float(min_fraction) or (bottom - top) < float(min_fraction):
        raise ValueError("Focus region is too small. Select a larger chart area.")
    return [left, top, right, bottom]


def normalize_focus_region_bbox(
    normalized_bbox: Sequence[Any],
    *,
    min_fraction: float = 0.04,
) -> list[float]:
    return _normalize_focus_region_bbox(normalized_bbox, min_fraction=min_fraction)


def _public_manual_focus_region(value: Any) -> dict[str, Any]:
    region = _mapping_to_dict(value)
    normalized_bbox: list[float] = []
    raw_bbox = cast(Sequence[Any], region.get("normalized_bbox", []))
    if len(raw_bbox) >= 4:
        try:
            normalized_bbox = _normalize_focus_region_bbox(raw_bbox)
        except ValueError:
            normalized_bbox = []
    enabled = bool(region.get("enabled", False)) and len(normalized_bbox) == 4
    return {
        "enabled": enabled,
        "normalized_bbox": normalized_bbox if enabled else [],
        "source": str(region.get("source", "") or ""),
        "updated_at": str(region.get("updated_at", "") or ""),
    }


def _default_capture_source_v3(*, state: str = "NO_SOURCE", message: str = "No chart source is selected.") -> dict[str, Any]:
    return {
        "schema_version": "PG_CAPTURE_SOURCE_V3",
        "state_revision": 0,
        "state": str(state or "NO_SOURCE").upper(),
        "selection_state": "IDLE",
        "source_id": "",
        "source_generation": 0,
        "source_lease_id": "",
        "source_type": "",
        "source_kind": "",
        "transport": "",
        "display_name": "",
        "coordinate_space": "",
        "selection_id": "",
        "sequence_id": "",
        "decision_usable": False,
        "fresh": False,
        "reason_code": str(state or "NO_SOURCE").upper(),
        "message": str(message or ""),
        "selected_at": 0.0,
        "updated_at": _now_epoch(),
        "last_frame_epoch": 0.0,
        "last_frame_id": 0,
        "frame_age_sec": 0.0,
        "stale_after_sec": 20.0,
        "roi": {},
        "stream": {},
    }


def _normalize_capture_source_v3(value: Any) -> dict[str, Any]:
    row = _mapping_to_dict(value)
    normalized = _default_capture_source_v3()
    normalized.update(row)
    normalized["schema_version"] = "PG_CAPTURE_SOURCE_V3"
    normalized["state_revision"] = max(0, int(_float_or(row.get("state_revision"), 0.0) or 0))
    normalized["state"] = str(row.get("state", "NO_SOURCE") or "NO_SOURCE").strip().upper()
    normalized["selection_state"] = str(row.get("selection_state", "IDLE") or "IDLE").strip().upper()
    normalized["source_generation"] = max(0, int(_float_or(row.get("source_generation"), 0.0) or 0))
    normalized["source_lease_id"] = str(
        row.get("source_lease_id", "") or row.get("lease_id", "") or ""
    ).strip()
    normalized.pop("lease_id", None)
    for key in (
        "source_id",
        "source_type",
        "source_kind",
        "transport",
        "display_name",
        "coordinate_space",
        "selection_id",
        "sequence_id",
        "reason_code",
        "message",
    ):
        normalized[key] = str(row.get(key, normalized.get(key, "")) or "").strip()
    for key in ("selected_at", "updated_at", "last_frame_epoch"):
        normalized[key] = max(0.0, _float_or(row.get(key, normalized.get(key, 0.0)), 0.0))
    normalized["last_frame_id"] = max(0, int(_float_or(row.get("last_frame_id"), 0.0) or 0))
    normalized["decision_usable"] = bool(row.get("decision_usable", False))
    normalized["fresh"] = bool(row.get("fresh", False))
    normalized["roi"] = _mapping_to_dict(row.get("roi", {}))
    normalized["stream"] = _mapping_to_dict(row.get("stream", {}))
    return normalized


def _public_capture_source_v3(value: Any, *, include_lease: bool = False) -> dict[str, Any]:
    row = _normalize_capture_source_v3(value)
    state = str(row.get("state", "NO_SOURCE") or "NO_SOURCE").strip().upper()
    now_epoch = _now_epoch()
    last_frame_epoch = _float_or(row.get("last_frame_epoch", 0.0), 0.0)
    frame_age_sec = max(0.0, now_epoch - last_frame_epoch) if last_frame_epoch > 0.0 else 0.0
    stale_after_sec = _env_float("PHOENIXGUARD_SELECTED_SOURCE_STALE_SEC", 20.0, 5.0)
    fresh = bool(row.get("fresh", False)) and last_frame_epoch > 0.0 and frame_age_sec <= stale_after_sec
    decision_usable = bool(row.get("decision_usable", False)) and fresh and state == "LIVE"
    reason_code = str(row.get("reason_code", state) or state)
    message = str(row.get("message", "") or "")
    if state == "LIVE" and not fresh:
        state = "STALE"
        reason_code = "SOURCE_STALE"
        message = "The selected chart stopped delivering fresh frames. Choose it again or select another source."
        decision_usable = False
    public = {
        "schema_version": "PG_CAPTURE_SOURCE_V3",
        "state_revision": int(row.get("state_revision", 0) or 0),
        "state": state,
        "selection_state": str(row.get("selection_state", "IDLE") or "IDLE").upper(),
        "source_id": str(row.get("source_id", "") or ""),
        "source_generation": int(row.get("source_generation", 0) or 0),
        "source_type": str(row.get("source_type", "") or ""),
        "source_kind": str(row.get("source_kind", "") or ""),
        "transport": str(row.get("transport", "") or ""),
        "display_name": str(row.get("display_name", "") or ""),
        "coordinate_space": str(row.get("coordinate_space", "") or ""),
        "selection_id": str(row.get("selection_id", "") or ""),
        "sequence_id": str(row.get("sequence_id", "") or ""),
        "decision_usable": decision_usable,
        "fresh": fresh,
        "reason_code": reason_code,
        "message": message,
        "selected_at": _float_or(row.get("selected_at", 0.0), 0.0),
        "updated_at": _float_or(row.get("updated_at", 0.0), 0.0),
        "last_frame_epoch": last_frame_epoch,
        "last_frame_id": int(row.get("last_frame_id", 0) or 0),
        "frame_age_sec": round(frame_age_sec, 3),
        "stale_after_sec": round(stale_after_sec, 3),
        "roi": _mapping_to_dict(row.get("roi", {})),
        "stream": _mapping_to_dict(row.get("stream", {})),
        "hotkeys": {
            "desktop_select": "Ctrl+Shift+B",
            "desktop_kill": "Ctrl+Shift+K",
            "edge_select": "Ctrl+Shift+8",
            "edge_kill": "Ctrl+Shift+9",
        },
    }
    if include_lease:
        public["source_lease_id"] = str(row.get("source_lease_id", "") or row.get("lease_id", "") or "")
    return public


def _external_evidence_lineage_v3(
    source: Mapping[str, Any] | None,
    *,
    model_frame_id: int = 0,
    study_surface_signature: str = "",
    published_epoch: float = 0.0,
) -> dict[str, Any]:
    row = _mapping_to_dict(source or {})
    source_id = str(row.get("source_id", "") or "").strip()
    if not source_id:
        return {}
    return {
        "schema_version": "PG_EXTERNAL_EVIDENCE_LINEAGE_V3",
        "source_id": source_id,
        "sequence_id": str(row.get("sequence_id", "") or "").strip(),
        "source_generation": max(
            0,
            int(_float_or(row.get("source_generation"), 0.0) or 0),
        ),
        "source_type": str(row.get("source_type", "") or "").strip(),
        "coordinate_space": str(row.get("coordinate_space", "") or "").strip(),
        "model_frame_id": max(0, int(model_frame_id or 0)),
        "study_surface_signature": str(study_surface_signature or "").strip(),
        "published_epoch": max(0.0, float(published_epoch or 0.0)),
    }


def _external_duplicate_evidence_guard_armed_v3(
    *,
    capture_started_with_tracking_enabled: bool,
    using_external_frame: bool,
    using_local_cpu_stream_frame: bool,
    previous_model_frame: int,
    previous_lineage: Mapping[str, Any] | None,
    incoming_lineage: Mapping[str, Any] | None,
) -> bool:
    if capture_started_with_tracking_enabled:
        return True
    if (
        not using_external_frame
        or using_local_cpu_stream_frame
        or int(previous_model_frame or 0) <= 0
    ):
        return False
    previous = _mapping_to_dict(previous_lineage or {})
    incoming = _mapping_to_dict(incoming_lineage or {})
    incoming_source_id = str(incoming.get("source_id", "") or "").strip()
    previous_source_id = str(previous.get("source_id", "") or "").strip()
    if not incoming_source_id or not previous_source_id:
        # No prior lineage means this is the first model frame for the source.
        return False
    return bool(
        incoming_source_id == previous_source_id
        and str(incoming.get("sequence_id", "") or "").strip()
        == str(previous.get("sequence_id", "") or "").strip()
        and int(_float_or(incoming.get("source_generation"), 0.0) or 0)
        == int(_float_or(previous.get("source_generation"), 0.0) or 0)
        and str(incoming.get("source_type", "") or "").strip()
        == str(previous.get("source_type", "") or "").strip()
        and str(incoming.get("coordinate_space", "") or "").strip()
        == str(previous.get("coordinate_space", "") or "").strip()
    )


def _focus_selector_state(
    *,
    supported: bool,
    armed: bool = False,
    active: bool = False,
    status: str = "idle",
    hotkey: str = "Ctrl+V",
    message: str = "",
    last_error: str = "",
    target_hwnd: int = 0,
    target_title: str = "",
    updated_at: str | None = None,
) -> dict[str, Any]:
    return {
        "supported": bool(supported),
        "armed": bool(armed),
        "active": bool(active),
        "status": str(status or "idle"),
        "hotkey": str(hotkey or "Ctrl+V"),
        "message": str(message or ""),
        "last_error": str(last_error or ""),
        "target_hwnd": int(target_hwnd or 0),
        "target_title": str(target_title or ""),
        "updated_at": str(updated_at or _now_iso()),
    }


def _public_focus_selector_state(value: Any, *, supported: bool) -> dict[str, Any]:
    row = _mapping_to_dict(value)
    return _focus_selector_state(
        supported=bool(row.get("supported", supported)),
        armed=bool(row.get("armed", False)),
        active=bool(row.get("active", False)),
        status=str(row.get("status", "idle") or "idle"),
        hotkey=str(row.get("hotkey", "Ctrl+V") or "Ctrl+V"),
        message=str(row.get("message", "") or ""),
        last_error=str(row.get("last_error", "") or ""),
        target_hwnd=int(row.get("target_hwnd", 0) or 0),
        target_title=str(row.get("target_title", "") or ""),
        updated_at=str(row.get("updated_at", "") or _now_iso()),
    )


def _focus_required_message() -> str:
    return (
        "Arm broker focus, switch to Pocket Option, press Ctrl+V, "
        "drag the chart region, and press Enter to lock it."
    )


def _crop_normalized_bbox(
    image: Image.Image,
    normalized_bbox: Sequence[Any],
) -> tuple[Image.Image, dict[str, Any]]:
    left, top, right, bottom = _normalize_focus_region_bbox(normalized_bbox, min_fraction=0.001)
    x0 = max(0, min(image.width - 1, int(round(image.width * left))))
    y0 = max(0, min(image.height - 1, int(round(image.height * top))))
    x1 = max(x0 + 1, min(image.width, int(round(image.width * right))))
    y1 = max(y0 + 1, min(image.height, int(round(image.height * bottom))))
    return image.crop((x0, y0, x1, y1)), {
        "normalized_bbox": [left, top, right, bottom],
        "pixel_bbox": [x0, y0, x1, y1],
        "width": max(0, x1 - x0),
        "height": max(0, y1 - y0),
    }


def _image_dimensions_payload(image: Image.Image) -> dict[str, int]:
    return {"width": int(image.width), "height": int(image.height)}


def _rescale_candle_tracks(
    tracks: Sequence[Mapping[str, Any]],
    *,
    scale_x: float,
    scale_y: float,
) -> list[dict[str, Any]]:
    if abs(scale_x - 1.0) <= 1e-6 and abs(scale_y - 1.0) <= 1e-6:
        return [dict(item) for item in tracks]
    result: list[dict[str, Any]] = []
    for item in tracks:
        row = dict(item)
        bbox = cast(Sequence[Any], row.get("bbox", []))
        if len(bbox) >= 4:
            row["bbox"] = [
                int(round(float(bbox[0]) * scale_x)),
                int(round(float(bbox[1]) * scale_y)),
                int(round(float(bbox[2]) * scale_x)),
                int(round(float(bbox[3]) * scale_y)),
            ]
            row["width"] = max(1, int(row["bbox"][2] - row["bbox"][0]))
            row["height"] = max(1, int(row["bbox"][3] - row["bbox"][1]))
        for key in ("center_x", "center_x_px"):
            if key in row:
                row[key] = float(row.get(key, 0.0) or 0.0) * scale_x
        for key in (
            "center_y",
            "center_y_px",
            "wick_top_px",
            "wick_bottom_px",
            "body_top_px",
            "body_bottom_px",
            "open_y_px",
            "close_y_px",
        ):
            if key in row:
                row[key] = float(row.get(key, 0.0) or 0.0) * scale_y
        result.append(row)
    return result


def _study_plane_integrity_error(study: TrackingStudy, selected_size: tuple[int, int]) -> str:
    expected = (int(selected_size[0]), int(selected_size[1]))
    chart_size = (int(study.chart_image.width), int(study.chart_image.height))
    overlay_size = (int(study.overlay_image.width), int(study.overlay_image.height))
    if chart_size != expected:
        return (
            "Tracker plane integrity failed: chart artifact dimensions "
            f"{chart_size[0]}x{chart_size[1]} do not match selected broker plane "
            f"{expected[0]}x{expected[1]}."
        )
    if overlay_size != expected:
        return (
            "Tracker plane integrity failed: overlay artifact dimensions "
            f"{overlay_size[0]}x{overlay_size[1]} do not match selected broker plane "
            f"{expected[0]}x{expected[1]}."
        )
    return ""


def _pixel_bbox_meta(image_size: tuple[int, int], bbox: Sequence[Any]) -> dict[str, Any]:
    width = max(1, int(image_size[0]))
    height = max(1, int(image_size[1]))
    x0 = max(0, min(width - 1, int(round(float(bbox[0])))))
    y0 = max(0, min(height - 1, int(round(float(bbox[1])))))
    x1 = max(x0 + 1, min(width, int(round(float(bbox[2])))))
    y1 = max(y0 + 1, min(height, int(round(float(bbox[3])))))
    return {
        "pixel_bbox": [x0, y0, x1, y1],
        "normalized_bbox": [
            float(x0 / width),
            float(y0 / height),
            float(x1 / width),
            float(y1 / height),
        ],
        "width": int(x1 - x0),
        "height": int(y1 - y0),
    }


def _binary_content_bbox(mask: ArrayND) -> tuple[int, int, int, int] | None:
    if mask.ndim != 2:
        return None
    ys, xs = np.where(mask > 0)
    if ys.size == 0 or xs.size == 0:
        return None
    return int(xs.min()), int(ys.min()), int(xs.max()) + 1, int(ys.max()) + 1


@lru_cache(maxsize=96)
def _expiry_text_template_bank() -> tuple[tuple[str, int, ArrayND], ...]:
    try:
        import cv2  # type: ignore[import-not-found]
    except Exception:
        return tuple()

    candidate_seconds = sorted(
        set(
            [3, 15, 30]
            + [minute * 60 for minute in range(1, 60)]
            + [hour * 3600 for hour in range(1, 25)]
        )
    )
    fonts = (
        cv2.FONT_HERSHEY_SIMPLEX,
        cv2.FONT_HERSHEY_DUPLEX,
        cv2.FONT_HERSHEY_COMPLEX_SMALL,
    )
    font_scales = (0.42, 0.50, 0.58, 0.66)
    thicknesses = (1, 2)
    templates: list[tuple[str, int, ArrayND]] = []
    for seconds in candidate_seconds:
        hours, remainder = divmod(int(seconds), 3600)
        minutes, second_value = divmod(remainder, 60)
        label = f"{hours:02d}:{minutes:02d}:{second_value:02d}"
        for font in fonts:
            for font_scale in font_scales:
                for thickness in thicknesses:
                    (text_width, text_height), baseline = cv2.getTextSize(label, font, font_scale, thickness)
                    canvas = np.zeros(
                        (
                            max(18, text_height + baseline + 8),
                            max(78, text_width + 12),
                        ),
                        dtype=np.uint8,
                    )
                    origin = (
                        max(4, (canvas.shape[1] - text_width) // 2),
                        max(text_height + 3, (canvas.shape[0] + text_height) // 2 - baseline // 2),
                    )
                    cv2.putText(canvas, label, origin, font, font_scale, (255, 255, 255), thickness, cv2.LINE_AA)
                    bbox = _binary_content_bbox(canvas)
                    if bbox is None:
                        continue
                    tx0, ty0, tx1, ty1 = bbox
                    cropped = canvas[max(0, ty0 - 1): min(canvas.shape[0], ty1 + 1), max(0, tx0 - 1): min(canvas.shape[1], tx1 + 1)]
                    if cropped.size:
                        templates.append((label, int(seconds), (cropped > 0).astype(np.uint8)))
    return tuple(templates)


def _read_expiry_text_by_template(mask: ArrayND) -> dict[str, Any]:
    try:
        import cv2  # type: ignore[import-not-found]
    except Exception:
        return {}
    bbox = _binary_content_bbox(mask)
    if bbox is None:
        return {}
    x0, y0, x1, y1 = bbox
    content = (mask[max(0, y0 - 1): y1 + 1, max(0, x0 - 1): x1 + 1] > 0).astype(np.uint8)
    if content.size == 0 or int(np.sum(content > 0)) < 18:
        return {}
    best_label = ""
    best_seconds = 0
    best_score = 0.0
    second_best = 0.0
    for label, seconds, template in _expiry_text_template_bank():
        if template.size == 0:
            continue
        resized = cv2.resize(
            content,
            (int(template.shape[1]), int(template.shape[0])),
            interpolation=cv2.INTER_NEAREST,
        )
        predicted = resized > 0
        expected = template > 0
        intersection = float(np.logical_and(predicted, expected).sum())
        predicted_area = float(max(1, predicted.sum()))
        expected_area = float(max(1, expected.sum()))
        union = float(max(1.0, np.logical_or(predicted, expected).sum()))
        precision = intersection / predicted_area
        recall = intersection / expected_area
        harmonic = 0.0 if (precision + recall) <= 1e-9 else (2.0 * precision * recall / (precision + recall))
        iou = intersection / union
        score = 0.62 * harmonic + 0.38 * iou
        if score > best_score:
            second_best = best_score
            best_label = label
            best_seconds = int(seconds)
            best_score = score
        elif score > second_best:
            second_best = score
    margin = best_score - second_best
    if best_label and best_score >= 0.28 and margin >= -0.015:
        return {
            "text": best_label,
            "seconds": int(best_seconds),
            "confidence": _clip01(best_score),
            "source": "time_field_template_ocr",
        }
    return {}


def _clip_bbox_to_image(image_size: tuple[int, int], bbox: Sequence[Any]) -> list[int]:
    width, height = image_size
    x0 = max(0, min(width - 1, int(round(float(bbox[0])))))
    y0 = max(0, min(height - 1, int(round(float(bbox[1])))))
    x1 = max(x0 + 1, min(width, int(round(float(bbox[2])))))
    y1 = max(y0 + 1, min(height, int(round(float(bbox[3])))))
    return [x0, y0, x1, y1]


def _clip_bbox_to_bounds(bounds: Sequence[Any], bbox: Sequence[Any]) -> list[int]:
    left, top, right, bottom = [int(round(float(value))) for value in bounds[:4]]
    if right <= left:
        right = left + 1
    if bottom <= top:
        bottom = top + 1
    x0 = max(left, min(right - 1, int(round(float(bbox[0])))))
    y0 = max(top, min(bottom - 1, int(round(float(bbox[1])))))
    x1 = max(x0 + 1, min(right, int(round(float(bbox[2])))))
    y1 = max(y0 + 1, min(bottom, int(round(float(bbox[3])))))
    return [x0, y0, x1, y1]


def _clip_point_to_bounds(bounds: Sequence[Any], point: Sequence[Any], *, pad: int = 0) -> tuple[int, int]:
    left, top, right, bottom = [int(round(float(value))) for value in bounds[:4]]
    inner_left = min(right - 1, left + max(0, int(pad)))
    inner_top = min(bottom - 1, top + max(0, int(pad)))
    inner_right = max(inner_left + 1, right - max(0, int(pad)))
    inner_bottom = max(inner_top + 1, bottom - max(0, int(pad)))
    x = max(inner_left, min(inner_right, int(round(float(point[0])))))
    y = max(inner_top, min(inner_bottom, int(round(float(point[1])))))
    return x, y


def _clip_line_segment_to_bounds(
    bounds: Sequence[Any],
    start: Sequence[Any],
    end: Sequence[Any],
    *,
    pad: int = 0,
    min_length: float = 6.0,
) -> tuple[tuple[float, float], tuple[float, float]] | None:
    left, top, right, bottom = [float(value) for value in bounds[:4]]
    pad_value = max(0.0, float(pad))
    left += pad_value
    top += pad_value
    right -= pad_value
    bottom -= pad_value
    if right <= left or bottom <= top:
        return None
    x0 = float(start[0])
    y0 = float(start[1])
    x1 = float(end[0])
    y1 = float(end[1])
    dx = x1 - x0
    dy = y1 - y0
    p = (-dx, dx, -dy, dy)
    q = (x0 - left, right - x0, y0 - top, bottom - y0)
    u0 = 0.0
    u1 = 1.0
    for p_value, q_value in zip(p, q):
        if abs(p_value) <= 1e-9:
            if q_value < 0.0:
                return None
            continue
        ratio = q_value / p_value
        if p_value < 0.0:
            if ratio > u1:
                return None
            u0 = max(u0, ratio)
        else:
            if ratio < u0:
                return None
            u1 = min(u1, ratio)
    clipped_start = (x0 + u0 * dx, y0 + u0 * dy)
    clipped_end = (x0 + u1 * dx, y0 + u1 * dy)
    clipped_dx = clipped_end[0] - clipped_start[0]
    clipped_dy = clipped_end[1] - clipped_start[1]
    if (clipped_dx * clipped_dx + clipped_dy * clipped_dy) ** 0.5 < min_length:
        return None
    return clipped_start, clipped_end


def _expand_bbox(
    image_size: tuple[int, int],
    bbox: Sequence[Any],
    *,
    pad_x: float = 0.0,
    pad_y: float = 0.0,
) -> list[int]:
    x0, y0, x1, y1 = [int(round(float(value))) for value in bbox[:4]]
    expanded = [x0 - int(round(pad_x)), y0 - int(round(pad_y)), x1 + int(round(pad_x)), y1 + int(round(pad_y))]
    return _clip_bbox_to_image(image_size, expanded)


def _translate_bbox(bbox: Sequence[Any], *, offset_x: float = 0.0, offset_y: float = 0.0) -> list[int]:
    return [
        int(round(float(bbox[0]) + offset_x)),
        int(round(float(bbox[1]) + offset_y)),
        int(round(float(bbox[2]) + offset_x)),
        int(round(float(bbox[3]) + offset_y)),
    ]


def _rgba(color: ColorRGB, alpha: int) -> ColorRGBA:
    return (int(color[0]), int(color[1]), int(color[2]), int(alpha))


@lru_cache(maxsize=32)
def _overlay_font(size: int, *, bold: bool = False) -> OverlayFont:
    requested = max(10, int(size))
    candidates = (
        (
            "C:/Windows/Fonts/segoeuib.ttf",
            "C:/Windows/Fonts/arialbd.ttf",
            "/usr/share/fonts/truetype/dejavu/DejaVuSans-Bold.ttf",
        )
        if bold
        else (
            "C:/Windows/Fonts/segoeui.ttf",
            "C:/Windows/Fonts/arial.ttf",
            "/usr/share/fonts/truetype/dejavu/DejaVuSans.ttf",
        )
    )
    for raw_path in candidates:
        path = Path(raw_path)
        if not path.exists():
            continue
        try:
            return ImageFont.truetype(str(path), requested)
        except OSError:
            continue
    return ImageFont.load_default()


def _encode_png(image: Image.Image, path: Path) -> None:
    path.parent.mkdir(parents=True, exist_ok=True)
    try:
        compress_level = int(os.getenv("PHOENIXGUARD_ARTIFACT_PNG_COMPRESS_LEVEL", "1") or "1")
    except ValueError:
        compress_level = 1
    compress_level = max(0, min(9, compress_level))
    with path.open("wb", buffering=1024 * 1024) as handle:
        image.save(handle, format="PNG", compress_level=compress_level, optimize=False)


def _live_window_jpeg_enabled(payload: Mapping[str, Any]) -> bool:
    enabled = str(os.getenv("PHOENIXGUARD_LIVE_WINDOW_JPEG", "1") or "1").strip().lower()
    if enabled in {"0", "false", "off", "no"}:
        return False
    return True


def _window_artifact_suffix(payload: Mapping[str, Any]) -> str:
    return ".jpg" if _live_window_jpeg_enabled(payload) else ".png"


def _full_overlay_jpeg_enabled(payload: Mapping[str, Any]) -> bool:
    enabled = str(os.getenv("PHOENIXGUARD_FULL_OVERLAY_JPEG", "1") or "1").strip().lower()
    return enabled not in {"0", "false", "off", "no"}


def _full_overlay_artifact_suffix(payload: Mapping[str, Any]) -> str:
    return ".jpg" if _full_overlay_jpeg_enabled(payload) else ".png"


def _chart_overlay_jpeg_enabled(payload: Mapping[str, Any]) -> bool:
    enabled = str(os.getenv("PHOENIXGUARD_CHART_OVERLAY_JPEG", "1") or "1").strip().lower()
    return enabled not in {"0", "false", "off", "no"}


def _chart_overlay_artifact_suffix(payload: Mapping[str, Any]) -> str:
    return ".jpg" if _chart_overlay_jpeg_enabled(payload) else ".png"


def _encode_window_artifact(image: Image.Image, path: Path) -> None:
    if path.suffix.lower() in {".jpg", ".jpeg"}:
        path.parent.mkdir(parents=True, exist_ok=True)
        try:
            quality = int(os.getenv("PHOENIXGUARD_LIVE_WINDOW_JPEG_QUALITY", "78") or "78")
        except ValueError:
            quality = 78
        quality = max(40, min(95, quality))
        encoder = str(os.getenv("PHOENIXGUARD_LIVE_WINDOW_JPEG_ENCODER", "cv2") or "cv2").strip().lower()
        if encoder in {"cv2", "opencv"}:
            try:
                import cv2

                rgb = np.asarray(image.convert("RGB"), dtype=np.uint8)
                bgr = cv2.cvtColor(rgb, cv2.COLOR_RGB2BGR)
                ok, buffer = cv2.imencode(
                    ".jpg",
                    bgr,
                    [int(cv2.IMWRITE_JPEG_QUALITY), int(quality)],
                )
                if ok:
                    with path.open("wb", buffering=1024 * 1024) as handle:
                        handle.write(buffer.tobytes())
                    return
            except Exception:
                LOGGER.debug("OpenCV JPEG encode failed; falling back to PIL.", exc_info=True)
        with path.open("wb", buffering=1024 * 1024) as handle:
            image.save(handle, format="JPEG", quality=quality, optimize=False, progressive=False)
        return
    _encode_png(image, path)


def _encode_jpeg_artifact(
    image: Image.Image,
    path: Path,
    *,
    quality_env: str,
    default_quality: int,
    encoder_env: str,
) -> None:
    path.parent.mkdir(parents=True, exist_ok=True)
    try:
        quality = int(os.getenv(quality_env, str(default_quality)) or str(default_quality))
    except ValueError:
        quality = int(default_quality)
    quality = max(40, min(95, quality))
    encoder = str(os.getenv(encoder_env, "cv2") or "cv2").strip().lower()
    if encoder in {"cv2", "opencv"}:
        try:
            import cv2

            rgb = np.asarray(image.convert("RGB"), dtype=np.uint8)
            bgr = cv2.cvtColor(rgb, cv2.COLOR_RGB2BGR)
            ok, buffer = cv2.imencode(
                ".jpg",
                bgr,
                [int(cv2.IMWRITE_JPEG_QUALITY), int(quality)],
            )
            if ok:
                with path.open("wb", buffering=1024 * 1024) as handle:
                    handle.write(buffer.tobytes())
                return
        except Exception:
            LOGGER.debug("OpenCV JPEG encode failed for %s; falling back to PIL.", path, exc_info=True)
    with path.open("wb", buffering=1024 * 1024) as handle:
        image.convert("RGB").save(handle, format="JPEG", quality=quality, optimize=False, progressive=False)


def _encode_chart_overlay_artifact(image: Image.Image, path: Path) -> None:
    if path.suffix.lower() not in {".jpg", ".jpeg"}:
        _encode_png(image, path)
        return
    _encode_jpeg_artifact(
        image,
        path,
        quality_env="PHOENIXGUARD_CHART_OVERLAY_JPEG_QUALITY",
        default_quality=82,
        encoder_env="PHOENIXGUARD_CHART_OVERLAY_JPEG_ENCODER",
    )


def _encode_full_overlay_artifact(image: Image.Image, path: Path) -> None:
    if path.suffix.lower() not in {".jpg", ".jpeg"}:
        _encode_png(image, path)
        return
    _encode_jpeg_artifact(
        image,
        path,
        quality_env="PHOENIXGUARD_FULL_OVERLAY_JPEG_QUALITY",
        default_quality=74,
        encoder_env="PHOENIXGUARD_FULL_OVERLAY_JPEG_ENCODER",
    )


def _compose_full_window_overlay(
    window_image: Image.Image,
    selected_overlay: Image.Image,
    focus_meta: Mapping[str, Any],
) -> Image.Image:
    base = window_image.convert("RGBA")
    overlay = selected_overlay.convert("RGBA")
    bbox = cast(Sequence[Any], focus_meta.get("pixel_bbox", []))
    if len(bbox) < 4:
        return base.convert("RGB")
    x0, y0, x1, y1 = [int(round(float(value))) for value in bbox[:4]]
    x0 = max(0, min(base.width - 1, x0))
    y0 = max(0, min(base.height - 1, y0))
    x1 = max(x0 + 1, min(base.width, x1))
    y1 = max(y0 + 1, min(base.height, y1))
    target_size = (max(1, x1 - x0), max(1, y1 - y0))
    if overlay.size != target_size:
        overlay = overlay.resize(target_size, Image.Resampling.BILINEAR)
    canvas = base.copy()
    canvas.alpha_composite(overlay, (x0, y0))
    return canvas.convert("RGB")


def _surface_signature(image: Image.Image) -> str:
    sample = image.convert("RGB")
    if sample.width > 96 or sample.height > 96:
        sample.thumbnail((96, 96), Image.Resampling.BILINEAR)
    digest = sample.tobytes()
    return uuid4().hex[:6] if not digest else f"{abs(hash(digest)) & 0xFFFFFFFF:08x}"


def _cpu_stream_frame_hash_v3(image: Image.Image) -> str:
    """Match the CPU observer's exact RGB keyframe SHA-256 contract."""

    rgb = image.convert("RGB")
    digest = hashlib.sha256()
    digest.update(f"RGB\0{rgb.width}\0{rgb.height}\0".encode("ascii"))
    digest.update(rgb.tobytes())
    return digest.hexdigest()


def _market_selector_visual_fingerprint(image: Image.Image) -> str:
    """Return a stable visual identity for the broker's selected instrument.

    The former fingerprint hashed the entire top-left 34% x 18% of the chart.
    That region includes live payout sparklines, clocks, and chart pixels, so it
    changed on every capture and falsely announced a pair switch.  Pocket
    Option keeps the selected-instrument control in a much smaller, fixed
    header lane.  Hash only its bright text/icon mask so candle motion and JPEG
    noise cannot invalidate studied history.
    """

    sample = image.convert("RGB")
    if sample.width < 64 or sample.height < 48:
        return ""
    left = max(0, min(sample.width - 2, int(round(sample.width * 0.055))))
    top = max(0, min(sample.height - 2, int(round(sample.height * 0.10))))
    right = max(left + 2, min(sample.width, int(round(sample.width * 0.21))))
    bottom = max(top + 2, min(sample.height, int(round(sample.height * 0.19))))
    crop = sample.crop((left, top, right, bottom)).convert("L")
    crop = crop.resize((128, 40), Image.Resampling.BILINEAR)
    # The broker header is dark and its selector glyphs are bright.  A binary
    # mask removes low-amplitude animation/compression changes while retaining
    # the actual pair text.  Require some foreground evidence so an empty dark
    # crop never becomes a misleading shared identity.
    # `L` mode serializes one unsigned byte per pixel.  Reading bytes avoids
    # Pillow's intentionally broad static pixel union (which also permits
    # tuple-valued RGB data) while preserving the exact binary mask.
    pixels = [value >= 145 for value in crop.tobytes()]
    if sum(pixels) < 12:
        return ""
    packed = bytearray((len(pixels) + 7) // 8)
    for index, enabled in enumerate(pixels):
        if enabled:
            packed[index // 8] |= 1 << (index % 8)
    return f"selector_v2_{hashlib.sha256(bytes(packed)).hexdigest()[:20]}"


def _artifact_frame_id_from_path(path: Path | str | None, default: int = 0) -> int:
    if not path:
        return int(default)
    match = re.match(r"^(\d{1,12})_", Path(path).name)
    if not match:
        return int(default)
    try:
        return int(match.group(1))
    except ValueError:
        return int(default)


def _stable_short_hash(payload: Mapping[str, Any]) -> str:
    encoded = json.dumps(dict(payload), sort_keys=True, separators=(",", ":"), default=str).encode("utf-8")
    return hashlib.sha256(encoded).hexdigest()[:16]


def _locked_stream_source_token_v3(payload: Mapping[str, Any]) -> str:
    """Return a bounded identity for one locked broker-window source."""

    locked = _mapping_to_dict(payload.get("locked_window", {}))
    try:
        hwnd = int(locked.get("hwnd", 0) or 0)
        process_id = int(
            locked.get("process_id", locked.get("pid", 0)) or 0
        )
    except (TypeError, ValueError, OverflowError):
        return ""
    session_id = str(payload.get("session_id") or "").strip()
    if hwnd <= 0 or not session_id:
        return ""
    return _stable_short_hash(
        {
            "session_id": session_id,
            "hwnd": hwnd,
            "process_id": process_id,
            "title": str(locked.get("title") or "").strip(),
            "continuity_generation": int(
                _float_or(
                    payload.get("stream_continuity_generation_v3"), 0.0
                )
                or 0
            ),
        }
    )


def _instrument_viewport_hash(payload: Mapping[str, Any]) -> str:
    focus = _public_manual_focus_region(payload.get("manual_focus_region", {}))
    locked = _mapping_to_dict(payload.get("locked_window", {}))
    descriptor: dict[str, Any] = {
        "manual_focus_enabled": bool(focus.get("enabled", False)),
        "manual_focus_bbox": list(cast(Sequence[Any], focus.get("normalized_bbox", []))),
        "locked_hwnd": int(locked.get("hwnd", 0) or 0),
        "locked_title": str(payload.get("locked_title", locked.get("title", "")) or ""),
        "locked_width": int(locked.get("width", 0) or 0),
        "locked_height": int(locked.get("height", 0) or 0),
    }
    return _stable_short_hash(descriptor)


def _trend_direction(value: float, *, epsilon: float = 0.012) -> str:
    if value > epsilon:
        return "BUY"
    if value < -epsilon:
        return "SELL"
    return "HOLD"


def _regression_slope(values: Sequence[float]) -> float:
    if len(values) < 2:
        return 0.0
    xs = np.linspace(0.0, 1.0, num=len(values), dtype=np.float32)
    ys = np.asarray(values, dtype=np.float32)
    if float(np.std(ys)) <= 1e-9:
        return 0.0
    slope, _intercept = np.polyfit(xs, ys, 1)
    return float(slope)


def _market_study_namespace_v3(value: Any) -> tuple[str, str]:
    study = _mapping_to_dict(value)
    return (
        str(study.get("symbol") or "").strip().upper(),
        str(study.get("timeframe") or "").strip().upper(),
    )


def _history_entry_matches_study_namespace_v3(
    value: Any,
    namespace: tuple[str, str],
) -> bool:
    symbol, timeframe = namespace
    if not symbol or not timeframe:
        return False
    row = _mapping_to_dict(value)
    row_study = _mapping_to_dict(row.get("market_study_v3"))
    return bool(
        str(row_study.get("status") or "").strip().upper() == "STUDIED"
        and str(row_study.get("closed_candle_key") or "").strip()
        and _market_study_namespace_v3(row_study) == namespace
    )


def _study_entry(
    signal: Mapping[str, Any],
    tracking: Mapping[str, Any],
    *,
    captured_at: str = "",
    published_at: str = "",
    frame_id: int = 0,
    source_capture_id: str = "",
) -> dict[str, Any]:
    decision_kernel = _mapping_to_dict(signal.get("decision_kernel", {}))
    high_frequency = _mapping_to_dict(signal.get("high_frequency_forecast", tracking.get("high_frequency_forecast", {})))
    two_candle_study = _mapping_to_dict(signal.get("two_candle_study", tracking.get("two_candle_study", {})))
    lstm_contribution = _mapping_to_dict(signal.get("lstm_contribution", tracking.get("lstm_contribution", {})))
    countertrend_lane = _mapping_to_dict(signal.get("countertrend_lane", {}))
    broker_execution = _mapping_to_dict(signal.get("broker_execution_state", tracking.get("broker_execution_state", {})))
    smart_money = _mapping_to_dict(tracking.get("smart_money_context", signal.get("smart_money_context", {})))
    support_resistance = _mapping_to_dict(
        tracking.get("support_resistance_context", signal.get("support_resistance_context", {}))
    )
    execution_timing = _mapping_to_dict(tracking.get("execution_timing", signal.get("execution_timing", {})))
    market_study_v3 = _mapping_to_dict(
        signal.get("market_study_v3") or tracking.get("market_study_v3")
    )
    observed_at = str(
        captured_at
        or signal.get("capture_started_at")
        or signal.get("observed_at")
        or _now_iso()
    )
    created_at = str(
        published_at
        or signal.get("published_at")
        or signal.get("timestamp")
        or observed_at
    )
    observed_epoch = _float_or(
        signal.get("capture_started_epoch", signal.get("observed_epoch", 0.0)),
        0.0,
    )
    published_epoch = _float_or(
        signal.get("published_epoch", signal.get("created_epoch", 0.0)),
        0.0,
    )
    return {
        "timestamp": created_at,
        "created_at": created_at,
        "captured_at": observed_at,
        "observed_at": observed_at,
        "observed_epoch": observed_epoch,
        "published_epoch": published_epoch,
        "frame_id": max(0, int(frame_id or 0)),
        "source_capture_id": str(source_capture_id or ""),
        "action": str(signal.get("action", "HOLD") or "HOLD"),
        "execution_action": str(signal.get("execution_action", "HOLD") or "HOLD"),
        "entry_state": str(signal.get("entry_state", "WAIT") or "WAIT"),
        "setup": str(signal.get("setup", "") or ""),
        "confidence": _clip01(signal.get("effective_confidence", 0.0)),
        "summary": str(signal.get("summary", "") or ""),
        "timeframe": str(
            market_study_v3.get("timeframe")
            or signal.get("focus_timeframe", "")
            or ""
        ),
        "market": str(
            market_study_v3.get("symbol") or signal.get("market", "") or ""
        ),
        "market_study_v3": market_study_v3,
        "global_direction": str(tracking.get("global_direction", "HOLD") or "HOLD"),
        "local_direction": str(tracking.get("local_direction", "HOLD") or "HOLD"),
        "dominant_side": str(decision_kernel.get("dominant_side", "hold") or "hold").upper(),
        "major_trend_side": str(decision_kernel.get("major_trend_side", "hold") or "hold").upper(),
        "major_trend_confidence": _clip01(decision_kernel.get("major_trend_confidence", 0.0)),
        "kernel_state": str(decision_kernel.get("state", "") or ""),
        "kernel_decision": str(decision_kernel.get("decision", "") or ""),
        "setup_age_candles": int(decision_kernel.get("setup_age_candles", 0) or 0),
        "candles_to_trigger": int(decision_kernel.get("eta_trigger_candles", 0) or 0),
        "candles_to_target": int(decision_kernel.get("eta_target_after_trigger_candles", 0) or 0),
        "target_horizon_candles": int(decision_kernel.get("target_horizon_candles", 0) or 0),
        "target_horizon_source": str(decision_kernel.get("target_horizon_source", "") or ""),
        "candles_to_invalidation": int(decision_kernel.get("eta_invalidation_candles", 0) or 0),
        "candles_to_stale": int(decision_kernel.get("stale_after_candles", 0) or 0),
        "triggered": str(decision_kernel.get("state", "") or "").upper() in {"TRIGGERED", "ACTIVE", "COMPLETE"},
        "target_before_invalidation": str(decision_kernel.get("next_most_likely_event", "") or "") == "target",
        "next_candle_bias": str(decision_kernel.get("next_candle_bias", "hold") or "hold").upper(),
        "high_frequency_summary": str(high_frequency.get("summary", "") or ""),
        "high_frequency_pressure": _upper_action(high_frequency.get("primary_pressure", "HOLD")),
        "high_frequency_confidence": _clip01(high_frequency.get("confidence", 0.0)),
        "two_candle_study_summary": str(two_candle_study.get("summary", high_frequency.get("summary", "")) or ""),
        "two_candle_study_display": str(two_candle_study.get("display_as", "") or ""),
        "lstm_contribution_fresh": bool(lstm_contribution.get("fresh", False)),
        "lstm_contribution_side": _upper_action(lstm_contribution.get("side", "HOLD")),
        "trade_mode": str(decision_kernel.get("trade_mode", "") or ""),
        "candle_execution_side": str(decision_kernel.get("candle_execution_side", "hold") or "hold").upper(),
        "hold_for_candles": int(decision_kernel.get("hold_for_candles", 0) or 0),
        "countertrend_state": str(countertrend_lane.get("state", "INACTIVE") or "INACTIVE"),
        "countertrend_side": str(countertrend_lane.get("side", "HOLD") or "HOLD").upper(),
        "countertrend_actionable": bool(countertrend_lane.get("actionable", False)),
        "smart_money_side": _upper_action(smart_money.get("dominant_side", "HOLD")),
        "smart_money_score": _clip01(smart_money.get("confidence", 0.0)),
        "smart_money_summary": str(smart_money.get("summary", "") or ""),
        "support_resistance_significant": int(support_resistance.get("significant_count", 0) or 0),
        "support_resistance_summary": str(support_resistance.get("summary", "") or ""),
        "execution_timing_class": str(execution_timing.get("timing_class", "") or ""),
        "execution_timing_expiry_seconds": int(execution_timing.get("recommended_expiry_seconds", execution_timing.get("expiry_seconds", 0)) or 0),
        "execution_opposing_force_risk": _clip01(execution_timing.get("opposing_force_risk", 0.0)),
        "execution_global_extreme_risk": _clip01(execution_timing.get("global_extreme_risk", 0.0)),
        "broker_execution_status": str(broker_execution.get("status", "") or ""),
        "broker_execution_message": str(broker_execution.get("message", "") or ""),
        "phoenixguard_decision_state": str(
            signal.get(
                "phoenixguard_decision_state",
                _mapping_to_dict(tracking.get("phoenixguard_report", {})).get("decision_state", "forming"),
            )
            or "forming"
        ),
        "phoenixguard_report_summary": str(signal.get("phoenixguard_report_summary", "") or ""),
    }


def _tracker_signal_state_hash(
    latest_signal: Mapping[str, Any],
    tracking_summary: Mapping[str, Any],
    decision_kernel: Mapping[str, Any] | None = None,
) -> str:
    kernel = _mapping_to_dict(
        decision_kernel
        if decision_kernel is not None
        else latest_signal.get("decision_kernel", tracking_summary.get("decision_kernel", {}))
    )
    global_local_control = _mapping_to_dict(
        latest_signal.get("global_local_control", tracking_summary.get("global_local_control", {}))
    )
    countertrend_lane = _mapping_to_dict(
        latest_signal.get("countertrend_lane", tracking_summary.get("countertrend_lane", {}))
    )
    smart_money = _mapping_to_dict(
        latest_signal.get("smart_money_context", tracking_summary.get("smart_money_context", {}))
    )
    support_resistance = _mapping_to_dict(
        latest_signal.get("support_resistance_context", tracking_summary.get("support_resistance_context", {}))
    )
    high_frequency = _mapping_to_dict(
        latest_signal.get("high_frequency_forecast", tracking_summary.get("high_frequency_forecast", {}))
    )
    high_frequency_candles = _sequence_of_mappings(high_frequency.get("candle_forecasts", []))
    two_candle_study = _mapping_to_dict(
        latest_signal.get("two_candle_study", tracking_summary.get("two_candle_study", high_frequency.get("two_candle_study", {})))
    )
    lstm_contribution = _mapping_to_dict(
        latest_signal.get("lstm_contribution", tracking_summary.get("lstm_contribution", high_frequency.get("lstm_contribution", {})))
    )
    execution_side = _upper_action(latest_signal.get("execution_action", latest_signal.get("action", "HOLD")))
    payload: dict[str, Any] = {
        "action": _upper_action(latest_signal.get("action", "HOLD")),
        "candidate_action": _upper_action(latest_signal.get("candidate_action", latest_signal.get("action", "HOLD"))),
        "execution_action": execution_side,
        "actionable": bool(latest_signal.get("actionable", False)) and execution_side in {"BUY", "SELL"},
        "entry_state": str(
            latest_signal.get("entry_state", tracking_summary.get("entry_state", "WAIT"))
            or "WAIT"
        ).upper(),
        "entry_label": str(
            latest_signal.get("entry_label", tracking_summary.get("entry_label", "WAIT"))
            or "WAIT"
        ).upper(),
        "kernel_state": str(kernel.get("state", "") or "").upper(),
        "kernel_decision": str(kernel.get("decision", "") or "").upper(),
        "kernel_trade_mode": str(kernel.get("trade_mode", "") or "").upper(),
        "dominant_side": _upper_action(kernel.get("dominant_side", latest_signal.get("dominant_side", "HOLD"))),
        "major_trend_side": _upper_action(kernel.get("major_trend_side", latest_signal.get("major_trend_direction", "HOLD"))),
        "target_horizon_candles": int(kernel.get("target_horizon_candles", 0) or 0),
        "next_candle_bias": _upper_action(kernel.get("next_candle_bias", "HOLD")),
        "candle_execution_side": _upper_action(kernel.get("candle_execution_side", "HOLD")),
        "countertrend_actionable": bool(countertrend_lane.get("actionable", False)),
        "countertrend_side": _upper_action(countertrend_lane.get("side", "HOLD")),
        "global_direction": _upper_action(tracking_summary.get("global_direction", "HOLD")),
        "local_direction": _upper_action(tracking_summary.get("local_direction", "HOLD")),
        "impulse_direction": _upper_action(tracking_summary.get("impulse_direction", "HOLD")),
        "smart_money_side": _upper_action(smart_money.get("dominant_side", "HOLD")),
        "smart_money_score": round(_clip01(smart_money.get("confidence", 0.0)), 3),
        "significant_sr": int(support_resistance.get("significant_count", 0) or 0),
        "control_direction": _upper_action(global_local_control.get("direction", "HOLD")),
        "control_owner": str(global_local_control.get("owner", "") or "").lower(),
        "hf_status": str(high_frequency.get("status", "") or "").upper(),
        "hf_pressure": _upper_action(high_frequency.get("primary_pressure", "HOLD")),
        "hf_pattern": str(high_frequency.get("pattern", "") or ""),
        "hf_confidence": round(_clip01(high_frequency.get("confidence", 0.0)), 3),
        "hf_candles": tuple(str(row.get("direction", "") or "").upper() for row in high_frequency_candles[:2]),
        "two_candle_display": str(two_candle_study.get("display_as", "") or ""),
        "two_candle_summary": str(two_candle_study.get("summary", high_frequency.get("summary", "")) or ""),
        "lstm_fresh": bool(lstm_contribution.get("fresh", False)),
        "lstm_side": _upper_action(lstm_contribution.get("side", "HOLD")),
    }
    encoded = json.dumps(payload, sort_keys=True, separators=(",", ":"), default=str).encode("utf-8")
    return hashlib.sha256(encoded).hexdigest()


def _ensure_tracker_signal_id(
    latest_signal: dict[str, Any],
    tracking_summary: Mapping[str, Any],
    *,
    session_id: str,
    frame_index: int,
) -> None:
    if str(latest_signal.get("signal_id", "") or "").strip():
        return
    session_key = re.sub(r"[^A-Za-z0-9]+", "_", str(session_id or "session")).strip("_") or "session"
    state_hash = _tracker_signal_state_hash(latest_signal, tracking_summary)[:14]
    latest_signal["signal_id"] = f"tracker_{session_key}_{int(frame_index)}_{state_hash}"


def _hypothesis_side(value: Any) -> str:
    if isinstance(value, Mapping):
        for key in ("side", "action", "execution_action", "direction", "bias"):
            side = _upper_action(cast(Mapping[str, Any], value).get(key), fallback="")
            if side in {"BUY", "SELL"}:
                return side
        return "HOLD"
    return _upper_action(value, fallback="HOLD")


def _published_signal_block(
    latest_signal: dict[str, Any],
    *,
    reason: str,
) -> None:
    latest_signal["actionable"] = False
    latest_signal["execution_action"] = "HOLD"
    latest_signal["side"] = "HOLD"
    latest_signal["execution_permission"] = "WAIT"
    latest_signal["status"] = "no_trade"
    latest_signal["no_trade_reason"] = reason
    latest_signal["execution_block_reason"] = reason
    latest_signal.setdefault("entry_reason", "")


def _harden_published_signal_contract(
    latest_signal: dict[str, Any],
    tracking_summary: Mapping[str, Any],
    public: Mapping[str, Any],
    *,
    session_id: str,
) -> None:
    decision_kernel = _mapping_to_dict(
        latest_signal.get("decision_kernel", tracking_summary.get("decision_kernel", {}))
    )
    market = _normalize_fx_market_candidate(
        latest_signal.get("symbol", latest_signal.get("market", tracking_summary.get("detected_market", public.get("market", ""))))
    )
    timeframe = str(
        latest_signal.get("timeframe", latest_signal.get("focus_timeframe", tracking_summary.get("detected_timeframe", "")))
        or ""
    ).upper()
    created_epoch = _float_or(
        latest_signal.get("signal_created_epoch", latest_signal.get("published_epoch", public.get("last_capture_epoch", 0.0))),
        0.0,
    )
    valid_until_epoch = _float_or(
        latest_signal.get(
            "signal_valid_until_epoch",
            latest_signal.get("valid_until_epoch", public.get("decision_valid_until_epoch", 0.0)),
        ),
        0.0,
    )
    latency_seconds = _float_or(
        latest_signal.get("latency_seconds", latest_signal.get("pipeline_latency_sec", public.get("pipeline_latency_sec", 0.0))),
        0.0,
    )
    execution_side = _upper_action(latest_signal.get("execution_action", latest_signal.get("action", "HOLD")))
    latest_signal["session_id"] = session_id
    if market:
        latest_signal.setdefault("symbol", market)
        latest_signal.setdefault("market", market)
    if timeframe:
        latest_signal.setdefault("timeframe", timeframe)
        latest_signal.setdefault("focus_timeframe", timeframe)
    latest_signal["side"] = execution_side if execution_side in {"BUY", "SELL"} else "HOLD"
    latest_signal.setdefault("setup_type", latest_signal.get("setup", ""))
    latest_signal.setdefault("entry_state", tracking_summary.get("entry_state", "WAIT"))
    latest_signal["expiry_seconds"] = int(latest_signal.get("expiry_seconds", latest_signal.get("required_seconds", 0)) or 0)
    latest_signal.setdefault("expiry_source", "not_actionable" if execution_side not in {"BUY", "SELL"} else "")
    if created_epoch > 0.0:
        latest_signal["signal_created_epoch"] = created_epoch
    if valid_until_epoch > 0.0:
        latest_signal["signal_valid_until_epoch"] = valid_until_epoch
    latest_signal.setdefault("tracker_frame_id", int(public.get("frame_index", 0) or 0))
    latest_signal["capture_count"] = int(public.get("capture_count", latest_signal.get("capture_count", 0)) or 0)
    latest_signal["latency_seconds"] = latency_seconds
    latest_signal["decision_kernel"] = decision_kernel
    latest_signal.setdefault(
        "market_context",
        {
            "symbol": market,
            "timeframe": timeframe,
            "market_confidence": _clip01(latest_signal.get("market_confidence", tracking_summary.get("market_confidence", 0.0))),
            "timeframe_confidence": _clip01(tracking_summary.get("timeframe_confidence", 0.0)),
        },
    )
    for key in ("buy_hypothesis", "sell_hypothesis", "active_hypothesis", "invalidation_condition"):
        if key not in latest_signal and key in tracking_summary:
            latest_signal[key] = tracking_summary[key]
    timing_signal = _mapping_to_dict(latest_signal.get("timing_signal", {}))
    if execution_side in {"BUY", "SELL"}:
        latest_signal.setdefault(
            "entry_reason",
            str(
                latest_signal.get("entry_reason")
                or timing_signal.get("instruction")
                or latest_signal.get("execution_trigger_reason")
                or latest_signal.get("summary")
                or ""
            ),
        )
    latest_signal.setdefault("no_trade_reason", "" if execution_side in {"BUY", "SELL"} else str(latest_signal.get("summary", "") or "No executable trade is active."))

    executable_signal = bool(latest_signal.get("actionable", False)) and execution_side in {"BUY", "SELL"}
    if not executable_signal:
        return

    buy_hypothesis = latest_signal.get("buy_hypothesis")
    sell_hypothesis = latest_signal.get("sell_hypothesis")
    active_hypothesis = latest_signal.get("active_hypothesis")
    active_side = _hypothesis_side(active_hypothesis)
    if isinstance(buy_hypothesis, Mapping) and isinstance(sell_hypothesis, Mapping) and active_side not in {"BUY", "SELL"}:
        _published_signal_block(latest_signal, reason="Dual BUY/SELL hypotheses are unresolved; no trade is published.")
        return
    if active_side in {"BUY", "SELL"} and active_side != execution_side:
        _published_signal_block(
            latest_signal,
            reason=f"Active hypothesis is {active_side} but executable side was {execution_side}; no trade is published.",
        )
        return

    map_timing = _mapping_to_dict(latest_signal.get("map_timing", tracking_summary.get("map_timing", {})))
    decision_state = str(latest_signal.get("phoenixguard_decision_state", "") or "").strip().lower()
    entry_state = str(latest_signal.get("entry_state", "") or "").strip().upper()
    current_candle_late = bool(
        latest_signal.get("current_candle_late", False)
        or map_timing.get("current_candle_late", False)
        or decision_state in {"late", "target_complete", "invalidated", "exhausted"}
        or entry_state in {"LATE", "COMPLETE", "TARGET_COMPLETE", "INVALIDATED"}
    )
    if current_candle_late:
        _published_signal_block(latest_signal, reason="Current candle is late for execution; no trade is published.")
        return

    expiry_source = str(latest_signal.get("expiry_source", "") or "").strip().lower()
    if "fallback" in expiry_source or expiry_source in {"default", "derived_default"}:
        _published_signal_block(latest_signal, reason="Expiry is fallback-derived; no trade is published.")


def _bind_live_decision_truth_to_execution_packets(payload: dict[str, Any]) -> None:
    council = _mapping_to_dict(payload.get("model_council"))
    market_reality = _mapping_to_dict(
        payload.get("market_reality") or council.get("market_reality")
    )
    trade_permission = _mapping_to_dict(
        payload.get("trade_permission")
        or market_reality.get("trade_permission")
        or market_reality.get("permission")
        or council.get("trade_permission")
    )
    entry_quality = _mapping_to_dict(
        payload.get("entry_quality")
        or market_reality.get("entry_quality")
        or council.get("entry_quality")
    )
    market_trap = _mapping_to_dict(
        payload.get("market_trap")
        or payload.get("trap_assessment")
        or market_reality.get("market_trap")
        or council.get("market_trap")
        or council.get("trap_assessment")
    )

    def bind(container: dict[str, Any], depth: int = 0) -> None:
        if depth > 3:
            return
        if container.get("schema_version") == PG_EXECUTION_PACKET_SCHEMA_VERSION:
            if trade_permission:
                container["trade_permission"] = dict(trade_permission)
            if entry_quality:
                container["entry_quality"] = dict(entry_quality)
            if market_trap:
                container["market_trap"] = dict(market_trap)
        for packet_key in (
            "model_council_packet",
            "execution_packet",
            "latest_model_council_packet",
            "latest_execution_packet",
        ):
            raw_packet = container.get(packet_key)
            if not isinstance(raw_packet, Mapping):
                continue
            packet = _mapping_to_dict(raw_packet)
            if trade_permission:
                packet["trade_permission"] = dict(trade_permission)
            if entry_quality:
                packet["entry_quality"] = dict(entry_quality)
            if market_trap:
                packet["market_trap"] = dict(market_trap)
            container[packet_key] = packet
        for nested_key in ("model_council_result", "model_council_state"):
            raw_nested = container.get(nested_key)
            if not isinstance(raw_nested, Mapping):
                continue
            nested = _mapping_to_dict(raw_nested)
            bind(nested, depth + 1)
            container[nested_key] = nested

    bind(payload)


def _execution_packet_alias_from_payload(payload: Mapping[str, Any]) -> dict[str, Any]:
    """Return the most direct previously published packet, without re-authorizing it."""

    pending: list[Mapping[str, Any]] = [payload]
    seen: set[int] = set()
    while pending:
        container = pending.pop(0)
        identity = id(container)
        if identity in seen:
            continue
        seen.add(identity)
        for packet_key in _EXECUTION_PACKET_ALIAS_KEYS:
            packet = container.get(packet_key)
            if isinstance(packet, Mapping):
                packet_mapping = cast(Mapping[str, Any], packet)
                if str(packet_mapping.get("packet_id", "") or "").strip():
                    return _mapping_to_dict(packet_mapping)
        for nested_key in ("model_council_result", "latest_signal", "tracking_summary"):
            nested = container.get(nested_key)
            if isinstance(nested, Mapping):
                pending.append(cast(Mapping[str, Any], nested))
    return {}


def _execution_packet_lineage(packet: Mapping[str, Any]) -> tuple[int, int]:
    provenance = _mapping_to_dict(packet.get("provenance"))
    frame_id = int(_float_or(packet.get("frame_id") or provenance.get("frame_id"), 0.0) or 0)
    capture_count = int(
        _float_or(packet.get("capture_count") or provenance.get("capture_count"), float(frame_id))
        or frame_id
    )
    return frame_id, capture_count


def _council_frame_is_newer_than_packet(
    packet: Mapping[str, Any],
    *,
    frame_id: int,
    capture_count: int,
) -> bool:
    packet_frame_id, packet_capture_count = _execution_packet_lineage(packet)
    if packet_frame_id <= 0 and packet_capture_count <= 0:
        return bool(frame_id > 0 or capture_count > 0)
    return bool(
        (capture_count > 0 and capture_count > packet_capture_count)
        or (frame_id > 0 and frame_id > packet_frame_id)
    )


def _execution_packet_revocation_reason(
    result_payload: Mapping[str, Any],
    previous_packet: Mapping[str, Any],
) -> str:
    execution = _mapping_to_dict(result_payload.get("execution"))
    council = _mapping_to_dict(result_payload.get("model_council"))
    current_side = _upper_action(
        execution.get("side")
        or council.get("final_side")
        or result_payload.get("final_side")
        or result_payload.get("side"),
        fallback="HOLD",
    )
    previous_side = _upper_action(resolve_v3_packet_side(previous_packet), fallback="HOLD")
    if current_side in {"BUY", "SELL"} and previous_side in {"BUY", "SELL"} and current_side != previous_side:
        return "NEWER_COUNCIL_OPPOSITE_SIDE"
    state = _upper_action(
        execution.get("state")
        or council.get("final_state")
        or result_payload.get("final_state")
        or result_payload.get("state"),
        fallback="HOLD",
    )
    if state in {"PREPARING", "WATCHING", "HOLD"}:
        return f"NEWER_COUNCIL_{state}"
    return "NEWER_COUNCIL_NO_EXECUTABLE_PACKET"


def _clear_execution_packet_aliases(
    container: dict[str, Any],
    *,
    tombstone: Mapping[str, Any] | None = None,
) -> None:
    for packet_key in _EXECUTION_PACKET_ALIAS_KEYS:
        container.pop(packet_key, None)
    container["execution_packet_present"] = False
    container.pop("execution_packet_retained_v3", None)
    if tombstone:
        container[_EXECUTION_PACKET_REVOCATION_KEY] = dict(tombstone)


def _bind_live_overlay_truth_to_execution_packets(
    payload: dict[str, Any],
    overlay_truth_audit: Mapping[str, Any] | None,
    *,
    frame_id: int,
    capture_count: int,
    input_frame_hash: str,
) -> None:
    if not isinstance(overlay_truth_audit, Mapping) or not overlay_truth_audit:
        return
    normalized = _mapping_to_dict(overlay_truth_audit)
    normalized["frame_id"] = int(frame_id)
    normalized["capture_count"] = int(capture_count)
    normalized["input_frame_hash"] = str(input_frame_hash or "")
    normalized = cast(dict[str, Any], _strip_packet_self_references(normalized))

    def bind(container: dict[str, Any], depth: int = 0) -> None:
        if depth > 3:
            return
        if container.get("schema_version") == PG_EXECUTION_PACKET_SCHEMA_VERSION:
            container["overlay_truth_audit"] = dict(normalized)
        for packet_key in (
            "model_council_packet",
            "execution_packet",
            "latest_model_council_packet",
            "latest_execution_packet",
        ):
            raw_packet = container.get(packet_key)
            if not isinstance(raw_packet, Mapping):
                continue
            packet = _mapping_to_dict(raw_packet)
            packet["overlay_truth_audit"] = dict(normalized)
            container[packet_key] = packet
        for nested_key in ("model_council_result", "model_council_state"):
            raw_nested = container.get(nested_key)
            if not isinstance(raw_nested, Mapping):
                continue
            nested = _mapping_to_dict(raw_nested)
            bind(nested, depth + 1)
            container[nested_key] = nested

    bind(payload)


def _model_council_packet_from_payload(
    payload: Mapping[str, Any],
    *,
    require_live_overlay_truth: bool = False,
) -> dict[str, Any]:
    """Find a V3 executable packet without accepting legacy raw signals."""

    now_epoch = _now_epoch()
    packet_keys = (
        "model_council_packet",
        "execution_packet",
        "latest_model_council_packet",
        "latest_execution_packet",
    )

    def declares_no_current_packet(candidate: Mapping[str, Any]) -> bool:
        if any(isinstance(candidate.get(key), Mapping) for key in packet_keys):
            return False
        result = _mapping_to_dict(candidate.get("model_council_result"))
        if any(isinstance(result.get(key), Mapping) for key in packet_keys):
            return False
        if result.get("execution_packet_present") is False:
            return True
        return candidate.get("execution_packet_present") is False

    def packet_valid_until(packet: Mapping[str, Any]) -> float:
        direct = _float_or(packet.get("valid_until_epoch_sec") or packet.get("valid_until_epoch"), 0.0)
        if direct > 0.0:
            return direct
        created = _float_or(packet.get("created_epoch_sec") or packet.get("created_epoch"), 0.0)
        ttl = _float_or(packet.get("ttl_sec") or packet.get("time_to_live_sec") or packet.get("freshness_window_sec"), 0.0)
        return created + max(0.1, ttl) if created > 0.0 and ttl > 0.0 else 0.0

    def packet_is_current(packet: Mapping[str, Any]) -> bool:
        valid_until = packet_valid_until(packet)
        return valid_until > now_epoch

    def packet_is_executable(packet: Mapping[str, Any]) -> bool:
        if packet.get("schema_version") != PG_EXECUTION_PACKET_SCHEMA_VERSION:
            return False
        if str(packet.get("packet_type") or "").strip() != PG_EXECUTION_PACKET_SCHEMA_VERSION:
            return False
        if not packet_is_current(packet):
            return False
        try:
            validation = validate_execution_packet_v3(
                packet,
                now_epoch=now_epoch,
                require_executable=True,
                require_overlay_truth=require_live_overlay_truth,
                require_live_handoff_truth=require_live_overlay_truth,
            )
        except Exception:
            LOGGER.debug("Rejected malformed Model Council execution packet.", exc_info=True)
            return False
        if not validation.ok:
            return False
        return validation.side in {"BUY", "SELL"} and validation.expiry_seconds is not None

    def walk(candidate: Any, depth: int = 0) -> dict[str, Any]:
        if depth > 4 or not isinstance(candidate, Mapping):
            return {}
        row = _mapping_to_dict(candidate)
        if depth == 0 and declares_no_current_packet(row):
            return {}
        if row.get("schema_version") == PG_EXECUTION_PACKET_SCHEMA_VERSION:
            packet = _compact_persisted_execution_packet(row)
            return packet if packet_is_executable(packet) else {}
        for key in (*packet_keys, "model_council_result", "model_council_state", "model_council", "latest_signal", "tracking_summary"):
            nested = row.get(key)
            found = walk(nested, depth + 1)
            if found:
                return found
        return {}

    return walk(payload)


def model_council_packet_from_payload(payload: Mapping[str, Any]) -> dict[str, Any]:
    return _model_council_packet_from_payload(payload, require_live_overlay_truth=True)


def _model_council_study_packet_from_payload(payload: Mapping[str, Any]) -> dict[str, Any]:
    """Find or synthesize the latest non-executable Model Council visibility packet."""

    now_epoch = time.time()
    latest_signal = _mapping_to_dict(payload.get("latest_signal", {}))
    tracking_summary = _mapping_to_dict(payload.get("tracking_summary", {}))
    execution_controls = _mapping_to_dict(payload.get("execution_controls", {}))
    pipeline_timing = _mapping_to_dict(latest_signal.get("pipeline_timing") or tracking_summary.get("pipeline_timing"))
    study_ttl_sec = max(
        _TRACKER_SIGNAL_MIN_FRESHNESS_WINDOW_SEC,
        _float_or(execution_controls.get("study_packet_valid_for_seconds"), 0.0),
        _float_or(payload.get("freshness_window_sec"), 0.0),
        _float_or(latest_signal.get("freshness_window_sec"), 0.0),
        _float_or(pipeline_timing.get("freshness_window_sec"), 0.0),
        _float_or(latest_signal.get("pipeline_latency_sec"), 0.0) * 3.0,
        _float_or(pipeline_timing.get("pipeline_latency_sec"), 0.0) * 3.0,
    )
    current_execution_packet = _model_council_packet_from_payload(
        payload,
        require_live_overlay_truth=True,
    )

    def packet_valid_until(packet: Mapping[str, Any]) -> float:
        direct = _float_or(packet.get("valid_until_epoch") or packet.get("valid_until_epoch_sec"), 0.0)
        if direct > 0.0:
            return direct
        created = _float_or(packet.get("created_epoch") or packet.get("created_epoch_sec"), 0.0)
        ttl = _float_or(packet.get("ttl_sec") or packet.get("time_to_live_sec") or packet.get("freshness_window_sec"), 8.0)
        return created + max(0.1, ttl) if created > 0.0 else 0.0

    def packet_is_current(packet: Mapping[str, Any]) -> bool:
        valid_until = packet_valid_until(packet)
        if valid_until <= now_epoch:
            return False
        return True

    generic_no_packet_reasons = {
        "",
        "NONE",
        "WATCHING",
        "STUDY_PACKET_PUBLISHED",
        "EXECUTION_PACKET_NOT_PUBLISHED",
        "PG_EXECUTION_PACKET_V3_PUBLISHED",
        "EXECUTABLE_PACKET_CREATED",
    }

    def _upper_text(value: Any) -> str:
        return str(value or "").strip().upper()

    def _derive_no_current_packet_reason(
        *,
        row: Mapping[str, Any],
        execution: Mapping[str, Any],
        council: Mapping[str, Any],
        promotion_trace: Mapping[str, Any],
    ) -> tuple[str, str, dict[str, Any], dict[str, Any], float, float, str]:
        lane = _mapping_to_dict(
            row.get("execution_lane")
            or council.get("execution_lane")
            or promotion_trace.get("execution_lane")
        )
        sequence = _mapping_to_dict(
            row.get("sequence_context_readiness")
            or council.get("sequence_context_readiness")
            or council.get("sequence_context")
            or promotion_trace.get("sequence_context_readiness")
        )
        timing = _mapping_to_dict(
            row.get("timing_decision")
            or council.get("timing_decision")
            or promotion_trace.get("timing_decision")
        )
        entry_timing = _mapping_to_dict(timing.get("entry_timing"))
        entry_quality = _mapping_to_dict(
            row.get("entry_quality")
            or council.get("entry_quality")
            or promotion_trace.get("entry_quality")
        )
        trade_permission = _mapping_to_dict(
            row.get("trade_permission")
            or council.get("trade_permission")
            or promotion_trace.get("trade_permission")
        )
        timing_mode = _upper_text(
            promotion_trace.get("timing_mode")
            or row.get("timing_mode")
            or entry_timing.get("mode")
            or execution.get("timing_mode")
        )
        final_score = _float_or(
            promotion_trace.get("final_execution_score")
            or council.get("final_execution_score")
            or row.get("final_execution_score")
            or row.get("final_score"),
            0.0,
        )
        threshold = _float_or(
            promotion_trace.get("execution_threshold")
            or lane.get("required_score")
            or lane.get("threshold")
            or council.get("execution_threshold")
            or row.get("execution_threshold")
            or row.get("threshold"),
            0.0,
        )
        entry_quality_label = _upper_text(
            entry_quality.get("state")
            or entry_quality.get("grade")
            or entry_quality.get("entry_grade")
        )
        final_state = _upper_text(council.get("final_state") or execution.get("state"))
        has_promotion_evidence = bool(
            lane
            or sequence
            or timing
            or entry_quality
            or trade_permission
            or timing_mode
            or final_score > 0.0
            or threshold > 0.0
            or final_state not in {"", "WATCHING"}
        )

        if not has_promotion_evidence:
            return (
                "PROMOTION_CONTEXT_MISSING",
                "runtime trace must include promotion_trace or execution_lane before packet absence can be certified",
                sequence,
                lane,
                final_score,
                threshold,
                timing_mode,
            )

        if sequence and sequence.get("ready") is False:
            return (
                "SEQUENCE_CONTEXT",
                str(sequence.get("next_required") or "sequence context must be complete before packet publication"),
                sequence,
                lane,
                final_score,
                threshold,
                timing_mode,
            )
        if lane and lane.get("accepted") is False:
            return (
                "NO_EXECUTION_LANE_ACCEPTED",
                str(lane.get("next_required") or lane.get("reason") or "execution_lane.accepted must be true"),
                sequence,
                lane,
                final_score,
                threshold,
                timing_mode,
            )
        if timing_mode and timing_mode != "ENTER_NOW":
            return (
                f"TIMING_MODE_{timing_mode}",
                str(
                    entry_timing.get("next_condition")
                    or timing.get("next_required")
                    or "timing_mode must be ENTER_NOW"
                ),
                sequence,
                lane,
                final_score,
                threshold,
                timing_mode,
            )
        if promotion_trace.get("timing_has_explicit_expiry") is False:
            return (
                "MODEL_COUNCIL_EXPLICIT_EXPIRY_MISSING",
                "timing.expiry_seconds must be explicit before PG_EXECUTION_PACKET_V3 can be current",
                sequence,
                lane,
                final_score,
                threshold,
                timing_mode,
            )
        if threshold > 0.0 and final_score < threshold:
            return (
                "LANE_SCORE_BELOW_THRESHOLD",
                f"final_score={final_score:.4f} >= threshold={threshold:.4f}",
                sequence,
                lane,
                final_score,
                threshold,
                timing_mode,
            )
        permission_state = _upper_text(
            trade_permission.get("state")
            or trade_permission.get("permission")
            or trade_permission.get("status")
        )
        if (
            trade_permission.get("allowed") is False
            or trade_permission.get("accepted") is False
            or permission_state in {"DENIED", "BLOCKED", "WAIT", "WAITING", "NO_TRADE"}
        ):
            return (
                "TRADE_PERMISSION_DENIED",
                str(trade_permission.get("deny_reason") or trade_permission.get("reason") or "trade permission must clear"),
                sequence,
                lane,
                final_score,
                threshold,
                timing_mode,
            )
        if entry_quality_label in {"BAD_NOW", "LATE_ENTRY", "CHASE_ENTRY", "WATCH_ONLY", "EARLY_WATCH"}:
            return (
                "ENTRY_QUALITY",
                str(entry_quality.get("reason") or "entry quality must clear before packet publication"),
                sequence,
                lane,
                final_score,
                threshold,
                timing_mode,
            )
        publish_claim = _upper_text(
            promotion_trace.get("release_state")
            or promotion_trace.get("packet_result")
            or promotion_trace.get("promotion_result")
            or row.get("release_state")
            or row.get("packet_result")
        )
        if publish_claim in {
            "EXECUTION_PACKET_PUBLISHED",
            "PG_EXECUTION_PACKET_V3_PUBLISHED",
            "EXECUTABLE_PACKET_CREATED",
        }:
            prior_audit = _mapping_to_dict(
                row.get("promotion_failure_audit_v3")
                or promotion_trace.get("promotion_failure_audit_v3")
                or council.get("promotion_failure_audit_v3")
            )
            prior_blocker = _upper_text(
                promotion_trace.get("true_blocker")
                or promotion_trace.get("blocked_by")
                or promotion_trace.get("denied_at")
                or row.get("true_blocker")
                or row.get("denied_at")
                or prior_audit.get("top_blocker")
                or prior_audit.get("denied_at")
            )
            if prior_blocker.startswith("SHOOTER_SECOND_READ"):
                return (
                    "SHOOTER_PACKAGE_REPORT_PENDING",
                    "Shooter package reporter must publish a fresh allowed package report; expired packets remain rejected.",
                    sequence,
                    lane,
                    final_score,
                    threshold,
                    timing_mode,
                )
            if packet_valid_until(row) <= now_epoch:
                return (
                    "EXECUTION_PACKET_EXPIRED_BEFORE_SHOOTER_CONFIRMATION",
                    "Published PG_EXECUTION_PACKET_V3 expired before calibrated shooter confirmation; wait for the next fresh qualified read.",
                    sequence,
                    lane,
                    final_score,
                    threshold,
                    timing_mode,
                )
            return (
                "EXECUTION_PACKET_NOT_CURRENT_AFTER_PUBLICATION",
                (
                    "published PG_EXECUTION_PACKET_V3 must remain current through API and shooter handoff; "
                    "current payload must include the valid execution_packet or the exact expiry/runtime rejection"
                ),
                sequence,
                lane,
                final_score,
                threshold,
                timing_mode,
            )
        if final_state and final_state not in {"WATCHING", "EXECUTABLE"}:
            return (
                final_state,
                str(promotion_trace.get("next_required") or row.get("next_required") or "model council state must become executable"),
                sequence,
                lane,
                final_score,
                threshold,
                timing_mode,
            )
        return (
            "PG_EXECUTION_PACKET_V3_MISSING_AFTER_READY_GATES",
            "current PG_EXECUTION_PACKET_V3 must exist, or packet validation must attach the exact rejection before study-only publication",
            sequence,
            lane,
            final_score,
            threshold,
            timing_mode,
        )

    def _attach_demoted_packet_audit(
        *,
        row: dict[str, Any],
        execution: dict[str, Any],
        council: dict[str, Any],
        promotion_trace: dict[str, Any],
        reason: str,
        next_required: str,
        sequence: Mapping[str, Any],
        lane: Mapping[str, Any],
        final_score: float,
        threshold: float,
        timing_mode: str,
    ) -> None:
        release_condition = str(
            promotion_trace.get("release_condition")
            or row.get("release_condition")
            or next_required
        )
        council["true_blocker"] = reason
        council["denied_at"] = reason
        council["next_required"] = next_required
        council["release_condition"] = release_condition
        promotion_trace.update(
            {
                "denied_at": reason,
                "blocked_by": reason,
                "true_blocker": reason,
                "next_required": next_required,
                "release_condition": release_condition,
                "packet_result": "STUDY_PACKET_PUBLISHED",
            }
        )
        audit = build_promotion_failure_audit_v3(
            packet_id=str(row.get("packet_id") or promotion_trace.get("packet_id") or ""),
            candidate_id=str(row.get("candidate_id") or promotion_trace.get("candidate_id") or ""),
            promotion_trace=promotion_trace,
            sequence_context_readiness=sequence,
            execution_lane=lane,
            final_score=final_score,
            threshold=threshold,
            timing_mode=timing_mode,
            instrument_context=_mapping_to_dict(row.get("instrument_context")),
            packet_result="STUDY_PACKET_PUBLISHED",
            extra_source_fields={
                "api_normalizer": "demoted_missing_current_execution_packet",
                "release_state": promotion_trace.get("release_state"),
                "non_executable_state": promotion_trace.get("non_executable_state"),
                "blocked_by": reason,
                "true_blocker": reason,
            },
        )
        promotion_trace["promotion_failure_audit_v3"] = audit
        council["promotion_failure_audit_v3"] = audit
        council["promotion_trace"] = promotion_trace
        row["execution"] = execution
        row["model_council"] = council
        row["promotion_trace"] = promotion_trace
        row["promotion_failure_audit_v3"] = audit
        row["true_blocker"] = reason
        row["denied_at"] = reason
        row["next_required"] = next_required
        row["release_condition"] = release_condition
        row["packet_result"] = "STUDY_PACKET_PUBLISHED"

    def normalize(packet: Mapping[str, Any]) -> dict[str, Any]:
        row = _mapping_to_dict(packet)
        if not row:
            return {}
        council_for_dual = _mapping_to_dict(row.get("model_council"))
        dual_thesis_report = _mapping_to_dict(
            row.get("dual_thesis_report_v3")
            or council_for_dual.get("dual_thesis_report_v3")
            or _mapping_to_dict(row.get("allowance_package")).get("dual_thesis_report_v3")
            or _mapping_to_dict(row.get("opportunity_maturity")).get("dual_thesis_report_v3")
            or _mapping_to_dict(row.get("book_strategy")).get("dual_thesis_report_v3")
        )
        if dual_thesis_report:
            row["dual_thesis_report_v3"] = dual_thesis_report
            if council_for_dual:
                council_for_dual["dual_thesis_report_v3"] = dual_thesis_report
                row["model_council"] = council_for_dual
        row.setdefault("packet_type", "STUDY_PACKET")
        row.setdefault("schema_version", str(row.get("schema_version") or "PG_MODEL_COUNCIL_STUDY_V3"))
        study_execution = _mapping_to_dict(row.get("execution"))
        source_execution_state = _upper_text(study_execution.get("state") or "WATCHING")
        study_execution["enabled"] = False
        study_execution["state"] = "WATCHING" if source_execution_state == "EXECUTABLE" else source_execution_state
        study_execution["source_state"] = source_execution_state
        study_execution["study_only"] = True
        row["execution"] = study_execution
        created = _float_or(row.get("created_epoch") or row.get("created_epoch_sec"), 0.0)
        if created <= 0.0:
            created = now_epoch
            row["created_epoch"] = created
        if packet_valid_until(row) <= 0.0:
            row["valid_until_epoch"] = created + study_ttl_sec
            row["valid_until_epoch_sec"] = row["valid_until_epoch"]
            row["ttl_sec"] = study_ttl_sec
        if not current_execution_packet:
            execution = _mapping_to_dict(row.get("execution"))
            council = _mapping_to_dict(row.get("model_council"))
            promotion_trace = _mapping_to_dict(row.get("promotion_trace"))
            execution_state = str(execution.get("state") or "").strip().upper()
            council_state = str(council.get("final_state") or "").strip().upper()
            claims_executable = (
                bool(execution.get("enabled"))
                or execution_state == "EXECUTABLE"
                or council_state == "EXECUTABLE"
                or str(promotion_trace.get("packet_result") or "").strip().upper() == "PG_EXECUTION_PACKET_V3_PUBLISHED"
                or str(promotion_trace.get("promotion_result") or "").strip().upper() == "EXECUTABLE_PACKET_CREATED"
            )
            reason = _upper_text(
                promotion_trace.get("true_blocker")
                or promotion_trace.get("denied_at")
                or promotion_trace.get("blocked_by")
                or row.get("true_blocker")
                or row.get("denied_at")
                or row.get("blocked_by")
            )
            reason_is_generic = reason in generic_no_packet_reasons
            if claims_executable or reason_is_generic:
                (
                    reason,
                    next_required,
                    sequence,
                    lane,
                    final_score,
                    threshold,
                    timing_mode,
                ) = _derive_no_current_packet_reason(
                    row=row,
                    execution=execution,
                    council=council,
                    promotion_trace=promotion_trace,
                )
                execution["enabled"] = False
                execution["state"] = "WATCHING" if execution_state == "EXECUTABLE" else (execution_state or "WATCHING")
                if execution["state"] == "EXECUTABLE":
                    execution["state"] = "WATCHING"
                council["final_state"] = "WATCHING" if council_state == "EXECUTABLE" else (council_state or "WATCHING")
                if str(promotion_trace.get("promotion_result") or "").strip().upper() == "EXECUTABLE_PACKET_CREATED":
                    promotion_trace["promotion_result"] = council["final_state"]
                _attach_demoted_packet_audit(
                    row=row,
                    execution=execution,
                    council=council,
                    promotion_trace=promotion_trace,
                    reason=reason,
                    next_required=next_required,
                    sequence=sequence,
                    lane=lane,
                    final_score=final_score,
                    threshold=threshold,
                    timing_mode=timing_mode,
                )
                row["packet_type"] = "STUDY_PACKET"
                if str(row.get("schema_version") or "").strip() == PG_EXECUTION_PACKET_SCHEMA_VERSION:
                    row["schema_version"] = "PG_MODEL_COUNCIL_STUDY_V3"
                row["created_epoch"] = now_epoch
                row["created_epoch_sec"] = now_epoch
                row["valid_until_epoch"] = now_epoch + study_ttl_sec
                row["valid_until_epoch_sec"] = now_epoch + study_ttl_sec
                row["ttl_sec"] = study_ttl_sec
        council_for_permission = _mapping_to_dict(row.get("model_council"))
        dual_for_permission = _mapping_to_dict(
            row.get("dual_thesis_report_v3")
            or council_for_permission.get("dual_thesis_report_v3")
        )
        entry_permission_v3 = build_entry_permission_v3(
            dual_for_permission,
            execution_packet=current_execution_packet,
            allowance_package=_mapping_to_dict(row.get("allowance_package")),
        )
        row["entry_permission_v3"] = entry_permission_v3
        if dual_for_permission:
            dual_for_permission["entry_permission_v3"] = entry_permission_v3
            row["dual_thesis_report_v3"] = dual_for_permission
            if council_for_permission:
                council_for_permission["dual_thesis_report_v3"] = dual_for_permission
                council_for_permission["entry_permission_v3"] = entry_permission_v3
                row["model_council"] = council_for_permission
        return row

    def walk(candidate: Any, depth: int = 0) -> dict[str, Any]:
        if depth > 4 or not isinstance(candidate, Mapping):
            return {}
        row = _mapping_to_dict(candidate)
        for key in (
            "model_council_study_packet",
            "study_packet",
            "latest_model_council_study_packet",
            "latest_study_packet",
        ):
            nested = row.get(key)
            if isinstance(nested, Mapping):
                normalized = normalize(cast(Mapping[str, Any], nested))
                if normalized.get("packet_id") and packet_is_current(normalized):
                    return normalized
        for key in (
            "model_council_result",
            "model_council_state",
            "latest_signal",
            "tracking_summary",
        ):
            found = walk(row.get(key), depth + 1)
            if found:
                return found
        return {}

    found = walk(payload)
    if found:
        return found

    result = _mapping_to_dict(payload.get("model_council_result"))
    council = _mapping_to_dict(result.get("model_council") or payload.get("model_council"))
    if not result and not council:
        return {}
    session_id = str(payload.get("session_id") or result.get("session_id") or "").strip()
    state_version = int(_float_or(payload.get("state_version") or result.get("state_version"), int(time.time() * 1000)))
    packet_id = str(result.get("packet_id") or f"study_{session_id or 'session'}_{state_version}").strip()
    execution = _mapping_to_dict(result.get("execution"))
    state = str(
        execution.get("state")
        or council.get("final_state")
        or result.get("state")
        or "WATCHING"
    ).strip().upper()
    side = str(
        execution.get("side")
        or council.get("final_side")
        or result.get("side")
        or "HOLD"
    ).strip().upper()
    created_epoch = _float_or(
        payload.get("last_capture_epoch")
        or payload.get("last_capture_started_epoch")
        or result.get("created_epoch")
        or result.get("timestamp_epoch"),
        now_epoch,
    )
    valid_until_epoch = _float_or(
        payload.get("decision_valid_until_epoch")
        or result.get("valid_until_epoch")
        or result.get("valid_until_epoch_sec"),
        0.0,
    )
    if valid_until_epoch <= created_epoch:
        valid_until_epoch = created_epoch + study_ttl_sec
    dual_thesis_report = _mapping_to_dict(
        result.get("dual_thesis_report_v3")
        or council.get("dual_thesis_report_v3")
        or _mapping_to_dict(result.get("allowance_package")).get("dual_thesis_report_v3")
        or _mapping_to_dict(result.get("opportunity_maturity")).get("dual_thesis_report_v3")
        or _mapping_to_dict(result.get("book_strategy")).get("dual_thesis_report_v3")
    )
    return normalize(
        {
            "packet_id": packet_id,
            "session_id": session_id,
            "created_epoch": created_epoch,
            "created_epoch_sec": created_epoch,
            "valid_until_epoch": valid_until_epoch,
            "valid_until_epoch_sec": valid_until_epoch,
            "ttl_sec": max(0.1, valid_until_epoch - created_epoch),
            "execution": {"enabled": False, "state": state, "side": side if side in {"BUY", "SELL"} else None},
            "model_council": council,
            "dual_thesis_report_v3": dual_thesis_report,
            "promotion_trace": _mapping_to_dict(result.get("promotion_trace") or council.get("promotion_trace")),
            "block_reason": result.get("block_reason") or council.get("arbitration_reason") or "study packet synthesized from council state",
        }
    )


def model_council_study_packet_from_payload(payload: Mapping[str, Any]) -> dict[str, Any]:
    return _model_council_study_packet_from_payload(payload)


def _model_council_wait_reason_from_payload(payload: Mapping[str, Any], fallback: str = "MISSING_PACKET") -> str:
    row = _mapping_to_dict(payload)
    result = _mapping_to_dict(row.get("model_council_result"))
    if not result:
        result = _mapping_to_dict(_mapping_to_dict(row.get("latest_signal", {})).get("model_council_result"))
    council = _mapping_to_dict(result.get("model_council") or row.get("model_council"))
    execution = _mapping_to_dict(result.get("execution"))
    state = str(council.get("final_state") or execution.get("state") or "WAITING").strip().upper()
    side = _upper_action(council.get("final_side") or execution.get("side") or "HOLD", fallback="HOLD")
    reason = str(
        result.get("block_reason")
        or council.get("arbitration_reason")
        or row.get("block_reason")
        or fallback
    ).strip()
    return f"state={state or 'WAITING'} side={side} reason={reason or fallback}"


